export const intermediateUnitContent: Record<string, any> = {
  '1': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPresent continuous (I am doing)\nSarah is in her car.  She is on her way to work.\nShe’s driving to work. (= She is driving …)\nThis means: she is driving now, at the time of speaking.\nThe action is not finished. \nam/is/are + -ing is the present continuous: \nI\nhe/she/it\nwe/you/they\nam\nis\nare\n(= I’m)\n(= he’s etc.)\n(= we’re etc.)\ndriving\nworking\ndoing  etc.\nSteve is talking to a friend on the phone.  He says:\nSteve says ‘I’m reading …’ but he is not reading the book at \nthe time of speaking. \nHe means that he has started reading the book, but has not \nfinished it yet.  He is in the middle of reading it. \nI am doing something = I started doing it and I haven’t finished; I’m in the middle of doing it. \nPlease don’t make so much noise.  I’m trying to work. (not I try)\n‘Where’s Mark?’ \n‘He’s having a shower.’ (not He has a shower)\nLet’s go out now.  It isn’t raining any more. (not It doesn’t rain)\nHow’s your new job?  Are you enjoying it?\nWhat’s all that noise?  What’s going on?    or    What’s happening?\nSometimes the action is not happening at the time of speaking.  For example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nStudy this example situation:\nSome more examples: \nKate wants to work in Italy, so she’s learning Italian.\n(but perhaps she isn’t learning Italian at the time of speaking)\nSome friends of mine are building their own house.  They hope to finish it next summer.\nYou can use the present continuous with today / this week / this year etc. (periods around now):\na:  You’re working hard today. (not You work hard today)\nb:  Yes, I have a lot to do.\nThe company I work for isn’t doing so well this year.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe use the present continuous when we talk about a change that has started to happen.  We oft en use \nthese verbs in this way:\ngetting, becoming  \nchanging, improving\n \nstarting, beginning  \nincreasing, rising, falling, growing \nIs your English getting better? (not Does your English get better)\nThe population of the world is increasing very fast. (not increases)\nAt first I didn’t like my job, but I’m starting to enjoy it now. (not I start)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nPresent continuous and present simple ➜ Units 3–4\nPresent tenses for the future ➜ Unit 19\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nI’m reading a really good book at the moment.\nIt’s about a man who …\n2\n</div>",
    exercises: [{"id": "1.1", "question": "What’s happening in the pictures?  Choose from these verbs:", "type": "fill_blank", "options": {"verbs": ["cross", "hide", "scratch", "take", "tie", "wave"]}, "items": [{"label": "She’s taking\n a picture.", "answer": "", "isExample": true}, {"label": "He \n a shoelace.", "answer": "He’s tying", "isExample": false}, {"label": "the road.", "answer": "They’re crossing", "isExample": false}, {"label": "his head.", "answer": "He’s scratching", "isExample": false}, {"label": "behind a tree.", "answer": "She’s hiding", "isExample": false}, {"label": "to somebody.", "answer": "They’re waving", "isExample": false}]}, {"id": "1.2", "question": "The sentences on the right follow those on the left .  Which sentence goes with which?", "type": "match", "options": null, "items": [{"label": "Please don’t make so much noise.", "answer": "", "isExample": true}, {"label": "We need to leave soon.", "answer": "e", "isExample": false}, {"label": "I don’t have anywhere to live right now.", "answer": "g", "isExample": false}, {"label": "I need to eat something soon.", "answer": "a", "isExample": false}, {"label": "They don’t need their car any more.", "answer": "d", "isExample": false}, {"label": "Things are not so good at work.", "answer": "h", "isExample": false}, {"label": "It isn’t true what they say.", "answer": "b", "isExample": false}, {"label": "We’re going to get wet.\na I’m getting hungry.\nb They’re lying.\nc It’s starting to rain.\nd They’re trying to sell it.\ne It’s getting late.\nf  I’m trying to work. \ng I’m staying with friends.\nh The company is losing money.", "answer": "c", "isExample": false}, {"label": "f", "answer": "", "isExample": true}, {"label": "3", "answer": "e", "isExample": false}, {"label": "5", "answer": "a", "isExample": false}, {"label": "7", "answer": "h", "isExample": false}]}, {"id": "1.3", "question": "Write questions.  Use the present continuous.", "type": "fill_blank", "options": null, "items": [{"label": "What’s all that noise?  What’s happening?\n (what / happen?)", "answer": "", "isExample": true}, {"label": "What’s the matter?  \n (why / you / cry?)", "answer": "Why are you crying?", "isExample": false}, {"label": "Where’s your mother?  \n (she / work / today?)", "answer": "Is she working today?", "isExample": false}, {"label": "I haven’t seen you for ages.  \n (what / you / do / these days?)", "answer": "What are you doing these days?", "isExample": false}, {"label": "Amy is a student.  \n (what / she / study?)", "answer": "What is she studying?", "isExample": false}, {"label": "Who are those people?  \n (what / they / do?)", "answer": "What are they doing?", "isExample": false}, {"label": "I heard you started a new job.  \n (you / enjoy / it?)", "answer": "Are you enjoying it?", "isExample": false}, {"label": "We’re not in a hurry.  \n (why / you / walk / so fast?)", "answer": "Why are you walking so fast?", "isExample": false}]}, {"id": "1.4", "question": "Put the verb into the correct form, positive (I’m doing etc.) or negative (I’m not doing etc.).", "type": "fill_blank", "options": null, "items": [{"label": "Please don’t make so much noise.  I’m trying\n (I / try) to work.", "answer": "", "isExample": true}, {"label": "Let’s go out now.  It isn’t raining\n (it / rain) any more.", "answer": "", "isExample": false}, {"label": "You can turn off  the radio.  \n (I / listen) to it.", "answer": "I’m not listening", "isExample": false}, {"label": "Kate phoned last night.  She’s on holiday with friends.  \n (She / have) \na great time and doesn’t want to come back.", "answer": "She’s having", "isExample": false}, {"label": "Andrew started evening classes recently.  \n (He / learn) Japanese.", "answer": "He’s learning", "isExample": false}, {"label": "Paul and Sarah have had an argument and now \n (they / speak) \nto one another.", "answer": "they aren’t speaking", "isExample": false}, {"label": "The situation is already very bad and now \n (it / get) worse.", "answer": "it’s getting", "isExample": false}, {"label": "Tim \n (work) today.  He’s taken the day off .", "answer": "isn’t working", "isExample": false}, {"label": "(I / look) for Sophie.  Do you know where she is?", "answer": "I’m looking", "isExample": false}, {"label": "The washing machine has been repaired.  \n (It / work) now.", "answer": "It’s working", "isExample": false}, {"label": "(They / build) a new hospital.  It will be finished next year.", "answer": "They’re building", "isExample": false}, {"label": "Ben is a student, but he’s not very happy.  \n (He / enjoy) his course.", "answer": "He’s not enjoying", "isExample": false}, {"label": "(The weather / change).  Look at those clouds.  \nI think it’s going to rain.", "answer": "The weather’s changing", "isExample": false}, {"label": "Dan has been in the same job for a long time.  \n (He / start) to get bored \nwith it.\nExercises", "answer": "He’s starting", "isExample": false}, {"label": "2", "answer": "", "isExample": true}, {"label": "4", "answer": "I’m not listening", "isExample": false}, {"label": "6", "answer": "He’s learning", "isExample": false}]}],
  },
  '2': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent simple (I do)\nWe use the present simple to talk about things in general.  We use it to say that something happens all the \ntime or repeatedly, or that something is true in general:\nNurses look aft er patients in hospitals. \nI usually go away at weekends. \nThe earth goes round the sun. \nThe cafe opens at 7.30 in the morning.\nWe say:\nI work \nbut \n he works\nyou go \nbut \nit goes\nthey teach  \nbut \n my sister teaches\nI have  \nbut \nhe has\nFor spelling (-s or -es), see Appendix 6.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nStudy this example situation: \nAlex is a bus driver, but now he is in bed asleep.\nHe is not driving a bus. (He is asleep.)\nbut  He drives a bus.  He is a bus driver.\ndrive(s), work(s), do(es) etc. is the present simple:\nI/we/you/they\ndrive/work/do etc.\nhe/she/it\ndrives/works/does etc.\nWe use do/does to make questions and negative sentences:\ndo\ndoes\nI/we/you/they\nhe/she/it\nwork?\ndrive?\ndo?\nI/we/you/they\nhe/she/it\ndon’t\ndoesn’t\nwork\ndrive\ndo\nI come from Canada.  Where do you come from? \nI don’t go away very oft en. \nWhat does this word mean? (not What means this word?)\nRice doesn’t grow in cold climates. \nIn the following examples, do is also the main verb (do you do / doesn’t do etc.):\n‘What do you do?’ \n‘I work in a shop.’\nHe’s always so lazy.  He doesn’t do anything to help.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe use the present simple to say how oft en we do things:\nI get up at 8 o’clock every morning. \nHow oft en do you go to the dentist? \nJulie doesn’t drink tea very oft en. \nRobert usually goes away two or three times a year. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI promise / I apologise etc.\nSometimes we do things by saying something.  For example, when you promise to do something,\nyou can say ‘I promise … ’; when you suggest something, you can say ‘I suggest … ’:\nI promise I won’t be late. \n(not I’m promising)\n‘What do you suggest I do?’ \n‘I suggest that you …’\nIn the same way we say: I apologise … / I advise … / I insist … / I agree … / I refuse … etc.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nPresent simple and present continuous ➜ Units 3–4\nPresent tenses for the future ➜ Unit 19\n4\n</div>",
    exercises: [],
  },
  '3': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nHow long have you (been) … ? \n Unit 11\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent continuous and present simple 1\n(I am doing and I do)\nCompare:\npresent continuous (I am doing)\npresent simple (I do)\nWe use the continuous for things happening at \nor around the time of speaking.\nThe action is not complete.\nWe use the simple for things in general or things \nthat happen repeatedly.\npast\nnow\nfuture\nI am doing\n I do \npast\nnow\nfuture\nThe water is boiling.  Be careful.\nListen to those people.  What language \nare they speaking?\nLet’s go out.  It isn’t raining now.\n‘I’m busy.’ \n‘What are you doing?’\nI’m getting hungry.  Let’s go and eat.\nKate wants to work in Italy, so she’s \nlearning Italian.\nThe population of the world is \nincreasing very fast.\nWater boils at 100 degrees Celsius.\nExcuse me, do you speak English?\nIt doesn’t rain very much in summer.\nWhat do you usually do at weekends?\nI always get hungry in the aft ernoon.\nMost people learn to swim when they \nare children.\nEvery day the population of the world \nincreases by about 200,000 people.\nWe use the continuous for temporary situations \n(things that continue for a short time):\nI’m living with some friends until I find a \nplace of my own.\na: You’re working hard today.\nb: Yes, I have a lot to do.\nWe use the simple for permanent situations\n(things that continue for a long time):\nMy parents live in London.  They have \nlived there all their lives.\nJoe isn’t lazy.  He works hard most of \nthe time.\nSee Unit 1 for more information.\nSee Unit 2 for more information.\nI always do and I’m always doing\nI always do something = I do it every time:\nI always go to work by car. (not I’m always going)\nI’m always doing something = I do it too oft en or more oft en than normal. \nFor example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI’m always losing them = I lose them too oft en,\nor more oft en than normal.\nPaul is never satisfied.  He’s always complaining. (= he complains too much)\nYou’re always looking at your phone.  Don’t you have anything else to do? \nPresent continuous and simple 2 ➜ Unit 4\nPresent tenses for the future ➜ Unit 19\nI’ve lost my keys again.  I’m always losing them.\n6\n</div>",
    exercises: [],
  },
  '4': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent continuous and present simple 2\n(I am doing and I do)\nWe use continuous forms (I’m waiting, it’s raining etc.) for actions and happenings that have started but \nnot finished.  \nSome verbs (for example, know and like) are not normally used in this way.  We don’t say ‘I am knowing’, \n‘they are liking’.  We say ‘I know’, ‘they like’.\nThe following verbs are not normally used in the present continuous: \nlike \n \nwant \n \nneed \n \nprefer\nknow \n \nrealise \n \nunderstand \n \nrecognise\nbelieve \n \nsuppose \n \nremember \n \nmean\nbelong \n \nfit \n \ncontain \n \nconsist \n \nseem\nI’m hungry.  I want something to eat. (not I’m wanting)\nDo you understand what I mean?\nAnna doesn’t seem very happy right now.\nthink\nWhen think means ‘believe’ or ‘have an opinion’, we do not use the continuous:\nI think Mary is Canadian, but I’m not sure. (not I’m thinking)\nWhat do you think of my idea? (= what is your opinion?)\nWhen think means ‘consider’, the continuous is possible:\nI’m thinking about what happened.  I often think about it.\nNicky is thinking of giving up her job. (= she is considering it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nam/is/are being \nYou can say he’s being … , you’re being … etc. to say how somebody is behaving now:\nI can’t understand why he’s being so selfish.  He isn’t usually like that. \n(being selfish = behaving selfishly now)\n‘The path is icy.  Don’t slip.’ \n‘Don’t worry.  I’m being very careful.’ \nCompare:\nHe never thinks about other people.  He’s very selfish.  \n(= he is selfish generally, not only now)\nI don’t like to take risks.  I’m a very careful person.  \nWe use am/is/are being to say how a person is behaving (= doing something they can control) now. \nIt is not usually possible in other situations:\nSam is ill. (not is being ill)\nAre you tired? (not are you being tired)  \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nsee \n \nhear \n \nsmell \n \ntaste \n \nlook \n \nfeel\nWe normally use the present simple (not continuous) with see/hear/smell/taste:\nDo you see that man over there? (not are you seeing)\nThe room smells.  Let’s open a window.\nThis soup doesn’t taste very good.\nYou can use the present simple or continuous to say how somebody looks or feels now:\nYou look well today.    or    You’re looking well today. \nHow do you feel now?    or    How are you feeling now?\nbut\nI usually feel tired in the morning. (not I’m usually feeling)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nPresent continuous and simple 1 ➜ Unit 3\nhave ➜ Unit 17\nPresent tenses for the future ➜ Unit 19\n8\n</div>",
    exercises: [],
  },
  '5': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPast simple (I did)\nWolfgang Amadeus Mozart was an Austrian \nmusician and composer.  He lived from 1756 to \n1791.  He started composing at the age of five \nand wrote more than 600 pieces of music. \nHe was only 35 years old when he died. \nlived/started/wrote/was/died are all past simple \nStudy this example:\nVery oft en the past simple ends in -ed (regular verbs): \nI work in a travel agency now.  Before that I worked in a department store.\nThey invited us to their party, but we decided not to go.\nThe police stopped me on my way home last night.\nLaura passed her exam because she studied very hard. \nFor spelling (stopped, studied etc.), see Appendix 6. \nBut many verbs are irregular.  The past simple does not end in -ed.  For example:\nwrite → wrote \n Mozart wrote more than 600 pieces of music.\nsee   → saw \n We saw Alice in town a few days ago.\ngo   → went \n I went to the cinema three times last week.\nshut  → shut \nIt was cold, so I shut the window.\nFor a list of irregular verbs, see Appendix 1.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nIn questions and negative sentences we use did/didn’t + infinitive (enjoy/see/go etc.):\nI\nshe\nthey\nenjoyed\nsaw\nwent\ndid\nyou\nshe\nthey\nenjoy?\nsee?\ngo?\nI\nshe\nthey\ndidn’t\nenjoy\nsee\ngo\nI enjoyed the party a lot.  Did you enjoy it?\nHow many people did they invite to the wedding?\nI didn’t buy anything because I didn’t have any money. \n‘Did you go out?’ \n‘No, I didn’t.’\nSometimes do is the main verb in the sentence (did you do?, I didn’t do):\nWhat did you do at the weekend? (not What did you at the weekend?)\nI didn’t do anything. (not I didn’t anything)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nThe past of be (am/is/are) is was/were:\nI/he/she/it\nwas/wasn’t\nwas\nI/he/she/it?\nwe/you/they\nwere/weren’t\nwere\nwe/you/they?\nI was annoyed because they were late. \nWas the weather good when you were on holiday? \nThey weren’t able to come because they were so busy. \nI wasn’t hungry, so I didn’t eat anything. \nDid you go out last night or were you too tired? \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nPast simple and past continuous ➜ Unit 6\nPast simple and present perfect ➜ Units 12–14\n10\n</div>",
    exercises: [],
  },
  '6': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPast continuous (I was doing)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPast simple (I did) ➜ Unit 5\nI was doing (= in the middle of an action)\nI did (= complete action)\nWe were walking home when I met \nDan. (in the middle of walking home)\nWe walked home aft er the party last \nnight.  (= all the way, completely)\nKate was watching TV when we \narrived.\nKate watched TV a lot when she was ill \nlast year.\nStudy this example situation:\nYesterday Karen and Joe played tennis.  They started at \n10 o’clock and finished at 11.30.\nSo, at 10.30 they were playing tennis. \nthey were playing = \nthey were in the middle of playing, they had not finished \nwas/were + -ing is the past continuous:\nhe/she/it   was\nplaying\ndoing\nworking etc.\nwe/you/they \nwere\nI was doing something = I was in the middle of doing it at a certain time.  The action or situation started \nbefore this time, but had not finished:\nI started doing \nI was doing \nI finished doing\npast\npast\nnow\nThis time last year I was living in Hong Kong.\nWhat were you doing at 10 o’clock last night?\nI waved to Helen, but she wasn’t looking.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare I was doing (past continuous) and I did (past simple):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can say that something happened (past simple) in the middle of something else (past continuous):\nMatt phoned while we were having dinner.\nIt was raining when I got up. \nI saw you in the park yesterday.  You were sitting on the grass and reading a book.\nI hurt my back while I was working in the garden. \nBut we use the past simple to say that one thing happened aft er another:\nI was walking along the road when I saw Dan.  So I stopped, and we talked for a while.\nCompare:\n When Karen arrived, we were having \ndinner. (= we had already started before \nshe arrived)\n When Karen arrived, we had dinner. \n(= Karen arrived, and then we had \ndinner)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nSome verbs (for example, know and want) are not normally used in continuous forms (is + -ing, \nwas + -ing etc.).  See Unit 4A for a list of these verbs. \nWe were good friends.  We knew each other well. (not we were knowing)\nI was enjoying the party, but Chris wanted to go home. (not was wanting)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n12\n</div>",
    exercises: [],
  },
  '7': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPresent perfect 1 (I have done)\nTom can’t find his key. \nHe’s lost his key. (= He has lost …)\nhe has lost his key = \nhe lost it and he doesn’t have it now\nhave lost / has lost is the present perfect simple:\nI/we/they/you    have (= I’ve etc.)\nfinished\nlost\ndone\nbeen  etc.\n       he/she/it    has (= he’s etc.)\nStudy this example situation:\nWhen we say ‘something has happened’, this is usually new information:\nOw!  I’ve cut my finger.\nThe road is closed.  There’s been an accident. (= There has been …)\nPolice have arrested two men in connection with the robbery. \nWhen we use the present perfect, there is a connection with now.  The action in the past has a result now: \nTom has lost his key. (= he doesn’t have it now)\nHe told me his name, but I’ve forgotten it. (= I can’t remember it now)\nSally is still here.  She hasn’t gone out. (= she is here now)\nI can’t find my bag.  Have you seen it? (= do you know where it is now?)\nCompare gone (to) and been (to):\nJames is on holiday.  He has gone to Italy. (= he is there now or on his way there)\nAmy is back home now.  She has been to Italy. (= she has now come back)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can also use the past simple (did, went, had etc.) in the examples on this page.  So you can say:\nBen isn’t here.  He’s gone out.    or    He went out. \n‘Are you hungry?’ \n‘No, I’ve just had lunch.’    or    ‘No, I just had lunch.’ \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nYou can use the present perfect with just, already and yet.\nJust = a short time ago:\n‘Are you hungry?’ \n‘No, I’ve just had lunch.’\nHello.  Have you just arrived?\nAlready = sooner than expected:\n‘Don’t forget to pay the bill.’ \n‘I’ve already paid it.’\n‘What time is Mark leaving?’ \n‘He’s already left .’\nYet = until now.  We use yet to show that we are expecting something to happen. \nWe use yet in questions and negative sentences: \nHas it stopped raining yet? \nI’ve written the email, but I haven’t sent it yet.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nThe present perfect simple is have/has + past participle.  The past participle oft en ends in -ed \n(finished/decided etc.), but many verbs are irregular (lost/done/written etc.). \nFor a list of irregular verbs, see Appendix 1.\nPresent perfect ➜ Units 8, 11\nbeen to ➜ Units 8A, 126A\nPresent perfect continuous ➜ Units 9–10\nPresent perfect and past ➜ Units 12–14\nyet and already ➜ Unit 111\nAmerican English ➜ Appendix 7\nI’ve lost my key.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n14\n</div>",
    exercises: [],
  },
  '8': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent perfect 2 (I have done)\nDaVE: \nHave you travelled a lot, Jane?\nJaNE: \nYes, I’ve been to lots of places.\nDaVE: \nReally?  Have you ever been to China?\nJaNE: \nYes, I’ve been to China twice.\nDaVE: \nWhat about India?\nJaNE: \nNo, I haven’t been to India.\nWhen we talk about a period of time that continues from the past until now, we use the present \nperfect (have been / have travelled etc.).  Here, Dave and Jane are talking about the places Jane \nhas visited in her life, which is a period that continues until now.\nStudy this example conversation:\nIn the same way we say:\nHave you ever eaten caviar?\nWe’ve never had a car.\nI don’t know what the film is about.  I haven’t seen it.\nSusan really loves that book.  She’s read it three times. (She’s = She has)\nIt’s a really boring movie.  It’s the most boring movie I’ve ever seen. \nbeen (to) = visited:\nI’ve never been to Canada.  Have you been there? \npast\nnow\nJane’s life\n(a period until now)\nIn the following examples too, the speakers are talking about a period that continues until now \n(recently, in the last few days, so far, since I arrived etc.):\nHave you heard anything from Ben recently?\nI’ve met a lot of people in the last few days.\nEverything is going well.  There haven’t been any\nproblems so far.\nThe weather is bad here.  It’s (= It has) rained every \nday since I arrived. (= from when I arrived until now)\nIt’s good to see you again.  We haven’t seen each other for a long time.\nIn the same way we use the present perfect with today, this evening, this year etc. when these \nperiods are not finished at the time of speaking:\nI’ve drunk four cups of coff ee today.\nHave you had a holiday this year?\nI haven’t seen Tom this morning.  Have you?\nrecently\nin the last few days\nsince I arrived\npast\nnow\ntoday\npast\nnow\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say ‘It’s the (first) time something has happened’.  For example:\nDon is having a driving lesson.  It’s his first lesson.\nWe can say:\n It’s the first time he has driven a car. (not drives) \n \nor He hasn’t driven a car before.\nor He has never driven a car before.\nIn the same way we say:\nSarah has lost her passport again.  This is the second \ntime this has happened. (not happens)\nAndy is phoning his girlfriend again.  It’s the third \ntime he’s phoned her this evening.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nPresent perfect 1 ➜ Unit 7\nPresent perfect + for/since ➜ Units 11–12 \nPresent perfect and past ➜ Units 12–14\nThis is the first time\nI’ve driven a car.\n16\n</div>",
    exercises: [],
  },
  '9': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent perfect continuous (I have been doing)\nIt’s been raining.\nStudy this example situation:\nIs it raining?\nNo, but the ground is wet.\nIt’s been raining. (= It has been …) \nhave/has been + -ing is the present perfect continuous: \nI/we/they/you \nhave \n(= I’ve etc.)\n \nhe/she/it \nhas \n(= he’s etc.)\nbeen\ndoing\nworking \nlearning   etc.\nWe use the present perfect continuous for an activity that has recently stopped or just stopped:\nWhy are you out of breath?  Have you been running?\nPaul is very tired.  He’s been working hard.\nWhy are you so tired?  What have you been doing? \nI’ve been talking to Amanda and she agrees with me.\nWhere have you been?  I’ve been looking for you.\nhave/has been + -ing\npresent perfect continuous\nnow\nIt’s been raining for two hours.\nStudy this example situation:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nHow long have you been learning English? (= you’re still learning English)\nBen is watching TV.  He’s been watching TV all day.\nWhere have you been?  I’ve been looking for you for the last half hour.\nChris hasn’t been feeling well recently.\nYou can use the present perfect continuous for repeated actions:\nSilvia is a very good tennis player.  She’s been playing since she was eight.\nEvery morning they meet in the same cafe.  They’ve been going there for years.\nIt began raining two hours ago and it is still raining.\nHow long has it been raining?\nIt’s been raining for two hours. (= It has been …)\nWe use the present perfect continuous in this way, especially \nwith how long, for … and since …  .  The activity is still \nhappening (as in this example) or has just stopped.\nCompare I am doing and I have been doing:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nDon’t disturb me now.  I’m working.\nWe need an umbrella.  It’s raining.\nHurry up!  We’re waiting.\n I’ve been working hard.  Now I’m going\nto have a break.\nThe ground is wet.  It’s been raining.\n We’ve been waiting for an hour.\nI have been doing\npresent perfect continuous\nnow\nnow\nI am doing\npresent continuous\nPresent perfect continuous and simple ➜ Units 10–11\n Present perfect + for/since ➜ Units 11–12\n18\n</div>",
    exercises: [],
  },
  '10': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent perfect continuous and simple\n(I have been doing and I have done)\nCompare these two situations:\nThere is paint on Kate’s clothes.\nShe has been painting her bedroom.\nhas been painting is the present perfect \ncontinuous.\nWe are thinking of the activity.  It does not matter \nwhether it has been finished or not.  In this \nexample, the activity (painting the bedroom) has \nnot been finished.\nThe bedroom was green.  Now it is yellow.\nShe has painted her bedroom.\nhas painted is the present perfect simple.\nHere, the important thing is that something has \nbeen finished.  ‘She has painted’ is a completed \naction.  We are thinking about the result of \nthe activity (the painted bedroom), not the \nactivity itself.\nPresent perfect simple ➜ Units 7–8\nPresent perfect continuous ➜ Unit 9\nPresent perfect + for/since ➜ Units 11–12\nCompare these examples: \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nC\nMy hands are very dirty.  I’ve been \nrepairing my bike.\nJoe has been eating too much recently. \nHe should eat less.\nIt’s nice to see you again.  What have you \nbeen doing since we last met?\nWhere have you been?  Have you been \nplaying tennis?\nMy bike is OK again now.  I’ve repaired \nit. (= I’ve finished repairing it)\nSomebody has eaten all the chocolates.  \nThe box is empty.\nWhere’s the book I gave you?  What have \nyou done with it?\nHave you ever played tennis?\nWe use the continuous to say how long (for \nsomething that is still happening):\nHow long have you been reading that \nbook?\nAmy is writing emails.  She’s been writing \nemails all morning.\nThey’ve been playing tennis since 2 o’clock.\nI’m learning Arabic, but I haven’t been \nlearning it very long.\nWe use the simple to say how much, how many \nor how many times (for completed actions):\nHow many pages of that book have \nyou read?\nAmy has sent lots of emails this morning.\nThey’ve played tennis three times this \nweek.\nI’m learning Arabic, but I haven’t learnt \nvery much yet.\nSome verbs (for example, know) are not normally used in continuous forms (be + -ing):\nI’ve known about the problem for a long time. (not I’ve been knowing)\nHow long have you had that camera? (not have you been having)\nFor a list of these verbs, see Unit 4A.  For have, see Unit 17.\nBut note that you can use want and mean in the present perfect continuous (have/has been + -ing):\nI’ve been meaning to phone Anna, but I keep forgetting.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI’ve painted my bedroom.\nI’ve been painting \nmy bedroom.\n20\n</div>",
    exercises: [],
  },
  '11': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nhow long have you (been) … ?\nStudy this example situation:\nWe use the present perfect to talk about something that began in the past and still\ncontinues now.\nCompare the present and present perfect:\n Paul is in hospital.\nbut  \nHe’s been in hospital since Monday. (= He has been …)\n \n(not Paul is in hospital since Monday)\nWe know each other very well.\nbut  \nWe’ve known each other for a long time.\n \n(not We know)\nDo they have a car? \nbut  \nHow long have they had their car? \nShe’s waiting for somebody. \nbut  \nShe hasn’t been waiting very long.\nI’ve known / I’ve had / I’ve lived etc. is the present perfect simple. \nI’ve been learning / I’ve been waiting etc. is the present perfect continuous. \nWhen we ask or say ‘how long’, the continuous is more usual (see Unit 10): \nI’ve been learning English since January. \nIt’s been raining all morning. \nRichard has been doing the same job for 20 years. \n‘How long have you been driving?’ \n‘Since I was 17.’ \nSome verbs (for example, know and like) are not normally used in the continuous: \nHow long have you known Jane? (not have you been knowing) \n I’ve had these shoes for ages. (not I’ve been having) \nSee also Units 4A and 10C. For have, see Unit 17. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nDan and Kate are married.  They got married exactly \n20 years ago, so today is their 20th wedding anniversary. \nThey have been married for 20 years. \nWe say: They are married. (present)\nbut    How long have they been married?\n            (not How long are they married?) \n            They have been married for 20 years. \n            (not They are married for 20 years)\n(present perfect)\nYou can use either the continuous or simple with live and work: \nJulia has been living in this house for a long time.    or    Julia has lived …\nHow long have you been working here?    or    How long have you worked here?\nBut we use the simple (have lived etc.) with always:\nI’ve always lived in the country. (not always been living) \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI haven’t … since/for ➜ Unit 8B\nPresent perfect continuous ➜ Units 9–10\nfor and since ➜ Unit 12A\nWe say ‘I haven’t (done something) since/for …’ ( present perfect simple):\nI haven’t seen Tom since Monday. (= Monday was the last time I saw him)\nSarah hasn’t phoned for ages. (= the last time she phoned was ages ago)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\npresent perfect\nhe has been\nwe have known\nhave they had\nshe has been waiting\npast\nnow\npresent\nhe is\nwe know\ndo they have\nshe is waiting\n22\n</div>",
    exercises: [],
  },
  '12': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nHow long have you (been) … ? ➜ Unit 11\nfor and since when … ? and how long … ?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe use for and since to say how long something has been happening.\nWe use for + a period of time:\nWe’ve been waiting for two hours.\ntwo hours ago \n now\nfor two hours\nfor\ntwo hours\n20 minutes\nfive days\na long time\nsix months\n50 years\na week\nages\nyears\nSally has been working here for six \nmonths. (not since six months)\nI haven’t seen Tom for three days. \nWe use since + the start of a period:\nWe’ve been waiting since 8 o’clock.\n8 o’clock \n now\nsince 8 o’clock\nsince\n8 o’clock\nMonday\n12 May\nApril\n2001\nChristmas\nlunchtime\nwe arrived\nI got up\nSally has been working here since \nApril. (= from April until now)\nI haven’t seen Tom since Monday.\nWe oft en leave out for (but not usually in negative sentences):\nThey’ve been married for ten years.    or     They’ve been married ten years.\nThey haven’t had a holiday for ten years. (you need for)\nYou can use in instead of for in negative sentences (I haven’t … etc.):\nThey haven’t had a holiday in ten years. (= for ten years)\nWe do not use for + all … (all day / all my life etc.):\nI’ve lived here all my life. (not for all my life)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare when … ? (+ past simple) and how long … ? (+ present perfect):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\na:  When did it start raining? \nb: It started raining  an hour ago / at 1 o’clock. \na:  How long has it been raining? \nb:  It’s been raining  for an hour / since 1 o’clock.\na:  When did Joe and Kate first meet? \nb:  They first met \na:  How long have they known each other? \nb:  They’ve known each other \na long time ago. \nwhen they were at school.\n⎧\n⎨\n⎩\nfor a long time.\nsince they were at school.\n⎧\n⎨\n⎩\nWe say:\n \nit’s \n(= it is)\nor it’s been (= it has been)\na long time\nsix months (etc.)\nsince something happened\nIt’s two years since I last saw Joe.    or    It’s been two years since … \n(= I haven’t seen Joe for two years)\nIt’s ages since we went to the cinema.    or    It’s been ages since …\n(= We haven’t been to the cinema for ages)\nHow long is it since Mrs Hill died?    or    How long has it been since …\n(= when did she die?)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n24\n</div>",
    exercises: [],
  },
  '13': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPresent perfect and past 1 (I have done and I did)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nTen minutes later:\nThe present perfect (something has happened) is a present tense.  It tells us about the situation now. \n‘Tom has lost his key’ = he doesn’t have his key now (see Unit 7). \nThe past simple (something happened) tells us only about the past.  If somebody says ‘Tom lost his key’,\nwe don’t know whether he has the key now or not.  We know only that he lost it at some time in the past.\nCompare present perfect and past simple:\nThey’ve gone away.  They’ll be back on Friday. (they are away now)\nThey went away, but I think they’re back at home now. (not They’ve gone away)\nIt has stopped raining now, so we don’t need the umbrella. (it isn’t raining now)\nIt stopped raining for a while, but now it’s raining again. (not It has stopped)\nTom is looking for his key.  He can’t find it.\nHe has lost his key. (present perfect)\nThis means that he doesn’t have his key now.\nNow Tom has found his key.  He has it now.\nHas he lost his key?  No, he has found it.\nDid he lose his key?  Yes, he did.\nHe lost his key (past simple)\nbut now he has found it. (present perfect)\nYou can use the present perfect for new or recent happenings:\nI’ve repaired the washing machine.  It’s working OK now.\n‘Hannah has had a baby!  It’s a boy.’ \n‘That’s great news.’\nUsually, you can also use the past simple:\nI repaired the washing machine.  It’s working OK now.\nUse the past simple (not the present perfect) for things that are not recent or new:\nMozart was a composer.  He wrote more than 600 pieces of music.\n \n(not has been … has written)\nMy mother grew up in Italy. (not has grown)\nCompare:\nSomebody has invented a new type of washing machine.\nWho invented the telephone? (not has invented)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use the present perfect to give new information (see Unit 7).  But if we continue to talk about it, \nwe normally use the past simple:\na:  Ow!  I’ve burnt myself.\nb:  How did you do that?   (not have you done)\na:  I picked up a hot dish.   (not have picked)\na:  Look!  Somebody has spilt something on the sofa.\nb:  Well, it wasn’t me.  I didn’t do it.   (not hasn’t been … haven’t done)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nPast simple ➜ Unit 5\nPresent perfect ➜ Units 7–8\nPresent perfect and past 2 ➜ Unit 14 \nAmerican English ➜ Appendix 7\n26\n</div>",
    exercises: [],
  },
  '14': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPresent perfect and past 2 (I have done and I did)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe do not use the present perfect (I have done) when we talk about a finished time (for example,\nyesterday / last year / ten minutes ago etc.).  We use a past tense:\nIt was very cold yesterday. (not has been) \nPaul and Lucy arrived ten minutes ago. (not have arrived) \nDid you eat a lot of sweets when you were a child? (not have you eaten) \nI got home late last night.  I was very tired and went straight to bed. \nUse the past to ask When … ? or What time … ? :\nWhen did your friends arrive? (not have … arrived)\nWhat time did you finish work?\nCompare:\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPresent perfect\nTom has lost his key.  He can’t get \ninto the house.\nIs Carla here or has she left?\nPast simple\nTom lost his key yesterday.  \nHe couldn’t get into the house.\nWhen did Carla leave?\nPresent perfect (have done)\nI’ve done a lot of work today.\nWe use the present perfect for a period of time  \nthat continues until now.  For example: \ntoday / this week / since 2010.\nIt hasn’t rained this week.\nHave you seen Anna this morning? \n(it is still morning now)\nHave you seen Ben recently? \n(in the last few days or weeks)\nI’ve been working here since 2010. \n(I still work here now)\nI don’t know where Lisa is.  I haven’t seen \nher. (= I haven’t seen her recently)\nWe’ve been waiting for an hour.  \n(we are still waiting now)\nJack lives in Los Angeles.  He has lived \nthere for seven years.\nI’ve never ridden a horse. (in my life)\nIt’s the last day of your holiday.  You say:  \nIt’s been a really good holiday.  I’ve really \nenjoyed it.\nPast simple (did)\nI did a lot of work yesterday.\nWe use the past simple for a finished time in \nthe past.  For example: \nyesterday / last week / from 2010 to 2014.\nIt didn’t rain last week.\nDid you see Anna this morning? \n(it is now afternoon or evening)\nDid you see Ben on Sunday? \nI worked here from 2010 to 2014. \n(I don’t work here now)\na:  Was Lisa at the party on Sunday? \nb:  I don’t think so.  I didn’t see her.\nWe waited (or were waiting) for an \nhour. (we are no longer waiting)\nJack lived in New York for ten years. \nNow he lives in Los Angeles.\nI never rode a bike when I was a child.\nAfter you come back from holiday you say: \nIt was a really good holiday.  I really \nenjoyed it.\nPast simple ➜ Unit 5\nPresent perfect ➜ Units 7–8\nPresent perfect and past 1 ➜ Unit 13\npast\nnow\nunfinished\npast\nnow\nyesterday\nfinished\ntoday\n28\n</div>",
    exercises: [],
  },
  '15': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPast perfect continuous ➜ Unit 16\nIrregular verbs (gone/seen etc.) ➜ Appendix 1\nPast perfect (I had done)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nThe past perfect (simple) is had + past participle (gone/seen/finished etc.).\nSometimes we talk about something that happened in the past:\n Sarah arrived at the party.\nThis is the starting point of the story.  Then, if we want to talk about things that happened before this time, \nwe use the past perfect (had …):\nWhen Sarah arrived at the party, Paul had already gone home.\nSome more examples:\nWhen we got home last night, we found that somebody had broken into the flat.\nKaren didn’t come to the cinema with us.  She’d already seen the movie.\nAt first I thought I’d done the right thing, but I soon realised that I’d made a big mistake.\nThe people sitting next to me on the plane were nervous.  They hadn’t flown before.\n \nor They’d never flown before.\nSarah and Paul went to the same party last week, but they \ndidn’t see each other.  Paul left  the party at 10.30 and Sarah \narrived at 11 o’clock.\nSo when Sarah arrived at the party, Paul wasn’t there.\nHe had gone home.\nhad gone is the past perfect:\nI/we/they/you\nhe/she/it\nhad\n(= I’d etc.)\n(= he’d etc.)\ngone\nseen\nfinished  etc.\nCompare present perfect (have seen etc.) and past perfect (had seen etc.):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPresent perfect\nWho is that woman?  I’ve seen her before, \nbut I can’t remember where.\nWe aren’t hungry.  We’ve just had lunch.\nThe house is dirty.  They haven’t cleaned \nit for weeks.\nPast perfect\nI wasn’t sure who she was.  I’d seen her \nbefore, but I couldn’t remember where.\nWe weren’t hungry.  We’d just had lunch.\nThe house was dirty.  They hadn’t \ncleaned it for weeks.\nPast simple\na: Was Tom there when you arrived?\n \nb: Yes, but he left  soon aft erwards.\nKate wasn’t at home when I phoned.\n \nShe was at her mother’s house.\nPast perfect\na:  Was Tom there when you arrived?\n \nb:  No, he’d already left .\nKate had just got home when I phoned.\n \nShe’d been at her mother’s house.\nCompare past simple (left , was etc.) and past perfect (had left , had been etc.):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\npast  \n       now\nhave seen\npast  \nnow\nhad seen\nPAUL\nSARAH\n10.30\n11.00\nBye!\nHi!\n30\n</div>",
    exercises: [],
  },
  '16': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPast perfect continuous (I had been doing)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nSome more examples:\nMy hands were dirty because I’d been repairing my bike.\nTom was tired when he got home.  He’d been working hard all day.\nI went to Madrid a few years ago and stayed with a friend of mine.  She hadn’t been living \nthere very long, but she knew the city very well.\nYou can say that something had been happening before something else happened:\nWe’d been playing tennis for about half an hour when it started to rain heavily.\nYesterday morning I got up and looked out of the window. \nThe sun was shining, but the ground was very wet.\nIt had been raining.\nIt was not raining when I looked out of the window.\nThe sun was shining.  But it had been raining before.\nhad been -ing is the past perfect continuous:\nI/we/you/they\nhe/she/it\nhad\n(= I’d etc.)\n(= he’d etc.)\nbeen\ndoing\nworking\nplaying  etc.\nyesterday morning\nCompare have been -ing (present perfect continuous) and had been -ing (past perfect continuous):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPresent perfect continuous\nI hope the bus comes soon.  I’ve been \nwaiting for 20 minutes. (before now)\nJames is out of breath.  He’s been \nrunning. (= he has been …)\nPast perfect continuous\nAt last the bus came.  I’d been waiting \nfor 20 minutes. (before the bus came)\nJames was out of breath.  He’d been \nrunning. (= he had been …)\nCompare was -ing (past continuous) and had been -ing:\nIt wasn’t raining when we went out.  The sun was shining.  But it had been raining, \nso the ground was wet.\nKatherine was lying on the sofa.  She was tired because she’d been working hard.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSome verbs (for example, know) are not normally used in continuous forms (be + -ing):\nWe were good friends.  We had known each other for years. (not had been knowing)\nA few years ago Lisa cut her hair really short.  I was surprised because she’d always had \nlong hair. (not she’d been having)\nFor a list of these verbs, see Unit 4A.  For have, see Unit 17\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nPresent perfect continuous ➜ Units 9–10\nPast perfect simple ➜ Unit 15\nI have been -ing\nnow\npast\nI had been -ing\nnow\npast \n32\n</div>",
    exercises: [],
  },
  '17': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nhave and have got\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nhave and have got (= for possession, relationships, illnesses, appointments etc.)\nYou can use have or have got.  There is no difference in meaning.  You can say: \nThey have a new car.    or    They’ve got a new car. \nLisa has two brothers.    or    Lisa has got two brothers.\nI have a headache.    or    I’ve got a headache.\nOur house has a small garden.    or    Our house has got a small garden.\nHe has a few problems.    or    He’s got a few problems.\nI have a driving lesson tomorrow.    or    I’ve got a driving lesson tomorrow.\nWith these meanings (possession etc.), we do not use continuous forms (I’m having etc.):\nWe’re enjoying our holiday.  We have / We’ve got a nice room in the hotel.  \n(not We’re having a nice room)\nFor the past we use had (usually without got):\nLisa had long hair when she was a child. (not Lisa had got)\nIn questions and negative sentences there are three possible forms:\n   Do you have any questions?\nor    Have you got any questions?\nor    Have you any questions? (less usual)\n   Does she have a car?\nor    Has she got a car?\nor    Has she a car? (less usual)\n   I don’t have any questions.\nor    I haven’t got any questions.\nor    I haven’t any questions. (less usual)\n   She doesn’t have a car.\nor    She hasn’t got a car.\nor    She hasn’t a car. (less usual)\nIn past questions and negative sentences, we use did/didn’t: \nDid you have a car when you were living in Paris? \nI didn’t have my phone, so I couldn’t call you. \nLisa had long hair, didn’t she? \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nhave breakfast / have a shower / have a good time etc. \nWe also use have (but not have got) for things we do or experience.  For example: \nhave\nbreakfast / dinner / a cup of coffee / something to eat etc. \na bath / a shower / a swim / a break / a rest / a party / a holiday \nan accident / an experience / a dream\na look (at something) \na chat / a discussion / a conversation (with somebody)\ntrouble / difficulty / fun / a good time etc. \na baby (= give birth to a baby)\nHave got is not possible in these expressions.  Compare: \n Sometimes I have (= eat) a sandwich for my lunch. (not I’ve got) \nbut  \nI’ve got / I have some sandwiches.  Would you like one? \nYou can use continuous forms (I’m having etc.) with these expressions: \nWe’re enjoying our holiday.  We’re having a great time. \n‘Where’s Mark?’ \n‘He’s having a shower.’ \nIn questions and negative sentences we use do/does/did: \nI don’t usually have a big breakfast. (not I usually haven’t) \nWhere does Chris usually have lunch?\nDid you have trouble finding somewhere to stay? (not Had you)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nhave (got) to … ➜ Unit 31\nAmerican English ➜ Appendix 7\n34\n</div>",
    exercises: [],
  },
  '18': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nused to (do)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\na few years ago\nthese days\nNicola doesn’t travel much these days.\nShe prefers to stay at home. \nBut she used to travel a lot. \nShe used to go away two or three times a year. \nShe used to travel a lot = she travelled oft en in the past, but \nshe doesn’t do this any more. \nnow\npast\nshe doesn’t \ntravel\nshe used to travel\nI used to do something = I did it oft en in the past, but not any more:\nI used to play tennis a lot, but I don’t play very much now.\nDavid used to spend a lot of money on clothes.  These days he can’t aff ord it.\n‘Do you go to the cinema much?’ \n‘Not now, but I used to.’ \n(= I used to go)\nWe also use used to … for things that were true, but are not true any more: \nThis building is now a furniture shop.  It used to be a cinema. \nI used to think Mark was unfriendly, but now I realise he’s a very nice person.\nI’ve started drinking coff ee recently.  I never used to like it before. \nLisa used to have very long hair when she was a child. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\n‘I used to do something’ is past.  There is no present.  You cannot say ‘I use to do’. \nTo talk about the present, we use the present simple (I do). \nCompare: \npast\nhe used to play\nwe used to live\nthere used to be \npresent\nhe plays\nwe live\nthere is\nWe used to live in a small village, but now we live in a city.\nThere used to be four cinemas in the town.  Now there is only one.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nThe normal question form is did (you) use to … ? :\nDid you use to eat a lot of sweets when you were a child? (= did you do this oft en?)\nThe negative form is didn’t use to … (used not to … is also possible):\n I didn’t use to like him. (or I used not to like him.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nCompare I used to do and I was doing:\nI used to watch TV a lot. (= I watched TV oft en in the past, but I don’t do this any more)\nI was watching TV when Rob called. (= I was in the middle of watching TV)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nDo not confuse I used to do and I am used to doing (see Unit 61).  The structures and meanings \nare diff erent:\nI used to live alone. (= I lived alone in the past, but I no longer live alone.)\nI am used to living alone. (= I live alone, and it’s not a problem for me because I’ve lived \nalone for some time.)\nF\nPast continuous (I was doing) ➜ Unit 6\nwould (= used to) ➜ Unit 36\nbe/get used to (doing something) ➜ Unit 61\n36\n</div>",
    exercises: [],
  },
  '19': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPresent tenses (I am doing / I do) for the future\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent continuous (I am doing) with a future meaning\nI’m doing something (tomorrow etc.) = I have already decided and arranged to do it:\na: What are you doing on Saturday evening? (not What do you do)\nb: I’m going to the cinema. (not I go)\na: What time is Katherine arriving tomorrow?\nb: Half past ten.  We’re meeting her at the station.\nI’m not working tomorrow, so we can go out somewhere.\nSteve isn’t playing football next Saturday.  He’s hurt his leg.\nWe do not normally use will to talk about what we have arranged to do:\nWhat are you doing tonight? (not What will you do)\nAlex is getting married next month. (not will get)\nWe also use the present continuous for an action just before you start to do it.  This happens \nespecially with verbs of movement (go/come/leave etc.):\nI’m tired.  I’m going to bed now.  Goodnight. (not I go to bed now)\n‘Tina, are you ready yet?’ \n‘Yes, I’m coming.’ (not I come)\nThis is Ben’s diary for next week.\nHe is playing tennis on Monday aft ernoon.\nHe is going to the dentist on Tuesday morning.\nHe is meeting Kate on Friday.\nIn all these examples, Ben has already decided and\narranged to do these things.\nPresent simple (I do) with a future meaning\nWe use the present simple when we talk about timetables and programmes (for example, transport \nor cinema times):\nI have to go.  My train leaves at 11.30.\nWhat time does the film start tonight?\nThe meeting is at nine o’clock tomorrow.\nYou can use the present simple to talk about people if their plans are fixed like a timetable:\nI start my new job on Monday.\nWhat time do you finish work tomorrow?\nBut the continuous is more usual for other personal arrangements:\nWhat time are you meeting Kate tomorrow? (not do you meet)\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPresent continuous\nWhat time are you arriving?\nI’m going to the cinema this evening.\nPresent simple\nWhat time does the train arrive?\nThe film starts at 8.15.\nWhen you talk about appointments, lessons, exams etc., you can use I have or I’ve got:\nI have an exam next week.    or    I’ve got an exam next week.\nI’m going to ➜ Units 20, 23\nwill ➜ Units 21–22\nPresent simple aft er when and if ➜ Unit 25\n38\n</div>",
    exercises: [],
  },
  '20': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nI’m going to (do)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nI am going to do something = I have already decided to do it, I intend to do it:\n‘Are you going to eat anything?’ \n‘No, I’m not hungry.’\na: I hear Sarah won the lottery.  What is she going to do with the money? \nb: She’s going to buy a new car. \nI’m just going to make a quick phone call.  Can you wait for me? \nThis cheese smells horrible.  I’m not going to eat it. \nI am doing and I am going to do\nI am doing = it is already fixed or arranged.  For example, you have arranged to go somewhere \nor meet somebody: \nI’m leaving next week.  I’ve booked my flight. \nWhat time are you meeting Emily this evening? \nI am going to do something = I’ve decided to do it.  Maybe I’ve arranged to do it, maybe not.\na: Your shoes are dirty.\nb: Yes, I know.  I’m going to clean them.\n \n(= I’ve decided to clean them, but I haven’t arranged this with anybody)\nI don’t want to stay here.  Tomorrow I’m going to look for somewhere else to stay.\nCompare:\nI don’t know what I’m doing tomorrow. (= I don’t know my schedule or plans)\nI don’t know what I’m going to do about the problem. (= I haven’t decided what to do)\nOft en the diff erence is small and either form is possible.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nnow \n future\nThe man isn’t looking where he is going.\nHe is going to walk into the wall. \nWhen we say that ‘something is going to happen’, \nthe situation now makes this clear. \nThe man is walking towards the wall now, so we \ncan see that he is going to walk into it. \nYou can also say that ‘something is going to happen’ in the future.  For example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI was going to do something = I intended to do it, but didn’t do it:\nWe were going to travel by train, but then we decided to drive instead. \nI was just going to cross the road when somebody shouted ‘Stop!’ \nYou can say that ‘something was going to happen’ (but didn’t happen): \nI thought it was going to rain, but it didn’t. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nSome more examples: \nLook at those black clouds!  It’s going to rain.   (we can see the clouds now) \nI feel terrible.  I think I’m going to be sick.   (I feel terrible now) \nThe economic situation is bad now and things are going to get worse. \nI am doing (future) ➜ Unit 19A\nI will and I’m going to ➜ Unit 23\ngoing to\n40\n</div>",
    exercises: [],
  },
  '21': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nwill and shall 1\nWe use I’ll … (= I will) when we’ve just decided to do something.  When we say ‘I’ll do something’, \nwe announce our decision:\nOh, I left  the door open.  I’ll go and shut it.\n‘What would you like to drink?’ \n‘I’ll have orange juice, please.’\n‘Did you call Max?’ \n‘Oh no, I forgot.  I’ll call him now.’\nWe do not use the present simple (I do / I go etc.) in these sentences:\nI’ll phone him now. (not I phone him now)\nWe oft en use I think I’ll … / I don’t think I’ll … :\nI’m a little hungry.  I think I’ll have something to eat.\nI don’t think I’ll go out tonight.  I’m too tired.\nIn spoken English will not is usually won’t:\nI can see you’re busy, so I won’t stay long. (= I will not stay long)\nI am doing (future) ➜ Unit 19\nwill and shall 2 ➜ Unit 22\nI will and I’m going to ➜ Unit 23\nAmerican English ➜ Appendix 7\nWe oft en use I’ll in these situations:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nOﬀ ering to do something\nThat bag looks heavy.  I’ll help you with it. (not I help)\nAgreeing to do something\na:  Can you give Tom this book?\nb:  Sure, I’ll give it to him when I see him this aft ernoon.\nPromising to do something\nThanks for lending me the money.  I’ll pay you back on Friday.\nI won’t tell anyone what happened.  I promise.\nWe use won’t to say that somebody refuses to do something:\nI’ve tried to give her advice, but she won’t listen.\nThe car won’t start. (= the car ‘refuses’ to start)\nWill you (do something)? = please do it:\nWill you please turn the music down?  It’s too loud.\nWe do not use will to talk about what has been decided or arranged before:\nI’m going on holiday next Saturday. (not I’ll go)\nCompare:\nI’m meeting Kate tomorrow morning. (decided before)\na: I’ll meet you at half past ten, OK?\nb: Fine.  See you then.                                    (decided now)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe use shall mostly in the questions shall I … ? / shall we … ?\nWe use shall I … ? / shall we … ? to ask if it’s OK to do something or to ask for a suggestion:\nShall I open the window? (= do you want me to open it?)\nI’ve got no money.  What shall I do? (= what do you suggest?)\n‘Shall we go?’ \n‘Just a minute.  I’m not ready yet.’\n‘Where shall we have lunch?’ \n‘Let’s go to Marino’s.’\nCompare shall I … ? and will you … ? :\nShall I shut the door? (= do you want me to shut it?)\nWill you shut the door? (= I want you to shut it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI’ll help you.\nThe car won’t start.\n42\n</div>",
    exercises: [],
  },
  '22': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSome more examples:\nThey’ve been away a long time.  When they return, they’ll find a lot of changes here.\n‘Where will you be this time next year?’ \n‘I’ll be in Japan.’\nThat plate is hot. If you touch it, you’ll burn yourself.\nAnna looks completely diff erent now.  You won’t recognise her.\nWhen will you get your exam results?\nCompare:\nI think James is going to the party on Friday. (= I think he has already decided to go)\nI think James will go to the party on Friday. (= I think he will decide to go)\nWe do not use will to say what somebody has already arranged or decided to do:\nLisa is working next week. (not Lisa will work)\n Are you going to watch TV this evening? (not will you watch)\nSee Units 19–20.\nWe use will to say what we know or believe about the future (not what someone has already decided).  \nFor example:\nwill and shall 2\nJoe believes that Kate will pass \nthe driving test. \nHe is predicting the future.\nWhen we predict a future \nhappening or situation, we use \nwill/won’t.\nKate has her driving test next week. \nChris and Joe are talking about it.\nWe oft en use will (’ll) with:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nprobably\nI’m sure\nI think\nI don’t think\nI wonder\nI’ll probably be home late tonight.\nDon’t worry about the exam.  I’m sure you’ll pass.\nDo you think Sarah will like the present we bought her?\nI don’t think the exam will be very diff icult.\nI wonder what will happen.\nAft er I hope, we generally use the present:\nI hope Kate passes the driving test.\nI hope it doesn’t rain tomorrow.\nGenerally we use will to talk about the future, but sometimes we use will to talk about now:\nDon’t phone Amy now.  She’ll be busy. (= she’ll be busy now)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nNormally we use shall only with I and we.  You can say:\nI shall or I will (I’ll)             we shall or we will (we’ll)\nI shall be late this evening. (or I will be)\nWe shall probably go to France in June. (or We will probably go)\nIn spoken English we normally use I’ll and we’ll:\nWe’ll probably go to France.\nThe negative of shall is shall not or shan’t:\nI shan’t be here tomorrow. (or I won’t be)\nWe do not normally use shall with he/she/it/you/they:\nShe will be very angry. (not She shall be)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nwill and shall 1 ➜ Unit 21\nI will and I’m going to ➜ Unit 23\nwill be doing and will have done ➜ Unit 24\nwill have to ➜ Unit 31A\nThe future ➜ Appendix 3\nAmerican English ➜ Appendix 7\nYes, she’s a good driver.\nShe’ll pass easily.\nJOE\nCHRIS\nDo you think \nKate will pass?\n44\n</div>",
    exercises: [],
  },
  '23': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nSarah is talking to Helen:\nLater that day, Helen meets Max:\nI will and I’m going to\nCompare:\n‘Gary has been trying to contact you.’ \n‘Has he?  OK, I’ll call him.’\n‘Gary has been trying to contact you.’ \n‘Yes, I know.  I’m going to call him.’\n‘Anna is in hospital.’ \n‘Really?  I didn’t know.  I’ll go and visit her.’\n‘Anna is in hospital.’ \n‘Yes, I know.  I’m going to visit her this evening.’\nFuture actions\nCompare will and (be) going to:\nSARAH\nHELEN\nHELEN\nMAX\nwill (We’ll invite …)\nWe use will (We’ll invite …) to announce a \nnew decision.  The party is a new idea.\n(be) going to  (We’re going to invite …)\nWe use (be) going to when we have \nalready decided to do something. \nHelen had already decided to invite lots of \npeople before she spoke to Max.\ndecision\nnow\nWe’ll …\npast\nnow\nfuture\ndecision\nbefore\npast\nnow\nfuture\nWe’re going to …\nFuture happenings and situations (predicting the future)\nWe use both will and going to for future happenings and situations.  So you can say:\nI think the weather will be nice later.    or\nI think the weather is going to be nice later.\nThose shoes are well-made.  They’ll last a long time.    or\nThose shoes are well-made.  They’re going to last a long time.\nWhen we say something is going to happen, we believe this because of the situation now.  What is \nhappening now shows that something is going to happen in the future.  For example:\nLook at those black clouds.  It’s going to rain. (not it will rain) \n(we can see that it is going to rain – the black clouds are in the sky now) \nCompare:\nWe’re going to be late.  The meeting starts in five minutes and it takes 15 minutes to get there.  \n(it is clear now that we don’t have enough time to get there)\nJane will be late for the meeting.  She’s always late.\n(I believe this because I know what Jane is like)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI’m going to ➜ Unit 20\nwill ➜ Units 21–22\nThe future ➜ Appendix 3\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nThat’s a great idea.\nWe’ll invite lots of people.\nLet’s have a party.\nSarah and I have decided to have a party.\nWe’re going to invite lots of people.\n46\n</div>",
    exercises: [],
  },
  '24': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nThese people are standing in a queue to get \ninto the cinema.\nHalf an hour from now, the cinema will be full.\nEveryone will be watching the film.\nThree hours from now, the cinema will be empty.\nThe film will have finished.\nEveryone will have gone home.\nnow\nhalf an hour from now\nthree hours from now\nStudy this example situation:\nwill be doing and will have done\nI will be doing something (future continuous) = I will be in the middle of doing it:\nThis time next week I’ll be on holiday.  I’ll be lying on the beach or swimming in the sea.\nYou have no chance of getting the job.  You’ll be wasting your time if you apply.\nCompare will be (do)ing and will (do):\nDon’t phone between 7 and 8.  We’ll be eating.\nLet’s wait for Liz to arrive and then we’ll eat.\nCompare:\nAt 10 o’clock yesterday, Tina was in her off ice.  She was working. (past continuous)\nIt’s 10 o’clock now.  She is in her off ice.  She is working. (present continuous)\nAt 10 o’clock tomorrow, she will be in her off ice.  She will be working. (future continuous)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe also use will be -ing to talk about complete actions in the future.\nFor example:\nThe government will be making a statement\nabout the crisis later today.\nLater in the programme, I’ll be talking to the\nMinister of Education.\nThe team’s star player is injured and won’t \nbe playing in the game on Saturday.\nWhen we use it in this way, will be (doing) is similar to \nwill (do) and going to (do).\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI will have done something (future perfect) = it will be complete before a time in the future.  For example:\nSally always leaves for work at 8.30 in the morning.  She won’t be at home at 9 o’clock –\n \nshe’ll have gone to work.\nWe’re late.  The film will already have started by the time we get to the cinema.\nCompare:\nTed and Amy have been married for 24 years. (present perfect)\nNext year they will have been married for 25 years. (future perfect)\nWhen their son was born, they had been married for three years. (past perfect)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nwill ➜ Units 21–22\nby then / by the time ➜ Unit 120\nThe future ➜ Appendix 3\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nLater in the programme,\nI’ll be talking to …\n48\n</div>",
    exercises: [],
  },
  '25': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSome more examples:\nWe’ll go out when it stops raining. (not when it will stop)\nWhen you are here again, you must come and see us. (not When you will be)\nDon’t forget to lock the door when you go out. (not will go)\nThe same thing happens aft er while / before / aft er / as soon as / until:\nWhat are you going to do while I’m away? (not while I will be)\nBefore you go, there’s something I want to ask you. \nWait here until I come back.    or    … till I come back.\nwhen I do and when I’ve done\nif and when\nStudy this example:\n‘I’ll call you again later when I arrive’ is a sentence\nwith two parts:\nthe main part: \nI’ll call you again later \n \nand when … : \nwhen I arrive\nThe time is future (‘later’), but Amy says:\n \n… when I arrive (not when I will arrive)\nWe say\nwhen I do something (not will do)\nwhen something happens (not will happen)\nAmy is on a train.  She’s calling a friend.\nYou can also use the present perfect (have done) aft er when / aft er / until / as soon as:\nCan I have the newspaper when you’ve finished with it?\nDon’t say anything while Ian is here.  Wait until he has gone.\nWe use the present perfect to show that one thing is complete before the other.  The two things do not \nhappen together:\nWhen I’ve phoned Kate, we can go out.\n(= first I’ll phone Kate and aft er that we can go out)\nDo not use the present perfect if the two things happen together:\nWhen I phone Kate, I’ll ask her about the party. (not when I’ve phoned)\nIt is oft en possible to use either the present simple or the present perfect:\nI’ll come as soon as I finish. \nor \nI’ll come as soon as I’ve finished.\nYou’ll feel better aft er you have \nor \nYou’ll feel better aft er you’ve had\nsomething to eat.  \nsomething to eat.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nif and when\nAft er if, we normally use the present (if I do / if I see etc.) for the future:\nI’ll be angry if it happens again. (not if it will happen)\nHurry up!  If we don’t hurry, we’ll be late.\nWe use if (not when) for things that will possibly happen (or not happen):\nIf it is raining this evening, I won’t go out. (not when it is raining)\nDon’t worry if I’m late tonight. (not when I’m late)\nIf they don’t come soon, I’m not going to wait for them.  \nWe use when for things which are sure to happen.  Compare:\nI might go out later. (it’s possible)  If I go out, I’ll get some bread.\nI’m going out later. (for sure)  When I go out, I’ll get some bread.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI’ll call you again later when I arrive.\nif ➜ Units 38–40\neven if / even when ➜ Unit 112D\nunless → Unit 115\n50\n</div>",
    exercises: [],
  },
  '26': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\ncan, could and (be) able to\nWe use can to say that something is possible or allowed, or that somebody has the ability to do \nsomething.  We use can + infinitive (can do / can see etc.):\nWe can see the lake from our hotel.\n‘I don’t have a pen.’ \n‘You can use mine.’\nCan you speak any foreign languages?\nI can come and see you tomorrow if you like.\nThe word ‘dream’ can be a noun or a verb.\nThe negative is can’t (= cannot):\nI’m afraid I can’t come to the party on Friday.\nYou can say that somebody is able to do something, but can is more usual:\n We are able to see the lake from our hotel.\nBut can has only two forms: can (present) and could (past).  So sometimes it is necessary to use  \n(be) able to.  Compare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\ncould and was able to\nWe use could for general ability and with see, hear etc. :\nMy grandfather could speak five languages. \nI could see them, but not very clearly.  \nBut to say that somebody succeeded in doing something in a specific situation, we normally  \nuse was/were able to or managed to (not could):\nThe fire spread quickly, but everybody was able to escape. (not could escape)\nI didn’t know where Max was, but I managed to find him in the end. (not could find)\nCompare:\nJack was an excellent tennis player when he was younger.  He could beat anybody.\n(= he was good enough to beat anybody, he had the ability)\nbut  \nJack and Andy played a match yesterday.  Andy played well, but Jack managed to beat him.\n(= he succeeded in beating him this time)\nThe negative couldn’t (could not) is possible in all situations:\nMy grandfather couldn’t swim.\nI looked for Max everywhere, but I couldn’t find him.\nAndy played well, but he couldn’t beat Jack.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI can’t sleep.\nTom can come tomorrow.\nMaria can speak French, Spanish and \nEnglish.\nI haven’t been able to sleep recently.\nTom might be able to come tomorrow.\nApplicants for the job must be able to  \nspeak two foreign languages.\nSometimes could is the past of can.  We use could especially with:\nsee \n \nhear \n \nsmell \n \ntaste \n \nfeel \n \nremember \n \nunderstand\nWe had a lovely room in the hotel.  We could see the lake.\nAs soon as I walked into the room, I could smell gas.\nI was sitting at the back of the theatre and couldn’t hear very well.\nWe also use could to say that somebody had the ability to do something, or was allowed  \nto do something:\nMy grandfather could speak five languages.\nWe were totally free.  We could do what we wanted. (= we were allowed to do)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nA\ncould (do) and could have (done) ➜ Unit 27\nmust and can’t ➜ Unit 28\ncan/could you … ? ➜ Unit 37\n52\n</div>",
    exercises: [],
  },
  '27': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\ncould (do) and could have (done)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSometimes could is the past of can (see Unit 26):\nListen.  I can hear something. (now)\nI listened.  I could hear something. (past)\nBut could is not always past.  We also use could for possible actions now or in the future, especially to \nmake suggestions.  For example:\na: What shall we do tonight?\n \nb: We could go to the cinema.\na:  When you go to Paris next month, \nyou could stay with Sarah.\n \nb: Yes, I suppose I could.\nCan is also possible in these sentences (‘We can go to the \ncinema.’ etc.).  Could is less sure than can. \nWe also use could (not can) for actions that are not realistic.  For example:\n I’m so tired, I could sleep for a week. (not I can sleep for a week)\nCompare can and could:\nI can stay with Sarah when I go to Paris. (realistic)\nMaybe I could stay with Sarah when I go to Paris. (possible, but less sure)\nThis is a wonderful place.  I could stay here for ever. (unrealistic)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe also use could (not can) to say that something is possible now or in the future:\nThe story could be true, but I don’t think it is. (not can be true)\nI don’t know what time Lisa is coming.  She could get here at any time.\nCompare can and could:\nThe weather can change very quickly in the mountains. (in general)\nThe weather is nice now, but it could change later. (the weather now, not in general)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe use could have (done) to talk about the past.  Compare:\nI’m so tired, I could sleep for a week. (now)\nI was so tired, I could have slept for a week. (past)\nThe situation is bad, but it could be worse. (now)\nThe situation was bad, but it could have been worse. (past)\nSomething could have happened = it was possible, but did not happen:\nWhy did you stay at a hotel?  You could have stayed with me.\nDavid was lucky.  He could have hurt himself when he fell, but he’s all right.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI couldn’t do something = it would not be possible:\nI couldn’t live in a big city.  I’d hate it. (= it wouldn’t be possible for me)\nEverything is fine right now.  Things couldn’t be better.\nFor the past we use couldn’t have … (= would not have been possible):\nWe had a really good holiday.  It couldn’t have been better.\nNote that ‘I couldn’t do something’ has two meanings:\n(1) I couldn’t = it would not be possible now, I would not be able:\nI couldn’t run ten kilometres now.  I’m not fit enough. (= I would not be able)\n(2) I couldn’t = I was not able (past)\nI couldn’t run yesterday because I’d hurt my leg. (= I was not able)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\ncan and could ➜ Unit 26\ncouldn’t have (done) ➜ Unit 28B\ncould and might ➜ Unit 29C\ncould I/you … ? ➜ Unit 37\ncould with if ➜ Units 38C, 39E, 40D\nModal verbs (can/will etc.) ➜ Appendix 4\nWe could go to the cinema.\nWhat shall we\ndo tonight?\n54\n</div>",
    exercises: [],
  },
  '28': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nmust and can’t\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example:\nWe use must to say that we believe something is certain:\nYou’ve been travelling all day.  You must be tired.\n(travelling is tiring and you’ve been travelling all day, so you must be tired)\n‘Joe is a hard worker.’ \n‘Joe?  You must be joking.  He doesn’t do anything.’\nLouise must get very bored in her job.  She does the same thing every day.\nWe use can’t to say that we believe something is not possible:\nYou’ve just had lunch.  You can’t be hungry already. \n(we don’t expect people to be hungry immediately aft er a meal)\nThey haven’t lived here for very long.  They can’t know many people.\nThe structure is:\nyou/she/they (etc.)\nmust\ncan’t\nbe (tired / hungry / at work etc.)\nbe -ing (doing / going / joking etc.)\nget / know / have etc.\nStudy this example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nMartin and Lucy expected their friends to \nbe at home.\nThey rang the doorbell twice, but\nnobody has answered.  Lucy says:\nThey must have gone out.\n(= there is no other possibility)\nThere’s nobody at \nhome.  They must \nhave gone out.\nFor the past we use must have … and can’t have … :\nI lost one of my gloves.  I must have dropped it somewhere.\n(that’s the only explanation I can think of)\n‘We used to live very near the motorway.’ \n‘Did you?  It must have been noisy.’\nSarah hasn’t contacted me.  She can’t have got my message.  \nMax walked into a wall.  He can’t have been looking where he was going.\nThe structure is:\nI/you/he (etc.)\nmust\ncan’t\nhave\nbeen (asleep / at work etc.)\nbeen -ing (doing / looking etc.)\ngone / got / known etc.\nYou can use couldn’t have instead of can’t have:\nSarah couldn’t have got my message.\nMax couldn’t have been looking where he was going.\ncan’t (‘I can’t swim’ etc.) ➜ Unit 26\nmust (‘I must go’ etc.) ➜ Units 31–32\nModal verbs (can/will etc.) ➜ Appendix 4\nAmerican English ➜ Appendix 7\nMy house is very near the motorway.\nIt must be very noisy.\n56\n</div>",
    exercises: [],
  },
  '29': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nmay and might 1\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nWe use may or might to say that something is possible.  You can use may or might:\nIt may be true.    or    It might be true. (= perhaps it is true)\nShe might know.    or    She may know.\nThe negative forms are may not and might not:\nIt may not be true. (= perhaps it isn’t true)\nShe might not know. (= perhaps she doesn’t know)\nI/you/he (etc.)\nmay\nmight\n(not)\nbe (true / in his off ice etc.)\nbe -ing (doing / working / having etc.)\nknow / work / want etc.\nNote the diff erence between may be (2 words) and maybe (1 word):\nIt may be true. (may + verb)\n‘Is it true?’ \n‘Maybe.  I’m not sure.’ (maybe = it’s possible, perhaps)\nYou are looking for Ben.  Nobody is sure where he is, but you get some suggestions.\n(= perhaps he is in his off ice)\n(= perhaps he is having lunch)\n(= perhaps she knows)\nFor the past we use may have … or might have … :\na: I wonder why Kate didn’t answer her phone.\nb: She may have been asleep. (= perhaps she was asleep)\na: I can’t find my phone anywhere.\nb: You might have left  it at work. (= perhaps you left  it at work)\na:  Why wasn’t Amy at the meeting yesterday?\nb: She might not have known about it. (= perhaps she didn’t know)\na:  I wonder why David was in such a bad mood yesterday.\nb: He may not have been feeling well. (= perhaps he wasn’t feeling well)\nI/you/he (etc.)\nmay\nmight\n(not) have\nbeen (asleep / at home etc.)\nbeen -ing (doing / working / feeling etc.)\nknown / had / wanted / left  etc.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\ncould is similar to may and might:\nIt’s a strange story, but it could be true. (= it is possible that it’s true)\nYou could have left  your phone at work. (= it’s possible that you left  it there)\nBut couldn’t (negative) is diff erent from may not and might not.  Compare:\nSarah couldn’t have received my message.  Otherwise she would have replied.\n(= it is not possible that she got my message)\nWhy hasn’t Sarah replied to my message?  I suppose she might not have received it.\n(= it’s possible that she didn’t receive it – perhaps she did, perhaps she didn’t)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\ncould ➜ Unit 27\nmay/might 2 ➜ Unit 30\nmay I … ? ➜ Unit 37C         \nmight with if ➜ Units 30B, 38C, 40D\nModal verbs (can/will etc.) ➜ Appendix 4\nWhere’s Ben?\nHe might be having lunch.\nAsk Kate.  She might know.\nHe may be in his oﬀ ice.\n58\n</div>",
    exercises: [],
  },
  '30': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nmay and might 2\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe use may and might to talk about possible actions or happenings in the future:\nI haven’t decided where to go on holiday.  I may go to Ireland. (= perhaps I will go there)\nTake an umbrella with you.  It might rain later. (= perhaps it will rain)\nThe bus isn’t always on time.  We might have to wait a few minutes.\n(= perhaps we will have to wait)\nThe negative forms are may not and might not (mightn’t):\nAmy may not go out tonight.  She isn’t feeling well. (= perhaps she will not go out)\nThere might not be enough time to discuss everything at the meeting. \n(= perhaps there will not be enough time)\nCompare:\nI’m going to buy a car. (for sure)\nI may buy a car.    or    I might buy a car. (possible)\nUsually you can use may or might.  So you can say:\nI may go to Ireland.    or    I might go to Ireland.\nJane might be able to help you.    or    Jane may be able to help you.\nBut we use might (not may) when the situation is not real:\n If they paid me better, I might work harder. (not I may work)\nThis situation (If they paid me better) is not real.  They do not pay me well, so I’m not going \nto work harder.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare may/might be -ing and will be -ing:\nDon’t phone at 8.30.  I’ll be watching the football on TV.\nDon’t phone at 8.30.  I might be watching the football on TV. (= perhaps I’ll be \nwatching it)\nWe also use may/might be -ing for possible plans.  Compare:\nI’m going to Ireland soon. (for sure)\nI might be going (or I may be going) to Ireland soon. (possible)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nmight as well\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nHelen and Clare have just missed the bus.  \nThe buses run every hour.\nWe might as well do something = we should \ndo it because there is no better alternative. \nThere is no reason not to do it.\nYou can also use may as well.\na: What time are you going out?\nb: Well, I’m ready, so I might as well go now.    or    … I may as well go now.\nBuses are so expensive these days, you might as well get a taxi. \n(= taxis are as good, no more expensive than buses)\nwill be -ing ➜ Unit 24\nmay/might 1 ➜ Unit 29\nmay I … ? ➜ Unit 37\nmight with if ➜ Units 38C, 40D\nWhat shall we do?  Shall we walk?\nWe might as well.  It’s a nice day and\nI don’t want to wait here for an hour.\n60\n</div>",
    exercises: [],
  },
  '31': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nhave to and must\nI have to do something = it is necessary to do it, I am obliged to do it:\nYou can’t turn right here.  You have to turn left .\nI have to wear glasses for reading.\nRobert can’t come out with us this evening.\n \nHe has to work late.\nLast week Tina broke her arm and had to go to hospital.\nI haven’t had to go to the doctor for ages.\nWe use do/does/did in questions and negative sentences \n(for the present and past simple):\nWhat do I have to do to get a new driving licence? (not What have I to do?)\nKaren doesn’t have to work Saturdays. (not Karen hasn’t to)\n‘Did you have to wait a long time for a bus?’ \n‘No, only ten minutes.’\nYou can say I’ll have to … , I’m going to have to … , I might have to … , I may have to … :\nThey can’t repair my computer, so I’ll have to buy a new one.    or    \n… I’m going to have to buy a new one.\nWe might have to change our plans.    or    We may have to change …\n(= it’s possible that we will have to change them)\nMust is similar to have to.  You can say:\nIt’s later than I thought.  I must go.   or   I have to go.\nYou can use must or have to when you give your own opinion (for example, to say what you think is \nnecessary, or to recommend someone to do something):\nI haven’t spoken to Sue for ages.  I must phone her. / I have to phone her. \n(= I say this is necessary)\nMark is a really nice person.  You must meet him. / You have to meet him. \n(= I recommend this)\nWe use have to (not usually must) to say what someone is obliged to do.  This is a fact, not the speaker’s \nown opinion:\nI have to work from 8.30 to 5.30 every day. (a fact, not an opinion)\nJane has to travel a lot for her work.\nBut we use must in written rules and instructions:\nApplications for the job must be received by 18 May.\nSeat belts must be worn.\nWe use had to (not must) to talk about the past:\nI went to the meeting yesterday, but I had to leave early. (not I must)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nMustn’t and don’t have to are completely diff erent:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can use have got to instead of have to.  You can say:\nI’ve got to work tomorrow.    or     I have to work tomorrow.\nWhen has Helen got to go?    or     When does Helen have to go?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nYou mustn’t do something = don’t do it:\nYou must keep this a secret.  You mustn’t tell anyone. (= don’t tell anyone)\nI promised I would be on time.  I mustn’t be late. (= I must be on time)\nYou don’t have to do something = you don’t need to do it (but you can if you want):\nYou don’t have to come with me.  I can go alone.\nI don’t have to be at the meeting, but I’m going anyway.\nmust (‘You must be tired’) ➜ Unit 28\nmust/mustn’t/needn’t ➜ Unit 32\n, not the speaker’s \nYou have to turn left  here.\n62\n</div>",
    exercises: [],
  },
  '32': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nmust     mustn’t     needn’t\nmust (‘You must be tired’) ➜ Unit 28\nhave to and must ➜ Unit 31\nModal verbs (can/could/will/would etc.) ➜ Appendix 4\nAmerican English ➜ Appendix 7\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nmust and mustn’t\nYou must do something = it is necessary that you do it:\nDon’t tell anybody what I said.  You must keep it a secret.\nWe don’t have much time.  We must hurry.\nYou mustn’t do something = don’t do it:\nYou must keep it a secret.  You mustn’t tell anyone. (= don’t tell anyone)\nWe must be very quiet.  We mustn’t make any noise.\nneedn’t and don’t need to\nYou needn’t do something = it’s not necessary to do it (but you can if you want):\nWe have plenty of time.  We needn’t hurry. (= it is not necessary to hurry)\nJoe can stay here.  He needn’t come with us. (= it is not necessary for him to come)\nYou can also use don’t/doesn’t need to:\n We don’t need to hurry.\nNote that we say ‘don’t need to do’, but ‘needn’t do’ (without to).\nCompare needn’t and mustn’t:\nYou needn’t tell Steve.  I can tell him myself. (= it is not necessary)\nYou mustn’t tell Steve.  I don’t want him to know. (= don’t tell him)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nneedn’t have (done)\nStudy this example situation:  \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nneedn’t have (done) and didn’t need to (do) \nHe needn’t have done something = he did it, but now we know that it was not necessary:\nWhy did he get up at 5 o’clock?  He needn’t have got up so early.  He could have stayed \nin bed longer.\nHe didn’t need to do something = it was not necessary to do it.  It doesn’t matter whether he did it or not:\nHe didn’t need to get up early, so he didn’t.\n He didn’t need to get up early, but it was a beautiful morning, so he did.\nYou can also say ‘He didn’t have to get up’ in these examples.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nCompare needn’t (do) and needn’t have (done):\nEverything will be OK.  You needn’t worry. (it is not necessary)\nEverything was OK.  You needn’t have worried. (you worried, but it was not necessary)\nWe needn’t have reserved a table.\nPaul and Sarah reserved a table at \na restaurant.\nBut when they went to the restaurant, \nit was almost empty.\nThey needn’t have reserved a table.\nThis means: they reserved a table, \nbut now they know this was not \nnecessary.\nCan I reserve a table for two?\n64\n</div>",
    exercises: [],
  },
  '33': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nshould 1\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nYou should do something = it is a good thing to do or the right thing to do.\nYou can use should to give advice or to give an opinion:\nYou look tired.  You should go to bed.\nThe government should do more to improve\nschools.\na: Should we invite Stephanie to the party?\nb: Yes, I think we should.\nThe man on the motorbike should be wearing a helmet.\nYou shouldn’t do something = it isn’t a good thing to do:\nYou shouldn’t believe everything you read in newspapers.\nWe oft en use should with I think / I don’t think / Do you think … ? :\nI think the government should do more to improve schools.\nI don’t think you should work so hard.\na: Do you think I should apply for this job? \nb: Yes, I think you should.\nShould is not as strong as must or have to:\nYou should apologise. (= it would be a good thing to do)\nYou must apologise. / You have to apologise. (= you have no alternative)\nWe use should when something is not right or what we expect: \nWhere’s Tina?  She should be here by now.\n(= she isn’t here yet, and this is not normal)\nThe price on this packet is wrong.  It should be £2.50, not £3.50.\nWe also use should to say that we expect something to happen:\nHelen has been studying hard for the exam, so she should pass. \n(= I expect her to pass)\nThere are plenty of hotels in the town.  It shouldn’t be hard to find a place to stay.\n(= I don’t expect it to be hard)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou should have done something = you didn’t do it, but it would have been a good thing to do:\nYou missed a great party last night.  You should have come.  Why didn’t you?\n(= you didn’t come, but it would have been good to come)\nI wonder why they’re so late.  They should have been here long ago.\nYou shouldn’t have done something = you did it, but it wasn’t a good thing to do:\nI’m feeling sick.  I shouldn’t have eaten so much. (= I ate too much)\nShe shouldn’t have been listening to our conversation.  It was private.\n(= she was listening)\nCompare should (do) and should have (done):\nYou look tired.  You should go to bed now.\nYou went to bed very late last night.  You should have gone to bed earlier.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nought to …\nYou can use ought to instead of should in the sentences on this page. \nWe say ‘ought to do’ (with to):\nDo you think I ought to apply for this job? (= Do you think I should apply … ?)\nJack ought not to go to bed so late. (= Jack shouldn’t go …)\nIt was a great party last night.  You ought to have come. (= You should have come)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nshould  2 ➜ Unit 34\nshould and had better ➜ Unit 35B\nModal verbs (can/could/will/would etc.) ➜ Appendix 4\n66\n</div>",
    exercises: [],
  },
  '34': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nshould 2\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nYou can use should after:\ninsist        demand        recommend        suggest        propose\nI insisted that he should apologise.\nDoctors recommend that everyone should eat plenty of fruit.\nWhat do you suggest we should do?\nMany people are demanding that something should be done about the problem.\nalso\nIt’s important/vital/necessary/essential that … should … :\nIt’s essential that everyone should be here on time.\nYou can also leave out should in the sentences in section A.  So you can say:\nIt’s essential that everyone be here on time. (= … that everyone should be here …)\nI insisted that he apologise. (= … that he should apologise)\nWhat do you suggest we do?\nMany people are demanding that something be done about the problem.\nThis form (be/do/apologise etc.) is called the subjunctive.  It is the same as the infinitive (without to).\nYou can also use normal present and past forms:\nIt’s essential that everyone is here on time.\nI insisted that he apologised.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe do not use to … with suggest.  You can say:\n What do you suggest we should do?\nor \n \nWhat do you suggest we do? (but not What do you suggest us to do?)\nJane won the lottery. \n \nI suggested that she should buy a car with the money she won.\nor \n \nI suggested that she buy a car.\nor \n \nI suggested that she bought a car. (but not I suggested her to buy)\nYou can also use -ing after suggest (What do you suggest doing?).  See Unit 53.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can use should after some adjectives, especially:\nstrange        odd        funny        typical        natural        interesting        surprised        surprising\nIt’s strange that he should be late.  He’s usually on time.\nI was surprised that he should say such a thing.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nYou can say ‘if something should happen …’ .  For example:\nWe have no jobs at present, but if the situation should change, we will contact you.\nYou can also begin with should (Should something happen …):\nShould the situation change, we will contact you.\nThis means the same as ‘If the situation changes, …’ .  With should, the speaker feels that the \npossibility is smaller. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nYou can use I should … / I shouldn’t … to give advice.  For example:\n‘Shall I leave now?’ \n‘No, I should wait a bit.’ (=  I advise you to wait)\nHere, I should … = ‘I would … if I were you’, ‘I advise you to …’ .  Two more examples:\n‘I’m going out now.  Is it cold outside?’ \n‘Yes, I should wear a coat.’\nI shouldn’t stay up too late.  You have to be up early tomorrow.\nF\nshould 1 ➜ Unit 33\nAmerican English ➜ Appendix 7\n68\n</div>",
    exercises: [],
  },
  '35': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nshould 1 ➜ Unit 33\nI’d better …     it’s time …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nhad better (I’d better / you’d better etc.)\nI’d better do something = it is advisable to do it.  If I don’t do it, there will be a problem or a danger:\nI have to meet Amy in ten minutes.  I’d better go now or I’ll be late.\n‘Shall I take an umbrella?’ \n‘Yes, you’d better.  It might rain.’\nWe’d better stop for petrol soon.  The tank is almost empty.\nThe negative is I’d better not (= I had better not):\na: That jacket looks good on you.  Are you going to buy it? \nb: I’d better not.  It’s very expensive.\nYou don’t look very well.  You’d better not go out tonight.\nRemember that:\nI’d better = I had better, you’d better = you had better etc.\nI’d better phone Chris, hadn’t I?\nWe had better go now.\nHad is normally past, but we use had better for the present or future, not past.\nI’d better go now / tomorrow.\nWe say ‘I’d better do’ (not to do).\nIt might rain.  We’d better take an umbrella. (not We’d better to take)\nhad better and should\nHad better is similar to should but not exactly the same.  We use had better only for a specific situation, \nnot for things in general.  You can use should in all types of situations to give an opinion or give advice:\nIt’s late.  You’d better go.    or    You should go. (a specific situation)\nYou’re always at home.  You should go out more often. (in general – not ‘had better go’)\nAlso, with had better, there is always a danger or a problem if you don’t follow the advice. \nShould means only ‘it is a good thing to do’.  Compare:\nIt’s a great film.  You should go and see it. (but no problem if you don’t)\nThe film starts at 8.30.  You’d better go now or you’ll miss the beginning.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nit’s time …\nYou can say It’s time (for somebody) to … :\nIt’s time to go home. / It’s time for us to go home.\nBut you can also say:\n It’s late.  It’s time we went home.\nWhen we use it’s time + past (‘it’s time we went’ etc.), the meaning is present, not past:\nIt’s time they were here.  Why are they so late? (not It’s time they are here)\nIt’s time somebody did something = they should have already done it or started it.  \nWe often use this structure to criticise or to complain:\nThis situation can’t continue.  It’s time you did something about it.\nHe’s very selfish.  It’s time he realised that he isn’t the most important person in the world.\nYou can also say It’s about time … :\nJack is a great talker, but it’s about time he did something instead of just talking.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\n70\n</div>",
    exercises: [],
  },
  '36': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nwould\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe use would (’d) / wouldn’t when we imagine a situation or action (= we think of something that is\nnot real):\nIt would be nice to buy a new car, but we can’t aff ord it.\nI’d love to live by the sea.\na: Shall I tell Chris what happened?\nb: No, I wouldn’t say anything.\n(= I wouldn’t say anything in your situation)\nWe use would have (done) when we imagine something\nthat didn’t happen in the past:\nThey helped us a lot.  I don’t know what we’d have done without their help.\n \n(we’d have done = we would have done)\nIt’s a shame you didn’t see the film.  You would have liked it.\nI didn’t tell Sam what happened.  He wouldn’t have been pleased.\nCompare would (do) and would have (done):\nI would call Lisa, but I don’t have her number. (now)\n \nI would have called Lisa, but I didn’t have her number. (past)\nI’m not going to invite them to the party.  They wouldn’t come anyway.\nI didn’t invite them to the party.  They wouldn’t have come anyway.\nWe oft en use would in sentences with if (see Units 38–40):\nI would call Lisa if I had her number.\nI would have called Lisa if I’d had her number.\nCompare will (’ll) and would (’d):\nI’ll stay a little longer.  I’ve got plenty of time.\n \nI’d stay a little longer, but I really have to go now. (so I can’t stay longer)\nI’ll call Lisa.  I have her number.\n \nI’d call Lisa, but I don’t have her number. (so I can’t call her)\nSometimes would/wouldn’t is the past of will/won’t. \nCompare: \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\npresent \npast\nTOM: I’ll call you on Sunday. \n→ \nTom said he’d call me on Sunday.\naMY:  I promise I won’t be late. \n→ \nAmy promised that she wouldn’t be late.\nLISa:  Oh, no!  The car won’t start. → \nLisa was annoyed because her car wouldn’t start.\nSomebody wouldn’t do something = he/she refused to do it:\nI tried to warn him, but he wouldn’t listen to me. (= he refused to listen)\nThe car wouldn’t start. (= it ‘refused’ to start)\nYou can also use would to talk about things that happened regularly in the past:\nWhen we were children, we lived by the sea.  In summer, if the weather was fine, we would \nall get up early and go for a swim. (= we did this regularly)\nWhenever Richard was angry, he would walk out of the room.\nWith this meaning, would is similar to used to (see Unit 18):\nWhenever Richard was angry, he used to walk out of the room.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nwill ➜ Units 21–22\nwould … if ➜ Units 38–40\nwish … would ➜ Unit 41\nwould like ➜ Units 37D, 58 \nwould prefer / would rather ➜ Unit 59\nModal verbs ➜ Appendix 4\n72\n</div>",
    exercises: [],
  },
  '37': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\ncan/could/would you … ? etc.\n(Requests, oﬀ ers, permission and invitations)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAsking people to do things (requests)\nWe use can or could to ask people to do things:\n Can you wait a moment, please?\nor \n \nCould you wait a moment, please?\nHelen, can you do me a favour?\nExcuse me, could you tell me how to get to the bus station?\nYou can say Do you think you could … ? :\nDo you think you could take me to the airport?\n(not Do you think you can)\nCould you open the door, please?\nAsking for things\nTo ask for something, we use Can (I) have … ? / Could (I) have … ? or Can (I) get …?:\n(in a shop) \nCan I have these postcards, please?    or    Can I get these postcards, please?\n(in a restaurant) \nCould we have the menu, please?    or    Can we have the menu, please?\nMay I have … ? is also possible:\nMay I have these postcards, please?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nAsking to do things\nWe use can I or could I to ask to do something:\n(on the phone)  Hello, can I speak to Steve, please?\n‘Could I use your phone charger?’ \n‘Sure.’\nDo you think I could borrow your bike?\nMay is also possible:\n May I ask you a question?  \nMay is more formal than can or could.\nYou can also say: \nDo you mind if I … ? \nIs it all right if I …? / Is it OK if I … ?\nDo you mind if I use your phone charger?\n‘Is it all right if I sit here?’ \n‘Yes, of course.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nOff ering and inviting\nYou can use Can I … ? to off er to do something:\n‘Can I help you?’    ‘No, it’s OK.  I can manage, thanks.’\n‘Can I get you some coff ee?’ \n‘That would be nice.’\nTo off er or to invite, we use Would you like … ? (not Do you like):\n‘Would you like some coff ee?’ \n‘No, thanks.’\n‘Would you like to eat with us tonight?’ \n‘That would be great.’\nI’d like … (= I would like) is a polite way to say what you want:\n(at a tourist information oﬀ ice)  I’d like some information about hotels, please.\n(in a shop)  I’d like to try on this jacket, please.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\ncan and could ➜ Units 26–27\nmind -ing ➜ Unit 53\nwould like ➜ Units 55A, 58B\nModal verbs (can/could/will/would etc.) ➜ Appendix 4\nCould I use your phone charger?\n74\n</div>",
    exercises: [],
  },
  '38': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nif I do … and if I did …  \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nCompare these examples:\n(1) LISa: Shall we take the bus or the train?\nJESS: If we take the bus, it will be cheaper.\nFor Jess, it is possible that they will take the bus, \nso she says:\nIf we take the bus, it will be …\n(2) Lisa and Jess decide to take the train.\nLater, Jess talks to Joe. \nJOE: How are you going to travel?\nJESS: We’re going to take the train.  If we took the bus,\nit would be cheaper, but the train is quicker.  \nNow Jess knows they are not going to take the bus, \nso she says:\nIf we took the bus, it would be …\nLISA\nJESS\nIf we take the bus, \nit will be cheaper.\nJOE\nJESS\nIf we took the bus, it would be cheaper.\nWhen we talk about something that will not happen, \nor we don’t expect that it will happen, we use\nif + past (if we went / if there was etc.).\nBut the meaning is not past:\nWhat would you do if you won a lot of money?\n(I don’t really expect this to happen)\nIf there was an election tomorrow, who would\nyou vote for?\n(there will not be an election tomorrow)\nI’d be surprised if they didn’t come to the party.\n(I expect them to come)\nCompare if I find and if I found:\nI think I left  my watch at your house.  If you find it, can you call me?\nbut\nIf you found a wallet in the street, what would you do with it?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe do not normally use would in the if-part of the sentence:\nI’d be very scared if somebody pointed a gun at me. (not if somebody would point)\nIf we went by bus, it would be cheaper. (not If we would go)\nIn the other part of the sentence (not the if-part) we use would (’d) / wouldn’t:\nI’d be (= I would be) scared if somebody pointed a gun at me.\nI’m not going to bed yet.  I’m not tired.  If I went to bed now, I wouldn’t sleep.\nWhat would you do if you were bitten by a snake? \nCould and might are also possible:\nIf I won a lot of money, I might buy a house.\n(= it is possible that I would buy a house)\nIf it stopped raining, we could go out.\n(= we would be able to go out)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nwill ➜ Units 21–22\nif and when ➜ Unit 25D\nwould ➜ Unit 36\nif I knew ➜ Unit 39\nif … was/were ➜ Unit 39C\nif I had known ➜ Unit 40\nIf I won a lot of money …\n76\n</div>",
    exercises: [],
  },
  '39': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nif I knew …   I wish I knew …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nSarah wants to phone Paul, but she can’t do this because\nshe doesn’t know his number.  She says:\nI’d phone him if I knew his number.\n(I’d phone = I would phone)\nSarah doesn’t know Paul’s number, so she says ‘if I knew’.\nShe imagines what she would do if she knew his number.\nWhen we imagine a situation like this, we use if + past (if I knew / if you were / if we didn’t etc.). \nBut the meaning is present, not past:\nThere are many things I’d like to do if I had more time. (but I don’t have time)\nIf I didn’t want to go to the party, I wouldn’t go. (but I want to go)\nIf you were in my position, what would you do?\nIt’s a pity he can’t drive.  It would be useful if he could.\nWe use the past in the same way aft er wish (I wish I knew / I wish you were etc.). \nWe use wish to say that we regret something, that something is not as we would like it to be:\nI wish I knew Paul’s phone number.\n(= I don’t know it and I regret this)\nDo you ever wish you could fly?\n(you can’t fly)\nIt’s very crowded here.  I wish there weren’t \nso many people. (there are a lot of people)\nI wish I didn’t have to work tomorrow, but\nunfortunately I do.\nCompare:\nI’m glad I live here. (I live here and that’s good)\nI wish I lived here. (I don’t live here unfortunately)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI wish I had an umbrella.\nAft er if and wish, you can use were instead of was (if I were / I wish it were etc.). \nYou can also use was.  So you can say:\nIf I were you, I wouldn’t buy that coat. \n  or \n  If I was you, …\nI’d go for a walk if it weren’t so cold. \nor \n… if it wasn’t so cold.\nI wish Anna were here. \nor \nI wish Anna was here.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe do not usually say ‘if … would’.  We use would (’d) in the other part of the sentence:\nIf I were rich, I would travel a lot. (not If I would be rich)\n Who would you ask if you needed help? (not  if you would need) \nIn the same way we say:\nI wish I had something to read.   (not I wish I would have)\nI wish she were here now.   (not I wish she would be)\nFor ‘I wish … would …’ see Unit 41.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nCould sometimes means ‘would be able to’ and sometimes ‘was/were able to’:\nShe could get a better job  \n(she could get = she would be able to get)\nif she could speak another language. \n(if she could speak = if she was able to speak)\nI wish I could help you. \n(I wish I could = I wish I was able)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\ncould ➜ Units 26–27\nif I do / if I did ➜ Unit 38\nif I had known / I wish I had known ➜ Unit 40\nwish ➜ Unit 41\n… if I knew his number …\n78\n</div>",
    exercises: [],
  },
  '40': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nif I had known …     I wish I had known …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nLast month Gary was in hospital for a few days.  Rachel didn’t know this.  \nA few days ago they met by chance.  Rachel said:\nIf I’d known you were in hospital, I would have gone to visit you.\n(= I didn’t know, so I didn’t go to visit you)\nIf I’d known = If I had known.  This tells us that she didn’t know before.\nWe use if + had (’d) … to talk about the past (if I’d known / if you’d done etc.):\nI didn’t see you when you passed me in the street.  If I’d seen you, I would have said hello. \nThey didn’t go out last night.  They would have gone out if they hadn’t been so tired.  \n(but they were tired)\nIf you’d been looking where you were going, you wouldn’t have walked into the wall.  \n(but you weren’t looking)\nThe view was wonderful.  I would have taken some pictures if I’d had (= if I had had) \na camera with me. (but I didn’t have a camera) \nCompare:\nI’m not hungry.  If I was hungry, I would eat something. (now)\nI wasn’t hungry.  If I had been hungry, I would have eaten something. (past)\nWe do not say ‘if something would have happened’.  We use would in the other part of the sentence:\nIf I had seen you, I would have said hello. (not If I would have seen you)\nThe short form ’d can be would or had:\nIf I’d seen you,                   (I’d seen = I had seen)\n \nI’d have said hello.\n(I’d have said = I would have said)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use had done/known/been etc. in the same way after wish.\nI wish something had happened = I am sorry that it didn’t happen\nI wish something hadn’t happened = I am sorry that it happened\nI wish I’d known that Gary was ill.  I would have gone to see him. (but I didn’t know)\nI feel sick.  I wish I hadn’t eaten so much. (I ate too much)\nDo you wish you’d studied science instead of languages? (you didn’t study science)\nCompare:\nI’m glad I saw him. (= I saw him)\nI wish I’d seen him. (= I didn’t see him)\nWe do not say ‘wish … would have …’ .\nThe weather was cold.  I wish it had been warmer. (not I wish it would have been)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCompare would (do) and would have (done):\nIf I’d gone to the party last night, I would be tired now. (I am not tired now – present)\nIf I’d gone to the party last night, I would have met lots of people. (I didn’t meet lots  \nof people – past)\nCompare would have, could have and might have:\nIf the weather hadn’t been so bad,\nwe would have gone out.\nwe could have gone out.\n(= we would have been able to go out)\nwe might have gone out.\n(= maybe we would have gone out)\n⎧\n⎪\n⎪\n⎨\n⎪\n⎪\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nhad done ➜ Unit 15\n if I do / if I did ➜ Unit 38\nif I knew / I wish I knew ➜ Unit 39\nwish ➜ Unit 41\n80\n</div>",
    exercises: [],
  },
  '41': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nwish\nWe say ‘wish somebody luck / all the best / success’ etc. :\nI wish you all the best in the future.\nI saw Mark before the exam and he wished me luck. \nWe say ‘wish somebody something’ (luck, happiness etc.), but we do not say ‘I wish something happens’.  \nWe use hope in this situation:\nI’m sorry you’re not well.  I hope you feel better soon. (not I wish you feel)\nCompare I wish and I hope:\nI wish you a pleasant stay at this hotel.\nI hope you enjoy your stay at this hotel. (not I wish you enjoy)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe also use wish to say that we regret something, that something is not as we would like it.\nWhen we use wish in this way, we use the past (knew/lived etc.), but the meaning is present:\nI wish I knew what to do about the problem. (but I don’t know)\nI wish you didn’t have to go so soon. (but you have to go)\nDo you wish you lived near the sea? (you don’t live near the sea)\nJack’s going on a trip to Mexico soon.  I wish I was going too. (but I’m not going)\nTo say that we regret something that happened before, we use wish + had known / had said etc. :\nI wish I’d known about the party.  I’d have gone if I’d known. (but I didn’t know)\nIt was a stupid thing to say.  I wish I hadn’t said it. (but I said it)\nSee also Units 39 and 40.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI wish I could (do something) = I regret that I cannot do it:\nI’m sorry you have to go.  I wish you could stay longer. (but you can’t)\nI’ve met that man before.  I wish I could remember his name. (but I can’t)\nI wish I could have (done something) = I regret that I could not do it:\nI hear the party was great.  I wish I could have gone. (but I couldn’t go)\nYou can say ‘I wish something would happen’.  For example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nD\nIt’s been raining all day.  Tanya doesn’t like it.  She says:\nI wish it would stop raining.\nTanya would like the rain to stop, but this will probably not happen.\nWe use I wish … would when we would like something to happen\nor change.\nWe oft en use I wish … would to complain about a situation:\nThe phone has been ringing for five minutes.  I wish somebody would answer it.\nI wish you’d do (= you would do) something instead of just sitting and doing nothing.\nYou can use I wish … wouldn’t … to complain about things that people do repeatedly:\nI wish you wouldn’t keep interrupting me. (= please stop interrupting me)\nWe use I wish … would … to say that we want something to happen.  We do not use I wish … would … \nto say how we would like things to be.  Compare:\nI wish Sarah would come. (= I want her to come)\nbut \nI wish Sarah was (or were) here now. (not I wish Sarah would be)\nI wish somebody would buy me a car.\nbut \nI wish I had a car. (not I wish I would have)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nwould ➜ Unit 36\nI wish I knew ➜ Unit 39\nI wish I was / I wish I were ➜ Unit 39C\nI wish I had known ➜ Unit 40\nI wish it would stop raining.\n82\n</div>",
    exercises: [],
  },
  '42': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPassive 1 (is done / was done)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example:\nWhen we use an active verb, we say what the subject does:\nMy grandfather was a builder.  He built this house in 1981.\nIt’s a big company.  It employs two hundred people.\nWhen we use a passive verb, we say what happens to the subject:\n‘How old is this house?’ \n‘It was built in 1981.’\nTwo hundred people are employed by the company.\nThis house was built in 1981.\n‘This house was built’ is passive.\nCompare active and passive:\nSomebody built  this house\nobject\n in 1981. (active)\n  subject\nThis house\nsubject\n was built in 1981. (passive)\nWhen we use the passive, who or what causes the action is oft en unknown or unimportant:\nA lot of money was stolen in the robbery. (somebody stole it, but we don’t know who)\nIs this room cleaned every day? (does somebody clean it? – it’s not important who)\nIf we want to say who does or what causes the action, we use by:\nThis house was built by my grandfather.\nTwo hundred people are employed by the company.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nThe passive is be (is/was etc.) + past participle (done/cleaned/seen etc.):\n \n(be) done \n \n(be) cleaned \n \n(be) damaged \n \n(be) built \n \n(be) seen etc.\nThe past participle oft en ends in -ed (cleaned/damaged etc.), but many important verbs are \nirregular (built/done/stolen etc.).  See Appendix 1.\nCompare active and passive, present simple and past simple:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nPresent simple  \nactive: \nclean(s) / see(s) etc.\npassive:  am/is/are + cleaned/seen etc.\nMany accidents are caused by careless driving. \n I’m not invited to parties very oft en. \n How is this word pronounced? \nSomebody cleans this room  every day.\nThis room  is cleaned every day.\nPast simple\nactive: \ncleaned/saw etc.\npassive:     was/were + cleaned/seen etc.\nSomebody cleaned this room  yesterday.\nThis room  was cleaned yesterday.\n We were woken up by a loud noise during the night.\n‘Did you go to the party?’ \n‘No, I wasn’t invited.’\nHow much money was stolen in the robbery?\nPassive 2–3 ➜ Units 43–44 \n by ➜ Unit 128\n84\n</div>",
    exercises: [],
  },
  '43': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPassive 2 (be done / been done / being done)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPresent perfect\nactive: \n have/has + done etc. \nThe room looks nice.  Somebody has cleaned it  .\npassive:    have/has been + done etc. \nThe room looks nice.  It  has been cleaned.\nHave you heard?  The trip has been cancelled.\nHave you ever been bitten by a dog?\n‘Are you going to the party?’ \n‘No, I haven’t been invited.’\nPast perfect\nactive: \n had + done etc. \nThe room looked nice.  Somebody had cleaned it  .\npassive:    had been + done etc. \nThe room looked nice. It  had been cleaned.\nThe vegetables didn’t taste good.  They had been cooked too long.\nThe car was three years old, but hadn’t been used very much.\nPresent continuous\nactive: \n am/is/are + (do)ing\nSomebody is cleaning the room  at the moment.\npassive:    am/is/are + being (done) \nThe room  is being cleaned at the moment.\nThere’s somebody walking behind us.  I think we are being followed.\nA new bridge is being built across the river.  It will be finished next year. \nPast continuous\nactive: \n was/were + (do)ing\nSomebody was cleaning the room  when I arrived.\npassive:    was/were + being (done) \nThe room  was being cleaned when I arrived.\nThere was somebody walking behind us.  I think we were being followed.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nD\nInfinitive\nactive: \n(to) do/clean/see etc. \nSomebody will clean this room  later.\npassive:    (to) be + done/cleaned/seen etc. \nThis room  will be cleaned later.\nThe situation is serious.  Something must be done before it’s too late.\nA mystery is something that can’t be explained.\nThe music was very loud and could be heard from a long way away.\nA new supermarket is going to be built next year.\nPlease go away.  I want to be left alone.\nPerfect infinitive\nactive: \n (to) have + done/cleaned/seen etc.\nSomebody should have cleaned the room  .\npassive:    (to) have been + done/cleaned/seen etc. \nThe room  should have been cleaned.\nI haven’t received the letter yet.  It might have been sent to the wrong address.\nIf you had locked the car, it wouldn’t have been stolen.\nThere were some problems at first, but they seem to have been solved.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPassive 1, 3 ➜ Units 42, 44\n86\n</div>",
    exercises: [],
  },
  '44': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPassive 3\nI was off ered … / we were given … etc.\nSome verbs can have two objects.  For example, give:\nMy grandfather gave  me  this watch.\nIt is possible to make two passive sentences:\nI was given this watch (by my grandfather).   or\nThis watch was given to me (by my grandfather).\nOther verbs which can have two objects are:\nask \n \noff er \n \npay \n \nshow \n \ntell\nWhen we use these verbs in the passive, most oft en we begin with the person:\nI’ve been off ered the job, but I don’t think I want it. (= somebody has off ered me the job)\nYou will be given plenty of time to decide. (= we will give you plenty of time)\nI didn’t see the original document, but I was shown a copy. (= somebody showed me a copy)\nTim has an easy job – he’s paid a lot of money to do very little. (= somebody pays him a lot)\nobject 1      object 2\nI don’t like being …\nThe passive of doing/seeing etc. is being done / being seen etc.  Compare:\n \nactive: \nI don’t like people telling me what to do.\n \npassive: \nI don’t like being told what to do.\nI remember being taken to the zoo when I was a child.\n(= I remember somebody taking me to the zoo)\nSteve hates being kept waiting. (= he hates people keeping him waiting)\nWe climbed over the wall without being seen. (= without anybody seeing us)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI was born …\nWe say ‘I was born …’ (not I am born):\nI was born in Chicago.\n Where were you born? (not Where are you born?)  \n⎧\n⎨\n⎩\npast\nbut\nHow many babies are born every day? \npresent\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nget\nYou can use get for the passive:\nThere was a fight, but nobody got hurt. (= nobody was hurt)\nI don’t get invited to many parties. (= I’m not invited)\nI’m surprised Liz didn’t get off ered the job. (= Liz wasn’t off ered the job)\nWe use get only when things happen.  For example, you cannot use get in these sentences:\nJessica is liked by everybody. (not gets liked – this is not a ‘happening’)\nPeter was a mystery man.  Very little was known about him. (not got known)\nWe use get mainly in informal spoken English.  You can use be in all situations.\nWe also use get in the following expressions (which are not passive in meaning):\nget married, get divorced \n \nget dressed (= put on your clothes)\nget lost (= not know where you are) \nget changed (= change your clothes)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n⎧\n⎨\n⎩\n⎧\n⎪\n⎪\n⎪\n⎨\n⎪\n⎪\n⎪\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPassive 1–2 ➜ Units 42–43\n88\n</div>",
    exercises: [],
  },
  '45': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nit is said that …    he is said to …\nhe is supposed to …\nGeorge is very old.  Nobody knows exactly how old he is, but:\nIt is said that he  is 108 years old.\nor  He  is said to be 108 years old.\nBoth these sentences mean: ‘People say that he is 108 years old.’\nYou can use these structures with a number of other verbs, especially:\nalleged \nbelieved \nconsidered \nexpected \nknown \nreported \nthought \nunderstood\nCathy loves running. \nIt is said that she runs 10 miles a day. \n    or \nShe is said to run 10 miles a day.\nThe police are looking for a missing boy. \nIt is believed that the boy is wearing \n    or \nThe boy is believed to be wearing \na white sweater and blue jeans. \na white sweater and blue jeans.\nThe strike started three weeks ago. \nIt is expected that it will end soon. \n    or \nThe strike is expected to end soon.\nA friend of mine has been arrested. \nIt is alleged that he stole a car. \nor \nHe is alleged to have stolen a car.\nThe two houses belong to the same family. \nIt is said that there is a secret tunnel \n    or \nThere is said to be a secret tunnel\n \nbetween them.\nbetween them.\nThese structures are often used in news reports.  For example, in a report about an accident:\nIt is reported that two people were \n    or \nTwo people are reported to have\ninjured in the explosion. \n \nbeen injured in the explosion.\nsupposed to …\nYou can use supposed to … in the same way as said to … :\nI want to see that film.  It’s supposed to be good. (= people say it’s good)\nThere are many stories about Joe.  He’s supposed to have robbed a bank many years ago.\nFireworks are supposed to have been invented in China.  Is it true?\nSometimes supposed to … has a different meaning.  We use supposed to to say what is intended, \narranged or expected.  Often this is different from the real situation:\nThe plan is supposed to be a secret, but everybody seems to know about it.\n(= the plan is intended to be a secret)\nWhat are you doing at work?  You’re supposed to be on holiday.\n(= you arranged to be on holiday)\nOur guests were supposed to come at 7.30, but they were late.\nJane was supposed to phone me last night, but she didn’t.\nI’d better hurry.  I’m supposed to be meeting Chris in ten minutes.\nYou’re not supposed to do something = it is not allowed or advised:\nYou’re not supposed to park your car here.  It’s private parking only.\nJoe is much better after his illness, but he’s not supposed to exercise too hard.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nStudy this example situation: \nGEORGE\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n90\n</div>",
    exercises: [],
  },
  '46': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nhave something done\nIf you have something done, you arrange for somebody to do it for you.\nCompare:\nLisa repaired the roof. (= she repaired it herself)\n \nLisa had the roof repaired. (= she arranged for somebody else to repair it)\na: Did you make those curtains yourself?\nb: Yes, I like making things.\na: Did you have those curtains made?\nb: No, I made them myself.\nThe roof of Lisa’s house was damaged.\nSo she called a builder, and yesterday he came \nand repaired it.\nLisa had the roof repaired yesterday.\nThis means: Lisa arranged for somebody else to\nrepair the roof.  She didn’t repair it herself.\nStudy this example situation:\nStudy the word order:\nhave\nobject\npast participle\nLisa had\nWhere did you have\nWe are having\nI think you should have\nI don’t like having\nthe roof\nyour hair\nthe house\nthat coat\nmy picture\nrepaired.\ncut?\npainted.\ncleaned.\ntaken.\nWe say:\nHow oft en do you have your car serviced? (not have serviced your car)\nOur neighbour is having a garage built. (not having built a garage) \nYour hair looks nice.  Did you have it cut?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nget something done\nYou can say ‘get something done’ instead of ‘have something done’:\nWhen are you going to get the roof repaired? (= have the roof repaired)\nI think you should get your hair cut really short.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe also use have something done with a diff erent meaning.  For example:\nPaul and Karen had their bags stolen while they were travelling.\nThis does not mean that they arranged for somebody to steal their bags.  ‘They had their bags stolen’ \nmeans only: ‘Their bags were stolen’.\nWith this meaning, we use have something done to say that something happens to somebody or their \nbelongings:\nGary had his nose broken in a fight. (= his nose was broken)\nHave you ever had your bike stolen?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nLISA\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n92\n</div>",
    exercises: [],
  },
  '47': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nReported speech 1 (he said that …)\nStudy this example situation:\nYou saw Paul yesterday and you want to tell somebody \nwhat he said. \nThere are two ways of doing this:\nYou can repeat Paul’s words (direct speech):\nPaul said, ‘I’m feeling ill.’\nOr you can use reported speech:\nPaul said that he was feeling ill.\nCompare: \n \ndirect \nPaul said, ‘ I\nam  \nfeeling ill.’\nreported \nPaul said that  he   was   feeling ill.\nIn writing we use these quotation \nmarks to show direct speech.\nWhen we use reported speech, the main verb of the sentence is usually past (Paul said that … /\nI told her that … etc.).  The rest of the sentence is usually past too:\nPaul said that he was feeling ill.\nI told Lisa that I didn’t have any money.\nYou can leave out that.  So you can say:\nPaul said that he was feeling ill.   or   Paul said he was feeling ill.\nIn general, the present in direct speech changes to the past in reported speech:\n \nam/is → was  \ndo/does → did  \nwill → would\n \nare → were  \nhave/has → had  \ncan → could\nwant/like/know/go etc. → wanted/liked/knew/went etc.\nSee also Unit 48A.\nCompare direct and reported speech:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou met Anna.  Here are some of \nthe things she said in direct speech:\nLater you tell somebody what Anna said.  \nYou use reported speech:\nI’ve lost my phone.\nI want to buy a car.\nI can’t come to the party on \nFriday.\nI don’t have much free time.\nMy parents are fine.\nI’m going away for a few days.  \nI’ll phone you when I get back.\nAnna said that she had lost her phone.\nShe said that she wanted to buy a car.\nShe said that she couldn’t come to \nthe party on Friday.\nShe said that she didn’t have much \nfree time.\nShe said that her parents were fine.\nShe said that she was going away for a \nfew days and would phone me when \nshe got back.\nThe past simple (did/saw/knew etc.) can stay the same in reported speech, or you can change it to the \npast perfect (had done / had seen / had known etc.):\ndirect\nPaul said: ‘I woke up feeling ill, so I didn’t go to work.’\nreported\nPaul said (that) he woke up feeling ill, so he didn’t go to work.   or\nPaul said (that) he had woken up feeling ill, so he hadn’t gone to work.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nANNA\nI’m feeling ill.\nPAUL\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nReported speech 2 ➜ Unit 48\nReported questions ➜ Unit 50B\n94\n</div>",
    exercises: [],
  },
  '48': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nReported speech 2\nWe do not always change the verb in reported speech.  If the situation is still the same, it is not necessary to \nchange the verb to the past.  For example:\ndirect \nPaul said, ‘My new job is boring.’\n \nreported Paul said that his new job is boring.\n(The situation is still the same.  His job is still boring now.)\ndirect \nHelen said, ‘I want to go to Canada next year.’\n \nreported Helen told me that she wants to go to Canada next year.\n(Helen still wants to go to Canada next year.)\nYou can also change the verb to the past:\nPaul said that his new job was boring.\nHelen told me that she wanted to go to Canada next year.\nBut if the situation has changed or finished, you need to use a past verb.  Compare:\nPaul left  the room suddenly.  He said ‘I have to go.’ (direct speech)\nPaul left  the room suddenly.  He said (that) he had to go. (not has to go)\nYou need to use the past in reported speech when\nwhat was said is diff erent from what is really true. \nFor example:\nYou met Rachel a few days ago.  She said:\nHave you heard?  Joe is in hospital.\nLater that day you meet Joe in the street.  You say:\nJoe, this is a surprise.  Rachel said you were in hospital.\n \n(not ‘you are in hospital’ – it’s clear that he isn’t)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nsay and tell\nIf you say who somebody is talking to, use tell:\nRachel told me that you were in hospital.  (not Rachel said me)\nWhat did you tell the police? (not say the police)\nOtherwise use say:\nRachel said that you were in hospital.   \n(not Rachel told that …)\nWhat did you say?\nYou can ‘say something to somebody’:\nAnna said goodbye to me and left . (not Anna said me goodbye)\nWhat did you say to the police?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe say ‘tell somebody to …’ and ‘ask somebody to …’ . \nCompare direct and reported speech:\ndirect \n‘Drink plenty of water,’ the doctor said to me.\n \nreported \nThe doctor told me to drink plenty of water.\ndirect \n‘Don’t work too hard,’ I said to Joe.\n \nreported \nI told Joe not to work too hard.\ndirect \n‘Can you help me, please,’ Jackie said to me.\n \nreported \nJackie asked me to help her.\nYou can also say ‘Somebody said (not) to do something’:\nPaul said not to worry about him. (but not Paul said me)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nJOE\nRachel said \nyou were \nin hospital\nRACHEL\nJoe is in hospital.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nReported speech 1 ➜ Unit 47\nReported questions ➜ Unit 50B\n96\n</div>",
    exercises: [],
  },
  '49': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nQuestions  1\nIn questions the subject is usually after the first verb:\n          subject   +   verb \n        verb   +   subject\n   Tom \nwill \n→\nwill\nTom?\n             you \nhave \n→\nhave\nyou?\nthe house \nwas \n→ \nwas \nthe house?\nWill Tom be here tomorrow?\nHave you been working hard?\n When was the house built?\nThe subject is after the first verb:\nIs Katherine working today? (not Is working Katherine)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nIn present simple questions, we use do/does:\n  you \nlive \n→ \ndo\nyou live?\n  the film \nstarts \n→ \ndoes\nthe film start?\nDo you live near here?\nWhat time does the film start?\nIn past simple questions, we use did:\n     you \nsold \n→ \ndid\nyou sell?\nthe train \nstopped → \ndid \nthe train stop?\nDid you sell your car?\n Why did the train stop?\nBut do not use do/does/did if who/what etc. is the subject of the sentence.  Compare:\nobject\nsubject\nwho object\nEmma phoned  somebody  .\n  Who  did Emma phone?\n \nwho subject\n          Somebody  phoned Emma.\n           Who  phoned Emma?\nIn these examples, who/what etc. is the subject:\nWho wants something to eat? (not Who does want)\nWhat happened to you last night? (not What did happen)\nHow many people came to the party? (not did come)\nWhich bus goes to the centre? (not does go)\nIn questions beginning who/what/which/where, prepositions (in, for etc.) usually go at the end:\nWhere are you from? \n What was the weather like?\nWho do you want to speak to? \n Which job has Tina applied for?\nYou can use preposition + whom in formal style:\nTo whom do you wish to speak?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nisn’t it … ? / didn’t you … ? etc.  (negative questions)\nWe use negative questions especially to show surprise:\n Didn’t you hear the doorbell?  I rang it three times.\nor when we expect the listener to agree with us:\n‘Haven’t we met before?’    ‘Yes, I think we have.’\nNote the meaning of yes and no in answers to negative questions:\n ‘Don’t you want to go?’ \n ‘Yes.’ (= Yes, I want to go)  \n‘No.’ (= No, I don’t want to go)\nWe often use negative questions with Why … ? :\nWhy don’t we eat out tonight? (not Why we don’t eat)\nWhy wasn’t Emma at work yesterday? (not Why Emma wasn’t)\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nA\nQuestions 2 ➜ Unit 50\nQuestion tags (do you?  isn’t it? etc.) ➜ Unit 52\n98\n</div>",
    exercises: [],
  },
  '50': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nQuestions 2 (do you know where … ? /\nhe asked me where …)\nDo you know where … ? / I don’t know why … / Could you tell me what … ? etc.\nWe say:                        Where has Tom gone?\nbut Do you know where Tom has gone? (not has Tom gone)\nWhen the question (Where has Tom gone?) is part of a longer sentence (Do you know … ? /\nI don’t know … / Can you tell me … ? etc.), the word order changes.  We say:\nWhat time is it? \nbut Do you know what time it is?\nWho are those people? \nI don’t know who those people are.\nWhere can I find Louise? \nCan you tell me where I can find Louise?\nHow much will it cost? \nDo you have any idea how much it will cost?\nBe careful with do/does/did questions.  We say:\nWhat time does the film start? \nbut     Do you know what time the film starts?\n(not does the film start)\nWhat do you mean? \nPlease explain what you mean.\nWhy did she leave early? \nI wonder why she left  early.\nUse if or whether where there is no other question word (what, why etc.):\nDid anybody see you? \nbut     I don’t know if anybody saw me.\n            or … whether anybody saw me.\nHe asked me where … \nThe same changes in word order happen in questions in reported speech.  Compare:\ndirect \nThe police off icer said to us ‘Where  are you going  ?’\nreported \nThe police off icer asked us where  we were going  .\ndirect \nClare asked ‘What time  do the shops close  ?’\nreported \nClare wanted to know what time  the shops closed  .\nIn reported speech the verb usually changes to the past (were, closed etc.).  See Unit 47.\nStudy these examples.  You had a job interview and the interviewer asked you these questions:\nAre you willing to travel?\nWhat do you do in your spare time?\nHow long have you been\nworking in your present job?\nWhy did you apply for the job?\nCan you speak any other languages?\nDo you have a driving licence?\nLater you tell a friend what the interviewer asked you.  You use reported speech:\nShe asked if (or whether) I was willing to travel.\nShe wanted to know what I did in my spare time.\nShe asked how long I had been working in my present job.\nShe asked why I had applied for the job.   or   … why I applied …\nShe wanted to know if (or whether) I could speak any other languages.\nShe asked if (or whether) I had a driving licence.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nA\nReported speech ➜ Units 47–48\n100\n</div>",
    exercises: [],
  },
  '51': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAuxiliary verbs (have/do/can etc.)\nI think so / I hope so etc.\nIn these sentences there is an auxiliary verb and a main verb:\nI\nShe\nThe hotel\nWhy\nauxiliary\nhave\ncan’t\nwas\ndo you\nmain\nlost\ncome\nbuilt\nwant\nmy keys.\nto the party.\nten years ago.\nto go home?\nIn these examples have/can’t/was/do are auxiliary (= helping) verbs.\nYou can use an auxiliary verb when you don’t want to repeat something:\n‘Have you locked the door?’ \n‘Yes, I have.’ (= I have locked the door)\nGary wasn’t working, but Laura was. (= Laura was working)\nJessica could lend me the money, but she won’t. (= she won’t lend me the money)\nWe use do/does/did for the present and past simple:\n‘Do you like onions?’ \n‘Yes, I do.’ (= I like onions)\n‘Does Simon live in London?’ \n‘He did, but he doesn’t any more.’\nYou can use auxiliary verbs to deny what somebody says (= say it is not true):\n‘You’re sitting in my place.’ \n‘No, I’m not.’ (= I’m not sitting in your place)\n‘You didn’t lock the door before you left.’ \n‘Yes, I did.’ (= I locked the door)\nWe use have you? / isn’t she? / are they? etc. to show that we are interested in what somebody has said, \nor to show surprise:\n‘I’ve just seen Steven.’ \n‘Oh, have you? How is he?’\n‘Lisa isn’t very well today.’ \n‘Isn’t she? What’s wrong with her?’\n‘It rained every day during our holiday.’ \n‘Did it? What a shame!’\n‘James and Tanya are getting married.’ \n‘Are they? Really?’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use auxiliary verbs with so and neither:\n‘I’m tired.’ \n‘So am I.’ (= I’m tired too)\n‘I never read newspapers.’ \n‘Neither do I.’ (= I never read newspapers either)\nSarah can’t drive and neither can Mark.\nNote the word order after so and neither (verb before subject):\nI passed the exam and so did Paul. (not so Paul did)\nInstead of neither, you can use nor.  You can also use not … either:\n‘I don’t know.’ \n‘Neither do I.’    or    ‘Nor do I.’    or    ‘I don’t either.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI think so / I suppose so etc.\nYou can say I think so / I suppose so etc. when we don’t want to repeat something:\n‘Are those people Korean?’ \n‘I think so.’ (= I think they are Korean)\n‘Is Kate working tomorrow?’ \n‘I suppose so.’ (= I suppose she is working tomorrow)\n‘Will you be at home this evening?’ \n‘I expect so.’ (= I expect I’ll be at home …)\nIn the same way we say: I hope so, I guess so and I’m afraid so.\nThe usual negative forms are:\nI think so / I expect so \n→\nI don’t think so / I don’t expect so\nI hope so / I’m afraid so \n→\nI hope not / I’m afraid not\nI guess so / I suppose so \n→\nI guess not / I suppose not\n‘Is that woman American?’ \n‘I think so. / I don’t think so.’\n‘Do you think it will rain?’ \n‘I hope so. / I hope not.’ (not I don’t hope so)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nAmerican English ➜ Appendix 7\n102\n</div>",
    exercises: [],
  },
  '52': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nQuestion tags (do you? isn’t it? etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy these examples:\nHave you? and wasn’t it? are question tags.  These are mini-questions that you can put on the end of\na sentence.  \nIn question tags, we use an auxiliary verb (have/was/will etc.).\nWe use do/does/did for the present and past simple (see Unit 51):\n‘Karen plays the piano, doesn’t she?’ \n‘Well, yes, but not very well.’\n‘You didn’t lock the door, did you?’ \n‘No, I forgot.’\nNo, I haven’t.\nYou haven’t seen\nLisa today, have you?\nNormally we use a negative question tag aft er  \n… and a positive question tag aft er a\na positive sentence:  \nnegative sentence:\n     positive sentence \nKate will be here soon,\nThere was a lot of traff ic,\nJoe should pass the exam,\nnegative tag\nwon’t she?\nwasn’t there?\nshouldn’t he?\nnegative sentence\nKate won’t be late,\nThey don’t like us,\nYou haven’t eaten yet,\npositive tag\nwill she?\ndo they?\nhave you?\nNotice the meaning of yes and no in answer to a negative sentence:\n‘You’re not going out this morning, are you?’\n+\n+\n‘Yes.’ (= Yes, I am going out)\n‘No.’  (= No, I am not going out)\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nThe meaning of a question tag depends on how you say it.  If your voice goes down, you are not\nreally asking a question.  You expect the listener to agree with you:\n‘It’s a nice day, isn’t it?’ \n‘Yes, beautiful.’\n‘Paul doesn’t look well today, does he?’ \n‘No, he looks very tired.’\n‘Lisa’s very funny.  She’s got a great sense of humour, hasn’t she?’ \n‘Yes, she has.’\nBut if the voice goes up, it is a real question:\n‘You haven’t seen Kate today, have you?’ \n‘No, I haven’t.’\n(= Have you seen Kate today?)\nYou can use a negative sentence + positive tag to ask for things or information, or to ask somebody\nto do something.  The voice goes up at the end of the tag:\n‘You couldn’t do me a favour, could you?’ \n‘It depends what it is.’\n‘You don’t know where Karen is, do you?’ \n‘Sorry, I have no idea.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nAft er Let’s … (= Let us) the question tag is shall we:\nLet’s go for a walk, shall we? (the voice goes up)\nAft er Don’t … , the question tag is will you:\nDon’t be late, will you? (the voice goes down)\nAft er I’m … , the negative question tag is aren’t I? (= am I not?):\n‘I’m right, aren’t I?’ \n‘Yes, you are.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nAuxiliary verbs (have/do/can etc.) ➜ Unit 51\nYes, it was great.\nIt was a good\nfilm, wasn’t it?\n104\n</div>",
    exercises: [],
  },
  '53': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + -ing (enjoy doing / stop doing etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe say:\nI enjoy reading. (not I enjoy to read)\nWould you mind closing the door?\n \n(not mind to close)\nChris suggested going to the cinema.\n \n(not suggested to go)\nAft er enjoy, mind and suggest, we use -ing (not to …).\nSome more verbs that are followed by -ing:\nstop\nfinish\nrecommend\nconsider\nadmit\ndeny\navoid\nrisk\nimagine\nfancy\nSuddenly everybody stopped talking.  There was silence.\nI’ll do the shopping when I’ve finished cleaning the flat.\nHe tried to avoid answering my question.\nI don’t fancy going out this evening. (= I’m not enthusiastic about it)\nHave you ever considered going to live in another country?\nThey said they were innocent.  They denied doing anything wrong.\nThe negative form is not -ing:\nWhen I’m on holiday, I enjoy not having to get up early.\nWe also use -ing aft er:\ngive up (= stop)\nput off  (= delay until later)\ngo on or carry on (= continue)\nkeep or keep on (= do something continuously or repeatedly)\nI’ve given up buying newspapers.  I don’t read them any more.\nYou shouldn’t put off  telling him what happened.  You need to tell him now.\nKatherine doesn’t want to retire.  She wants to go on working.    or    … to carry on working.\nYou keep interrupting when I’m talking.    or    You keep on interrupting …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWith some verbs you can use the structure verb + somebody + -ing:\nYou can’t stop people doing what they want.\nI can’t imagine George riding a motorbike.\nDid she really say that?  I don’t remember her saying that.\nSorry to keep you waiting so long.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWhen you talk about finished actions, you can say having done/stolen/said etc. :\nThey admitted having stolen the money.\nBut it is not necessary to use having (done).  You can say:\nThey admitted stealing the money.\nI now regret saying that.    or    I now regret having said that.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nOther structures are possible with admit, deny, suggest and recommend.  For example, you can say:\nThey denied (that) they had done anything wrong. (= They denied doing …)\nChris suggested (that) we go to the cinema. (= Chris suggested going …)\nI recommend (that) you travel by train. (= I recommend travelling …)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nsuggest ➜ Unit 34\nbeing done (passive) ➜ Unit 44B\nVerb + to … ➜ Unit 54\nVerb + to … and -ing ➜  Units 55C, 56–58\nremember / regret / go on ➜ Unit 56B\ngo on / carry on / keep on ➜ Unit 141A\nWould you mind\nclosing the door?\n106\n</div>",
    exercises: [],
  },
  '54': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + to … (decide to … / forget to … etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAft er these verbs you can use to … (infinitive):\noff er\nagree\nrefuse\ndecide\nplan\narrange\nhope\nforget\nmanage\nfail\npromise\nthreaten\ndeserve\naff ord\nlearn\ntend\nIt was a long way to walk, so we decided to take a taxi home.\nSimon was in a diff icult situation, so I agreed to help him.\nI waved to Karen, but failed to attract her attention.\nI like Dan, but I think he tends to talk too much.\nHow old were you when you learnt to drive?    \nor    … learnt how to drive?\nThe negative is not to … :\nWe decided not to go out because of the weather.\nI promised not to be late.\nAft er some verbs, we use -ing (not to …).  For example, enjoy/think/suggest:\nI enjoy reading.    (not enjoy to read)\nAndy suggested meeting for coff ee. (not suggested to meet)\nAre you thinking of buying a car? (not thinking to buy)\nFor verb + -ing, see Units 53 and 62.\nDan tends to talk too much.\nAft er dare you can use the infinitive with or without to:\nI didn’t dare to tell him.    or    I didn’t dare tell him.\nBut aft er dare not (or daren’t), we do not use to:\nI daren’t tell him what happened. (not I daren’t to tell him)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe also use to … aft er seem, appear, pretend and claim.  For example:\nThey seem to have plenty of money.\nAnn pretended not to see me when she passed me in the street.\nYou can also use to be -ing (continuous infinitive) and to have (done) (perfect infinitive):\nI pretended to be reading the newspaper. (= I pretended that I was reading)\nHave you seen my keys?  I seem to have lost them. (= it seems that I have lost them)\nShe claimed not to have seen me. (= she claimed that she hadn’t seen me)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nAft er these verbs you can use a question word (what/how etc.) + to … . \nask \nknow \ndecide \nremember \nforget \nlearn \nexplain \nunderstand \nwonder \nFor example:\nWe asked\nHave you decided\nI don’t know\nDo you understand\nhow\nwhere\nwhether\nwhat\nto get\nto go\nto apply\nto do?\nto the station.\non holiday?\nfor the job or not.\nalso \nshow/tell/ask/advise/teach somebody what/how/where to do something:\nCan somebody show me how to use this camera?\nAsk Jack.  He’ll tell you what to do.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nVerb + -ing ➜ Unit 53\nVerb + object + to … (want etc.) ➜ Unit 55\nVerb + to … and -ing ➜ Units 55C, 56–58\n108\n</div>",
    exercises: [],
  },
  '55': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb (+ object) + to …  (I want you to …)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe say:\nverb     +    to … \nverb     +     object         + to …\nwant\nexpect\nask\nhelp\nwould like\nwould prefer\nto go \nto be \nto work \netc.\nand\nwant\nexpect\nask\nhelp\nwould like\nwould prefer\nsomebody\nsomething\nto go \nto be \nto work \netc.\nWe expected to be late.\nWould you like to go now?\nHe doesn’t want to know.\nWe expected Dan to be late.\nWould you like me to go now?\nHe doesn’t want anybody to know.\nWe do not usually say ‘want that’:\nDo you want me to come with you? (not want that I come)\nYou can use help with or without to.  You can say:\nCan you help me to move this table?    or    Can you help me move this table?\nThese verbs have the structure verb + object + to … :\n        verb       +       object   +      to …\ntell\nadvise\nremind\nwarn\ninvite\nencourage\npersuade\nget\nforce\nteach\nallow\nenable\nsomebody\nto do \nto be \nto work \netc.\nIt’s not a nice hotel.  I wouldn’t advise you to stay \nthere.\nCan you remind me to call Sam tomorrow?\nJoe said the switch was dangerous and warned me \nnot to touch it.\nI didn’t move the piano by myself.  I got somebody \nto help me.\nWho taught you to drive?\nThey don’t allow people to park in front of the \nbuilding.\nIn these examples, the verb is passive (I was warned / we are allowed etc.):\nI was warned not to touch the switch.\nAre we allowed to park here?\nWe do not use suggest with to … :\nJane suggested that I ask you for advice. (not Jane suggested me to ask)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say ‘make somebody do something’, ‘let somebody do something’ (without to): \nI made him promise that he wouldn’t tell anybody what happened.  \n(not made him to promise)\nHot weather makes me feel tired. (= causes me to feel tired)\nHer parents wouldn’t let her go out alone. (= wouldn’t allow her to go out)\nLet me carry your bag for you.\nWe say ‘make somebody do’, but in the passive we say ‘(be) made to do’ (with to):\nWe were made to wait for two hours. (= They made us wait …)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nsuggest ➜ Units 34, 53\ntell/ask somebody to … ➜ Unit 48D\nVerb + -ing ➜ Unit 53\nVerb + to … ➜ Unit 54\nVerb + to … and -ing ➜ Units 56–58\nhelp ➜ Unit 57C\n110\n</div>",
    exercises: [],
  },
  '56': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + -ing or to … 1   (remember, regret etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSome verbs are followed by -ing and some are followed by to …  .\nVerbs that you can use with -ing (not to …):\nadmit\navoid\nconsider\ndeny\nenjoy\nfancy\nfinish\nimagine\nkeep (on)\nmind\npostpone\nrisk\nstop\nsuggest\nFor examples, see Unit 53.\nVerbs that you can use with to … :\nafford\nagree\narrange\ndecide\ndeserve\nfail\nforget\nhope\nlearn\nmanage\noffer \nplan\npromise\nrefuse\ntend\nFor examples, see Unit 54.\nI remember doing something = I did it and\nnow I remember this.\nYou remember doing something after you\nhave done it.\nI know I locked the door.  I clearly\nremember locking it.\n(= I locked it, and now I remember this)\nHe could remember driving along the\nroad just before the accident, but he\ncouldn’t remember the accident itself.\nI remembered to do something = \nI remembered that I had to do it, so I did it.\nYou remember to do something before you \ndo it.\nI remembered to lock the door, but I \nforgot to shut the windows.\n(= I remembered that I had to lock it, \nand so I locked it)\nRemember to buy some bananas. \n(= Don’t forget to buy them)\nI regret doing something = I did it and now\nI am sorry about it:\nI now regret saying what I said.  I \nshouldn’t have said it.\nDo you regret not going to college?\nI regret to say / to tell you / to inform you =  \nI am sorry that I have to say:\n(from a formal letter)  I regret to say that\nwe are unable to accept your offer.\ngo on doing something = continue doing the \nsame thing:\nThe president paused for a moment and \nthen went on talking.\nWe need to change.  We can’t go on\n \nliving like this.\ngo on to do something = do or say something  \nnew:\nAfter discussing the economy, the \npresident went on to talk about \nforeign policy.\nSome verbs can be followed by -ing or to … with a difference of meaning:\nremember\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nregret\ngo on\nWe use the following verbs with -ing or to … with no difference of meaning:\nbegin \n \nstart \n \ncontinue \n \nintend \n \nbother\nSo you can say:\nIt started raining.    or    It started to rain.\nAndy intends buying a house.    or    Andy intends to buy …\nDon’t bother locking the door.    or    Don’t bother to lock …\nNormally we do not use -ing after -ing:\nIt’s starting to rain. (not usually It’s starting raining)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nVerb + -ing ➜ Unit 53\nVerb + to … ➜ Units 54–55\nOther verbs + -ing or to … ➜ Units 57–58\n112\n</div>",
    exercises: [],
  },
  '57': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + -ing or to … 2   (try, need, help)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\ntry to … and try -ing\nneed to … and need -ing\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\ntry to do = attempt to do, make an eff ort to do:\nI was very tired.  I tried to keep my eyes open, but I couldn’t.\nPlease try to be quiet when you come home.  Everyone will be asleep.\ntry something or try doing something = do it as an experiment or test:\nThese cakes are delicious.  You should try one. (= have one to see if you like it)\nWe couldn’t find anywhere to stay.  We tried every hotel in the town, but they were all full.\n(= we went to every hotel to see if they had a room)\na: The photocopier doesn’t seem to be working.\nb: Try pressing the green button.\n(= press the green button – perhaps this will help to solve the problem)\nCompare:\nI tried to move the table, but it was too heavy. (so I couldn’t move it)\nI didn’t like the way the furniture was arranged, so I tried moving the table to the other\nside of the room.  But it didn’t look right, so I moved it back again.\n \n(I tried moving it = I moved it to see if it looked better)\nI need to do something = it is necessary for me to do it:\nHe needs to work harder if he wants to make progress.\nI don’t need to come to the meeting, do I?\nYou can say that something needs -ing: \nMy phone needs charging. (= it needs to be charged)\nDoes your suit need cleaning? (= … need to be cleaned)\nIt’s a diff icult problem.  It needs thinking about carefully.\n(= it needs to be thought about carefully)\nCompare:\n I need to charge my phone.\nbut  \nMy phone needs charging.\nYou can say help to do or help do (with or without to):\nEverybody helped to clean up aft er the party.    or\n \nEverybody helped clean up …\nCan you help me move this table?    or\nCan you help me to move …\nI can’t help doing something = I can’t stop myself doing it:\nI don’t like him, but he has a lot of problems. \nI can’t help feeling sorry for him.\nShe tried to be serious, but she couldn’t help laughing.\n(= she couldn’t stop herself laughing)\nI’m sorry I’m so nervous.  I can’t help it.\n(= I can’t help being nervous)\nShe couldn’t help laughing.\nhelp and can’t help\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nVerb + -ing ➜ Unit 53\nVerb + to … ➜ Units 54–55\nOther verbs + -ing or to … ➜ Units 56, 58\nMy phone needs charging.\n114\n</div>",
    exercises: [],
  },
  '58': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + -ing or to … 3 (like / would like etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nlike / love / hate\nWhen you talk about repeated actions, you can use -ing or to … after these verbs.\nSo you can say:\nDo you like getting up early?    or    Do you like to get up early?\nStephanie hates flying.    or    Stephanie hates to fly.\nI love meeting people.    or    I love to meet people.\nI don’t like being kept waiting.    or    … like to be kept waiting.\nI don’t like friends calling me at work.    or    … friends to call me at work.\nbut\n(1) We use -ing (not to …) when we talk about a situation that already exists (or existed).\nFor example:\nPaul lives in Berlin now.  He likes living there.  \n(he lives there now and he likes it)\nDo you like being a student? (you are a student – do you like it?)\nThe office I worked in was horrible.  I hated working there. (I worked there and I hated it)\n(2) There is sometimes a difference between I like to do and I like doing:\nI like doing something = I do it and I enjoy it:\nI like cleaning the kitchen. (= I enjoy it.)\nI like to do something = I choose to do it (but maybe I don’t enjoy it):\nIt’s not my favourite job, but I like to clean the kitchen as often as possible.\nNote that we use -ing (not to …) with enjoy and mind:\nI enjoy cleaning the kitchen. (not I enjoy to clean)\nI don’t mind cleaning the kitchen. (not I don’t mind to clean)\nwould like / would love / would hate / would prefer\nWould like / would love etc. are usually followed by to … :\nI’d like (= I would like) to go away for a few days.\nWhat would you like to do this evening?\nI wouldn’t like to go on holiday alone.\nI’d love to meet your family.\nWould you prefer to eat now or later?\nCompare I like and I would like (I’d like):\nI like playing tennis. / I like to play tennis. (= I like it in general)\nI’d like to play tennis today. (= I want to play today)\nWould mind is followed by -ing:\nWould you mind closing the door, please? (not mind to close)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI would like to have (done something)\nI would like to have done something = I regret now that I didn’t or couldn’t do it:\nIt’s a shame we didn’t see Anna.  I would like to have seen her again.\nWe’d like to have gone away, but we were too busy at home.\nWe use the same structure after would love / would hate / would prefer:\nPoor David!  I would hate to have been in his position.\nI’d love to have gone to the party, but it was impossible.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nenjoy/mind ➜ Unit 53\nwould like ➜ Units 37E, 55A\nprefer ➜ Unit 59\n116\n</div>",
    exercises: [],
  },
  '59': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nprefer and would rather\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nprefer to … and prefer -ing\nWhen you say what you prefer in general, you can use prefer to … or prefer -ing:\nI don’t like cities.  I prefer to live in the country.    or    I prefer living in the country.\nYou can say:\n prefer something\nto something else\n prefer doing something\nto doing something else\nrather than (doing) something else\n prefer to do something\nrather than (do) something else\nI prefer this coat to the other one.\nI prefer driving to travelling by train.    or\n \nI prefer driving rather than travelling by train.\nI prefer to drive rather than travel by train.\nSarah prefers to live in the country rather than in a city.\nwould prefer (I’d prefer …) \nWe use would prefer to say what somebody wants in a specific situation (not in general):\n‘Would you prefer tea or coffee?’ \n‘Coffee, please.’\nWe say ‘would prefer to do something’ (not usually would prefer doing):\n‘Shall we go by train?’ \n‘I’d prefer to drive.’ (= I would prefer …)\nI’d prefer to stay at home tonight rather than go to the cinema.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nwould rather (I’d rather …)\nI’d rather = I would rather.  I’d rather do something = I’d prefer to do it.  \nWe say I’d rather do (not to do).  Compare:\n‘Shall we go by train?’ \n Which would you rather do,\n \nWhich would you prefer to do, \nThe negative is ‘I’d rather not …’ :\nI’m tired.  I’d rather not go out this evening, if you don’t mind.\n‘Do you want to go out this evening?’ \n‘I’d rather not.’\nWe say ‘I’d rather do one thing than do another’:\nI’d rather stay at home tonight than go to the cinema.\n‘I’d rather drive.’ (not to drive)\n‘I’d prefer to drive.’\n⎧\n⎨\n⎩\ngo to the cinema or go shopping?\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nI’d rather somebody did something\nWe say ‘I’d rather you did something’ (not I’d rather you do):\n‘Who’s going to drive, you or me?’ \n‘I’d rather you drove.’  (= I would prefer this)\n‘Jack says he’ll repair your bike tomorrow, OK?’ \n‘I’d rather he did it today.’\nAre you going to tell Anna what happened, or would you rather I told her?\nWe use the past (drove, did etc.) here, but the meaning is present not past.  Compare:\nI’d rather make dinner now.\nI’d rather you made dinner now. (not I’d rather you make)\nI’d rather you didn’t (do something) = I’d prefer you not to do it:\nI’d rather you didn’t tell anyone what I said.\n‘Shall I tell Anna what happened?’ \n‘I’d rather you didn’t.’\n‘Are you going to tell Anna what happened?’ \n‘No.  I’d rather she didn’t know.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nwould prefer ➜ Unit 58B\nprefer (one thing) to (another) ➜ Unit 136D\n118\n</div>",
    exercises: [],
  },
  '60': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPreposition (in/for/about etc.) + -ing\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nIf a preposition (in/for/about etc.) is followed by a verb, the verb ends in -ing:\nAre you interested\nI’m not good\nKate must be fed up\nWhat are the advantages\nThanks very much\nHow\nWhy don’t you go out\nAmy went to work\npreposition\nin\nat\nwith\nof\nfor\nabout\ninstead of\nin spite of\nverb (-ing)\nworking\nlearning\nstudying.\nhaving\ninviting\nmeeting\nsitting\nfeeling\nfor us?\nlanguages.\na car?\nme to your party.\nfor lunch tomorrow?\nat home all the time?\nill.\nYou can also say ‘instead of somebody doing something’, ‘fed up with people doing something’ etc. :\nI’m fed up with people telling me what to do.\nWe say:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nto + -ing (look forward to doing something etc.)\nWe often use to + infinitive (to do / to see etc.):\nWe decided to travel by train.\nWould you like to meet for lunch tomorrow?\nBut to is also a preposition (like in/for/about/with etc.).  For example:\nWe went from Paris to Geneva.\nI prefer tea to coffee.\nAre you looking forward to the weekend?\nIf we use a preposition + verb, the verb ends in -ing:\nI’m fed up with travelling by train.\nHow about going away this weekend?\nSo, when to is a preposition and it is followed by a verb, we use to -ing:\nI prefer driving to travelling by train. (not to travel)\nAre you looking forward to going on holiday? (not looking forward to go)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nbe/get used to -ing ➜ Unit 61\nVerb + preposition + -ing ➜ Unit 62\nwhile/when -ing ➜ Unit 68B\nin spite of ➜ Unit 113\nPrepositions ➜ Units 121–136 \nbefore -ing, after -ing:\nBefore going out, I phoned Sarah.   (not Before to go out)\n What did you do after leaving school?\nYou can also say ‘Before I went out …’ and ‘… after you left school’.\nby -ing (to say how something happens):\nYou can improve your English by reading more.\nShe made herself ill by not eating properly.\nMany accidents are caused by people driving too fast.\nThe burglars got into the house by breaking a window and climbing in.\nwithout -ing:\nWe ran ten kilometres without stopping.\nIt was a stupid thing to say.  I said it without thinking.\nShe needs to work without people disturbing her.    or    … without being disturbed.\nI have enough problems of my own without having to worry about yours.\n120\n</div>",
    exercises: [],
  },
  '61': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nbe/get used to … (I’m used to …)\nStudy this example situation:\nLisa is American, but she lives in Britain. \nWhen she first drove a car in Britain, driving on the left  \nwas a problem for her because:\nShe wasn’t used to it.\nShe wasn’t used to driving on the left .\n(because Americans drive on the right)\nBut aft er some time, driving on the left  became easier. \nShe got used to driving on the left .\nNow it’s no problem for Lisa:\nShe is used to driving on the left .\nI’m used to something = it is not new or strange for me\nYou can say:\nbe\nget\nused to\nsomething\nor\ndoing something\nPaul lives alone.  He has lived alone for a long time, so it is not strange for him.  He’s used to it. \nHe is used to living alone.\nI bought some new shoes.  They felt a little strange at first because I wasn’t used to them.\n  Our new apartment is on a busy street.  I expect we’ll get used to the noise, but at the moment \nit’s very disturbing.\nHelen has a new job.  She has to get up much earlier now than before – at 6.30.  She finds this \ndiff icult because she isn’t used to getting up so early.\nKatherine’s husband is oft en away from home.  She doesn’t mind this.  She’s used to him \nbeing away.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say ‘be/get used to doing something’ (not I’m used to do).\nLisa is used to driving on the left . (not is used to drive)\nI’m used to living alone. (not I’m used to live)\nWhen we say ‘I am used to …’ , to is a preposition:\nWe’re not used to\nthe noise.\nit.\nliving here. (not live here)\nCompare to + infinitive (to do, to live etc.):\nWe don’t want to live here.\n⎫⎪⎬⎪⎭\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCompare I am used to doing and I used to do:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI am used to (doing) something = it isn’t strange or new for me:\nI’m used to the weather here.\nI’m used to driving on the left  because I’ve lived in Britain a long time.\nI used to do something = I did it regularly in the past but no longer do it.  We use this only for the past \n(I used …), not for the present.  See Unit 18.\nI used to drive to work every day, but these days I usually go by bike.\nWe used to live just outside the town, but now we live near the centre.\nused to (do) ➜ Unit 18\nto + -ing ➜ Unit 60C\nlisa\n122\n</div>",
    exercises: [],
  },
  '62': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\ndecide to … ➜ Unit 54A\nPreposition + -ing ➜ Unit 60\nVerb + preposition ➜ Units 132–136\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition + -ing  \n(succeed in -ing / insist on -ing etc.)\nWe use some verbs + preposition + object.  For example:\n     verb  +  preposition     +  object\nWe talked\nI apologised\nabout\nfor\nthe problem.\nwhat I said.\nIf the object is another verb, we use -ing:\n  verb  +  preposition    +  -ing\nWe talked\nYou should apologise\nabout\nfor\ngoing to South America.\nnot telling the truth.\nYou can use these verbs in the same way:\napprove of\ndecide against\ndream of\nfeel like\ninsist on\nlook forward to\nsucceed in\nthink of/about\nHe doesn’t approve\nWe have decided\nI wouldn’t dream\nI don’t feel\nThey insisted\nAre you looking forward\nHas Paul succeeded\nI’m thinking\nof\nagainst\nof\nlike\non\nto\nin\nof/about\nswearing.\nmoving to London.\nasking them for money.\ngoing out tonight.\npaying for the meal.\ngoing away?\nfinding a job yet?\nbuying a house.\nYou can also say ‘approve of somebody doing something’, ‘look forward to somebody doing\nsomething’ etc. :\nI don’t approve of people killing animals as a sport.\nWe are all looking forward to Andy coming home next week.\nSome verbs can have the structure verb + object + preposition + -ing.  \nFor example:\nverb  +   object  \n+ \npreposition  + -ing\naccuse … of\ncongratulate … on\nprevent … from\nstop … from\nsuspect … of\nthank … for\nHe accused\nWe congratulated\nWhat prevented\nThe rain didn’t stop\nNobody suspected\nI thanked\nme\nLisa\nyou\nus\nthe general\neveryone\nof\non\nfrom\nfrom\nof\nfor\ntelling lies.\nwinning the first prize.\ncoming to see us?\nenjoying our holiday.\nbeing a spy.\nhelping me.\nYou can say ‘stop somebody doing’ or ‘stop somebody from doing’:\nYou can’t stop me doing what I want.    or    You can’t stop me from doing …\nNote this example with not -ing:\nHe accused me of not telling the truth.\nSome of these verbs are often used in the passive.  For example:\nWe were accused of telling lies. (or … accused of lying.)\nThe general was suspected of being a spy.\nNote that we say ‘apologise to somebody for …’ :\nI apologised to them for keeping them waiting. (not I apologised them)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\n124\n</div>",
    exercises: [],
  },
  '63': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\ngone and been … ➜ Unit 7B\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nthere’s no point in -ing,  it’s worth -ing etc.\nWe say:\nthere’s no point in\nit’s no use\nit’s no good\ndoing something\nThere’s no point in having a car if you never use it.\nThere was no point in waiting any longer, so we left.\nIt’s no use worrying about what happened.  There’s nothing you can do about it.\nIt’s no good trying to persuade me.  You won’t succeed.\nWe say ‘no point in …’ but ‘the point of …’ :\nThere’s no point in having a car.\nWhat’s the point of having a car if you never use it?\nWe say:\nit’s worth\nit’s not worth\ndoing something\nIt’s a nice town.  It’s worth spending a few days there. \nOur flight was very early in the morning, so it wasn’t worth going to bed.\nYou can say that something is worth it or not worth it:\nYou should spend a couple of days here.  It’s worth it.\nWe didn’t go to bed.  It wasn’t worth it.\nYou can also say that something is worth doing, a movie is worth seeing etc. :\nIt’s a great movie.  It’s worth seeing.\nThieves broke into the house, but didn’t take anything.  There was nothing worth stealing.\nIt’s an interesting idea.  It’s worth thinking about.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say:\nhave\ntrouble\ndifficulty\na problem\ndoing something\nI had no trouble finding a place to stay. (not trouble to find)\nDid you have a problem getting a visa?\nPeople sometimes have difficulty reading my writing.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe say:\nspend \nwaste\n(time)\ndoing something\nHe spent hours trying to repair the clock.\nI waste a lot of time doing nothing.\nWe also say ‘(be) busy doing something’:\nShe said she couldn’t meet me.  She was too busy doing other things.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe use go -ing for sports and other activities.  For example:\ngo sailing \ngo swimming \ngo fishing \ngo riding \ngo hiking \ngo surfing \ngo scuba diving \ngo skiing \ngo jogging \ngo camping\nHow often do you go swimming?\nWe went skiing last year.\nTom isn’t here.  He’s gone shopping.\nI’ve never been sailing. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n126\n</div>",
    exercises: [],
  },
  '64': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nto … , for … and so that …\nWe say:\nI called the restaurant to reserve a table. \nWhat do you need to make bread?\nWe shouted to warn everybody of the danger.\nThis letter is to confirm the decisions we made at our meeting last week.\nThe president has a team of bodyguards to protect him.\nIn these examples to … (to reserve … / to make … etc.) tells us the purpose of something: why \nsomebody does something, has something, needs something etc., or why something exists.\nWe say ‘a place to park’, ‘something to eat’, ‘work to do’ etc. :\nIt’s hard to find a place to park in the city centre. (= a place where you can park)\nWould you like something to eat? (= something that you can eat)\nDo you have much work to do? (= work that you must do)\nSometimes there is a preposition (on, with etc.) after the verb:\nIs there a chair to sit on? (= a chair that I can sit on)\nI get lonely if there’s nobody to talk to.\nI need something to open this bottle with.\nWe also say money/time/chance/opportunity/energy/courage (etc.) to do something:\nThey gave us money to buy food.\nDo you have much opportunity to practise your English?\nI need a few days to think about your proposal.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare for … and to …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nfor + noun\nWe stopped for petrol.\nI had to run for the bus.\nto + verb\nWe stopped to get petrol.\nI had to run to catch the bus.\nYou can say ‘for somebody to do something’:\nThere weren’t any chairs for us to sit on, so we sat on the floor.\nWe use for (do)ing to say what something is used for:\nThis brush is for washing the dishes.\nBut we do not use for -ing to say why somebody does something:\nI went into the kitchen to wash the dishes. (not for washing)\nYou can use What … for? to ask about purpose:\nWhat is this switch for? (= what is it used for?)\nWhat did you do that for? (= why did you do that?)\nso that\nWe use so that (not to …) especially with can/could and will/would: \nShe’s learning English so that she can study in Canada.\nWe moved to London so that we could see our friends more often.\nI hurried so that I wouldn’t be late.  \n(= because I didn’t want to be late)\nYou can leave out that.  So you can say:\nI hurried so that I wouldn’t be late.    or    I hurried so I wouldn’t be late.    \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n128\n</div>",
    exercises: [],
  },
  '65': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nafraid/interested/sorry ➜ Unit 66\nit … ➜ Unit 84C\nenough and too + adjective ➜ Unit 103\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAdjective + to …\nhard to understand, interesting to talk to etc.\nWe use other adjectives in the same way.  For example:\neasy  \nnice \nsafe \ncheap  \nexciting \nimpossible\ndifficult  \ngood \ndangerous  \nexpensive  \ninteresting\nDo you think it is safe to drink this water?\nDo you think this water is safe to drink?   (not to drink it)\nThe exam questions were very hard.  It was impossible to answer them.\nThe exam questions were very hard.  They were impossible to answer.\n \n(not to answer them)\nNicola has lots of interesting ideas.  It’s interesting to talk to her.\nNicola is interesting to talk to. (not to talk to her)\nWe also use this structure with adjective + noun:\nThis is a difficult question to answer. (not to answer it)\nCompare sentences (a) and (b): \n(a) It is hard to understand  him .\nJames doesn’t speak clearly.\n(b) He  is hard to understand.\nSentences (a) and (b) have the same meaning.  Note that we say:\nHe is hard to understand. (not He is hard to understand him)\n⎫⎪⎬⎪⎭\nnice of (you) to …\nWe say ‘It’s nice of somebody to …’ :\nIt was nice of you to take me to the airport.  Thank you very much.\nWe use other adjectives in the same way.  For example:\nkind       generous       careless       silly       stupid       inconsiderate      unfair       typical\nIt’s silly of Ruth to give up her job when she needs the money.\nI think it was unfair of him to criticise me.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nsorry to … / surprised to … etc.\nYou can use adjective + to … to say how somebody reacts to something:\nI’m sorry to hear that your mother isn’t well.\nWe use other adjectives in the same way.  For example:\nglad       pleased       relieved       surprised       amazed       sad       disappointed\nWas Julia surprised to see you?\nIt was a long and tiring journey.  We were glad to get home.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can use to … after the next / the last / the only / the first / the second (etc.):\nThe next train to arrive at platform 4 will be the 10.50 to Liverpool.\nEverybody was late except me.  I was the only one to arrive on time.\nIf I have any more news, you will be the first to know. (= the first person to know.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nYou can say that something is sure/likely/bound to happen:\nCarla is a very good student.  She’s bound to pass the exam. (= she is sure to pass)\nIt’s possible I’ll win the lottery one day, but it’s not likely to happen. (= it’s not probable)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n130\n</div>",
    exercises: [],
  },
  '66': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nto … (afraid to do) and \npreposition + -ing (afraid of -ing)\nafraid to (do) and afraid of (do)ing\nI am afraid to do something = \nI don’t want to do it because it is dangerous or the result could be bad.\nThis part of town is dangerous.  People are afraid to walk here at night.\n(= they don’t walk here at night because it is dangerous)\nJames was afraid to tell his parents what had happened.\n(= he didn’t tell them because he thought they would be angry)\nI am afraid of something happening = \nI am afraid that something bad will happen.\nThe path was icy, so we walked very carefully.  We were afraid of falling.\n(= we were afraid that we would fall – not afraid to fall)\nI don’t like dogs.  I’m always afraid of being bitten.\n(= I’m afraid that I will be bitten – not afraid to be bitten)\nSo, you are afraid to do something because you are afraid of something happening as a result:\nI was afraid to go near the dog because I was afraid of being bitten.\ninterested in (do)ing and interested to (do)\nI’m interested in doing something = I’m thinking of doing it, I would like to do it:\nLet me know if you’re interested in joining the club. (not to join)\nI tried to sell my car, but nobody was interested in buying it. (not to buy)\nI was interested to hear/see/know something = it was interesting for me.  For example:\nI was interested to hear that Tanya left her job. \n(= I heard this and it was interesting for me)\nI’ll ask Mike for his opinion.  I would be interested to know what he thinks.  \n(= it would be interesting for me to know what he thinks)\nThis structure is the same as surprised to … / glad to … etc. (see Unit 65C):\nI was surprised to hear that Tanya left her job.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nsorry for … and sorry to … \nWe use sorry for (doing) to apologise for something:\n I’m sorry for shouting at you yesterday. (not sorry to shout)\nYou can also say:\nI’m sorry I shouted at you yesterday.\nWe use sorry to … to say that we regret something that happens:\nI’m sorry to hear that Nicky lost her job. (not sorry for)\nI’ve enjoyed my stay here.  I’ll be sorry to leave.\nWe also say ‘I’m sorry to …’ to apologise at the time we do something:\nI’m sorry to bother you, but I need to ask you a question.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nD\nVerb + to … ➜ Units 54–55\nVerb + preposition + -ing ➜ Unit 62\nsorry to … ➜ Unit 65C \nAdjective + preposition ➜ Units 130–131\nsorry about/for ➜ Unit 130\nWe say:\nI want to (do), I’d like to (do)\nI hope to (do)\nI failed to (do)\nI allowed them to (do)\nI plan to (do)\nI promised to (do)\nbut\nI’m thinking of (do)ing\nI dream of (do)ing\nI succeeded in (do)ing\nI prevented them from (do)ing\nI’m looking forward to (do)ing\nI insisted on (do)ing\n132\n</div>",
    exercises: [],
  },
  '67': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPast simple (I did) ➜ Unit 5\nPast continuous (I was doing) ➜ Unit 6\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nsee somebody do and see somebody doing\nStudy this example situation:\nTom got into his car and drove off .  You saw this.\nYou can say:\nI saw Tom get into his car and drive off .\nWe say ‘I saw him do something’ (= he did it\nand I saw this).  In the same way, you can say:\nhear\nlisten to\nwatch\nfeel\nsomebody do something\nsomething happen\nI didn’t hear you come in. (you came in – I didn’t hear this)\nLisa suddenly felt somebody touch her on the shoulder.\nYesterday you saw Kate.  She was waiting for a bus.\nYou can say:\nI saw Kate waiting for a bus.\nWe say ‘I saw her doing something’ (= she was doing it and I saw this).  \nIn the same way, you can say:\nhear\nlisten to\nwatch\nfeel\nsmell\nfind\nsomebody doing something\nsomething happening\nI could hear it raining. (it was raining – I could hear it)\nListen to the birds singing!\nCan you smell something burning?\nWe looked for Paul and finally we found him sitting under a tree eating an apple.\nI saw him do something = he did something and I saw this. \nI saw the complete action from start to finish:\nHe jumped over the wall and ran away.  I saw this. \n→I saw him jump over the wall and run away.\nThey went out.  I heard this.  →  I heard them go out.\nI saw him doing something = he was doing something and I saw this. \nI saw him in the middle of doing something (not from start to finish): \nI saw Tom as I drove past in my car.  He was walking along the street.\n→ I saw Tom walking along the street.\nI heard them.  They were talking.  →  I heard them talking.\nSometimes the diff erence is not important and you can use either form:\nI’ve never seen her dance.    or    I’ve never seen her dancing.\nStudy this example situation:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nStudy the diff erence in meaning:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\ntom\nkate\n134\n</div>",
    exercises: [],
  },
  '68': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n-ing clauses (He hurt his knee playing football.)\nStudy this example:\nKate is in the kitchen.  She’s making coff ee.\nYou can say:\nKate is in the kitchen making coff ee.\nYou can use -ing in this way when two things happen \nat the same time:\nA man ran out of the house shouting.\n(= he ran out of the house and he was shouting)\nDo something!  Don’t just stand there doing nothing!\nBe careful crossing the road.\nWe also use -ing when one action happens during another action:\nJoe hurt his knee playing football. (= while he was playing)\nDid you cut yourself shaving? (= while you were shaving)\nYou can also say ‘while doing something’ and ‘when doing something’:\nJoe hurt his knee while playing football.\nBe careful when crossing the road. (= when you are crossing)\n-ing clause\nWhen one action happens before something else, we use having (done) for the first action:\nHaving found a hotel, we looked for somewhere to eat.\nHaving finished her work, she went home.\nYou can also say aft er -ing:\nAft er finishing her work, she went home.\nThese structures are used more in written English than in spoken English.\nWhen we begin a sentence with ‘Having (done something)’ or ‘Aft er (doing something)’, we \nwrite a comma (,) aft er this part of the sentence:\nHaving finished her work, she went home.\ncomma\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can also use -ing to explain something, or to say why somebody does something. \nThe sentence usually begins with -ing:\nFeeling tired, I went to bed early. (= because I felt tired)\nBeing unemployed, he doesn’t have much money. (= because he is unemployed)\nNot having a car, she finds it diff icult to get around.\n(= because she doesn’t have a car)\nWe use having (done) for something that is complete before something else:\nHaving seen the film twice, I didn’t want to see it again.\n(= because I had seen it twice)\nThese structures are used more in written English than in spoken English. \nWhen we begin a sentence with -ing (Feeling tired … / Not knowing … / Having seen … etc.), we write \na comma (,) aft er this part of the sentence.\nNot knowing what to do, I called my friend to ask her advice.\n-ing clause\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\n136\n</div>",
    exercises: [],
  },
  '69': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nCountable and uncountable 1\nA noun can be countable or uncountable:\nCountable\nI eat a banana every day.\nI like bananas.\nBanana is a countable noun.\nA countable noun can be singular (banana)\nor plural (bananas).\nWe can use numbers with countable nouns.\nSo we can say one banana, two bananas\netc.\nExamples of nouns usually countable:\nKate was singing a song.\nThere’s a nice beach near here.\nDo you have a ten-pound note?\nIt wasn’t your fault.  It was an accident.\nThere are no batteries in the radio.\nWe don’t have enough cups.\nUncountable\nI eat rice every day.\nI like rice.\nRice is an uncountable noun.\nAn uncountable noun has only one form (rice). \nThere is no plural.\nWe cannot use numbers with uncountable\nnouns.  We cannot say ‘one rice’, ‘two rices’\netc.\nExamples of nouns usually uncountable:\nKate was listening to music.\nThere’s sand in my shoes.\nDo you have any money?\nIt wasn’t your fault.  It was bad luck.\nThere is no electricity in this house.\nWe don’t have enough water.\nYou can use a/an with singular countable\nnouns:\n \na beach \n \na student \n \nan umbrella\nYou cannot use singular countable nouns alone\n(without a/the/my etc.):\nDo you want a banana?    \n(not want banana)\nThere’s been an accident.\n \n(not There’s been accident)\nYou can use plural countable nouns alone:\nI like bananas. (= bananas in general)\nAccidents can be prevented.\nWe do not use a/an with uncountable nouns.  \nWe do not say ‘a sand’, ‘a music’, ‘a rice’.\nBut you can often use a … of.  For example:\n     a bowl / a packet / a grain of rice\nYou can use uncountable nouns alone\n(without the/my/some etc.):\nI eat rice every day.\nThere’s blood on your shirt.\nCan you hear music? \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use some and any with plural\ncountable nouns:\nWe sang some songs.\nDid you buy any apples?\nWe use many and few with plural countable\nnouns:\nWe didn’t take many pictures.\nI have a few things to do.\nYou can use some and any with uncountable\nnouns:\nWe listened to some music.\nDid you buy any apple juice?\nWe use much and little with uncountable\nnouns:\nWe didn’t do much shopping.\nI have a little work to do.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCountable and uncountable 2 ➜ Unit 70\nchildren / the children ➜ Unit 75\nsome and any ➜ Unit 85\nmany/much/few/little ➜ Unit 87\n138\n</div>",
    exercises: [],
  },
  '70': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nCountable and uncountable 1 ➜ Unit 69\nAmerican English ➜ Appendix 7\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nCountable and uncountable 2\nMany nouns are sometimes countable, and sometimes uncountable.  Usually there is a difference in meaning. \nCompare:\nCoffee/tea/juice/beer etc. (drinks) are normally uncountable:\n I don’t like coffee very much.\nBut you can say a coffee (= a cup of coffee), two coffees (= two cups) etc. :\nTwo coffees and an orange juice, please.\nCountable\nDid you hear a noise just now?\n(= a specific noise)\nI bought a paper to read.\n(= a newspaper)\nThere’s a hair in my soup!\n(= one single hair)\nThis is a nice room.\n(= a room in a house)\nI had some interesting experiences\nwhile I was travelling.\n(= things that happened to me)\nEnjoy your trip.  Have a great time!\nUncountable\nI can’t work here.  There’s too much\n \nnoise. (= noise in general)\nI need some paper to write on.\n(= material for writing on)\nYou’ve got very long hair. (not hairs)\n(= all the hair on your head)\nYou can’t sit here.  There isn’t room.\n(= space)\nI was offered the job because I had a\nlot of experience. (not experiences)\n(= experience of that type of job)\nI can’t wait.  I don’t have time.\nCountable\nI’m looking for a job.\nWhat a beautiful view!\nIt’s a nice day today.\nWe had a lot of bags.\nThese chairs are mine.\nThat’s a good suggestion.\nThere were a lot of cars.\nUncountable\nI’m looking for work. (not a work)\nWhat beautiful scenery!\nIt’s nice weather today.\nWe had a lot of baggage/luggage.\nThis furniture is mine.\nThat’s good advice.\nThere was a lot of traffic.\nThese nouns are usually uncountable:\naccommodation \nbehaviour \ndamage \nluck \npermission \ntraffic\nadvice \nbread \nfurniture \nluggage \nprogress \nweather\nbaggage \nchaos \ninformation \nnews \nscenery \nwork\nWe do not normally use a/an with these nouns:\nI’m going to buy some bread.    or    … a loaf of bread. (not a bread)\nEnjoy your holiday!  I hope you have good weather.    (not a good weather)\nThese nouns are not usually plural (so we do not say ‘breads’, ‘furnitures’ etc.):\nWhere are you going to put all your furniture?   (not furnitures) \nLet me know if you need more information. (not informations) \nNews is uncountable, not plural: \nThe news was unexpected. (not The news were) \nTravel (noun) means ‘travelling in general’ (uncountable).  We do not say ‘a travel’ to mean a trip\nor a journey: \nThey spend a lot of money on travel. \nWe had a very good trip/journey. (not a good travel) \nCompare these countable and uncountable nouns: \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\n140\n</div>",
    exercises: [],
  },
  '71': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nCountable nouns with a/an and some\nCountable nouns can be singular or plural: \na dog \na child \nthe evening \nthis party \nan umbrella\ndogs \nsome children \nthe evenings \nthese parties \ntwo umbrellas\nBefore singular countable nouns you can use a/an:\nBye!  Have a nice evening. \nDo you need an umbrella? \nYou cannot use singular countable nouns alone (without a/the/my etc.): \nShe never wears a hat.   (not wears hat)\nBe careful of the dog. \nWhat a beautiful day!\nDid you hurt your leg?\nWe use a/an … to say what kind of thing something is, or what kind of person somebody is:\n That’s a nice table.\nIn the plural we use the noun alone (not some …):\nThose are nice chairs. (not some nice chairs)\nCompare singular and plural:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use some with plural countable nouns.  We use some in two ways.\n(1) some = a number (of) / a few (of) / a pair (of):\nI’ve seen some good movies recently.   (not I’ve seen good movies) \nSome friends of mine are coming to stay at the weekend. \nI need some new sunglasses.  (= a new pair of sunglasses)\nOften you can say the same thing with or without some.  For example:\nI need (some) new clothes.\nThe room was empty apart from a table and (some) chairs.\nDo not use some when you are talking about things in general (see Unit 75):\nI love bananas.   (not some bananas)\nMy aunt is a writer.  She writes books.   (not some books)\n(2) some = some but not all:\nSome children learn very quickly.  (but not all children)\nTomorrow there will be rain in some places, but most of the country will be dry.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nA dog is an animal.\nI’m an optimist.\nMy father is a doctor.\nJane is a really nice person.\nWhat a lovely dress!\nDogs are animals.\nWe’re optimists.\nMy parents are both doctors.\nJane and Ben are really nice people.\nWhat awful shoes!\nJack has a long nose. \n(not the long nose)\nJack has blue eyes. \n(not the blue eyes)\nWe say that somebody has a long nose / a nice face / blue eyes / long fingers etc. :\nWe use a/an when we say what somebody’s job is:\nSandra is a nurse.   (not Sandra is nurse) \nWould you like to be an English teacher?\nCountable and uncountable ➜ Units 69–70\na/an and the ➜ Unit 72\nsome and any ➜ Unit 85\n142\n</div>",
    exercises: [],
  },
  '72': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\na/an ➜ Unit 71\nthe ➜ Units 73–78\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example:\nJoe says ‘a sandwich’, ‘an apple’ because this is \nthe first time he talks about them.\nJoe now says ‘the sandwich’, ‘the apple’\nbecause we know which sandwich and \nwhich apple he means – the sandwich and\nthe apple he had for lunch.\nI had a sandwich and an apple \nfor lunch.\nThe sandwich wasn’t very good, \nbut the apple was nice.\nJOE\nCompare a and the in these examples:\nA man and a woman were sitting opposite me.  The man was American, but I think the \nwoman was British. \nWhen we were on holiday, we stayed at a hotel.  Sometimes we ate at the hotel and \nsometimes we went to a restaurant.\na/an and the\nWe use the when we are thinking of a specific thing.  Compare a/an and the:\nTim sat down on a chair.  (maybe one of many chairs in the room)\nTim sat down on the chair nearest the door.  (a specific chair)\nDo you have a car?   (not a specific car)\nI cleaned the car yesterday.  (= my car)\nWe use a/an when we say what kind of thing or person we mean.  Compare:\nWe stayed at a very cheap hotel.  (a type of hotel)\nThe hotel where we stayed was very cheap.  (a specific hotel)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say ‘once a week / three times a day / £1.50 a kilo’ etc. :\nI go to the cinema about once a month.\n ‘How much are those potatoes?’   ‘£1.50 a kilo.’\nHelen works eight hours a day, six days a week.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe use the when it is clear which thing or person we mean.  For example, in a room we talk about the \nlight / the floor / the ceiling / the door / the carpet etc. :\nCan you turn off  the light, please?  (= the light in this room)\nI took a taxi to the station.  (= the station in that town)\n(in a shop)  I’d like to speak to the manager, please.  (= the manager of this shop)\nWe also say ‘(go to) the bank / the post off ice’:\nI have to go to the bank and then I’m going to the post off ice. \n(The speaker is usually thinking of a specific bank or post off ice.) \nand ‘(go to) the doctor / the dentist’:\nClare isn’t well.  She’s gone to the doctor.\nI don’t like going to the dentist.\nCompare the and a: \nI have to go to the bank today.\nIs there a bank near here?\nI don’t like going to the dentist.\nMy sister is a dentist. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\n144\n</div>",
    exercises: [],
  },
  '73': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\na/an ➜ Unit 71\na/an and the ➜ Unit 72\nthe 2–4 ➜ Units 74–76\nNames with and without the ➜ Units 77–78\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nthe 1\nWe use the when there is only one of something:\nHave you ever crossed the equator?\n(there is only one equator)\nOur apartment is on the tenth floor.\nBuenos Aires is the capital of Argentina.  \nI’m going away at the end of this month.\nWe use the + superlative (best, oldest etc.):\nWhat’s the longest river in Europe?\nCompare the and a/an (see also Units 71–72):\nThe sun is a star. (= one of many stars)\nThe hotel where we stayed was a very old hotel.\nWe live in an apartment on the tenth floor.\nWhat’s the best way to learn a language?\nTHE EQUATOR\nWe say ‘the same’:\nYour sweater is the same colour as mine.   (not is same colour)\n‘Are these keys the same?’    ‘No, they’re diff erent.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe usually say breakfast/lunch/dinner (without the):\nWhat did you have for breakfast? \nWe had lunch in a very nice restaurant.\nBut we say ‘a big lunch’, ‘a wonderful dinner’, ‘an early breakfast’ etc. \nWe had a very nice lunch.   (not We had very nice lunch)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nWe say: size 43, platform 5 etc.  (without the)\nOur train leaves from platform 5.   (not the platform 5) \nDo you have these shoes in size 43?   (not the size 43) \nIn the same way, we say: room 126, page 29, vitamin A, section B etc. \nF\nWe say: the world \nthe universe \nthe sun \nthe moon \nthe earth\nthe sky \nthe sea \nthe ground \nthe country (= not a town)\nI love to look at the stars in the sky. (not in sky)\nDo you live in a town or in the country?\nThe earth goes round the sun, and the moon goes round the earth. \nWe also use Earth (without the) when we think of it as a planet in space (like Mars, Jupiter etc.).\nWhich is the planet nearest Earth?\nWe say space (without the) when we mean ‘space in the universe’.  Compare:\nThere are millions of stars in space. (not in the space) \nI tried to park my car, but the space was too small. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe say: \n(go to) the cinema, the theatre\nI go to the cinema a lot, but I haven’t been to the theatre for ages. \nTV / television (without the), but the radio\n I watch TV a lot, but I don’t listen to the radio much. \nbut  \nCan you turn off  the television, please?  (the television = the TV set) \nthe internet\nThe internet has changed the way we live.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n146\n</div>",
    exercises: [],
  },
  '74': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nCompare school and the school:\nthe 2   (school / the school etc.)\nEllie is ten years old.  Every day she goes to \nschool.  She’s at school now.  School starts  \nat 9 and finishes at 3.\nWe say a child goes to school or is at school \n(as a student).  We are not thinking of a specific \nschool.  We are thinking of school as a general  \nidea – children learning in a classroom.\nToday Ellie’s mother wants to speak to her  \ndaughter’s teacher.  So she has gone to the \nschool to see her.  She’s at the school now.\nEllie’s mother is not a student.  She is not ‘at\nschool’, she doesn’t ‘go to school’.  If she\nwants to see Ellie’s teacher, she goes to the\nschool (= Ellie’s school, a specific building).\nELLIE\nWhen I leave school, I plan to go  \nto university / go to college.  \n(as a student)\nJoe had an accident last week.  He was \ntaken to hospital.  He’s still in hospital \nnow. (as a patient)\nKen’s brother is in prison for robbery. \n(He is a prisoner.  We are not thinking \nof a specific prison.)\nSarah’s father goes to church every \nSunday. (for a religious service)\nI went to the university to meet \nProfessor Thomas.   \n(as a visitor, not as a student)\nJane has gone to the hospital to visit \nJoe.  She’s at the hospital now.   \n(as a visitor, not as a patient)\nKen went to the prison to visit his \nbrother. (He went as a visitor, not as a \nprisoner.)\nSome workmen went to the church to \nrepair the roof. (a specific building)\nWe use prison (or jail), hospital, university, college and church in a similar way.  We do not use the  \nwhen we are thinking of the general idea of these places and what they are used for.\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWith most other places, you need the.  For example, the station, the cinema (see Units 72C and 73D).\nWe say go to bed / be in bed etc. (not the bed):\nI’m going to bed now. Goodnight.\nDo you ever have breakfast in bed? \nbut\nI sat down on the bed. (a specific piece of furniture) \ngo to work / be at work / start work / finish work etc. (not the work):\nChris didn’t go to work yesterday. \nWhat time do you usually finish work?\ngo home / come home / arrive home / get home / be (at) home / do something at home etc. :\nIt’s late.  Let’s go home. \nI don’t go out to work.  I work at home.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nthe ➜ Units 72–73, 75 –78\nPrepositions (at school / in hospital etc.) ➜ Units 123–125\nhome ➜ Unit 126C\nAmerican English ➜ Appendix 7\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n148\n</div>",
    exercises: [],
  },
  '75': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nthe 1–2 ➜ Units 73–74\nthe + adjective (the young / the English etc.) ➜ Unit 76\nWhen we are talking about things or people in general, we do not use the:\nI’m afraid of dogs. (not the dogs)\n(dogs = dogs in general, not a specific group of dogs)\nDoctors are usually paid more than teachers.\nDo you know anybody who collects stamps?\nLife has changed a lot in the last thirty years.\nDo you like classical music / Chinese food / fast cars?\nMy favourite sport is football/skiing/athletics.\nMy favourite subject at school was history/physics/English.\nWe say ‘most people / most shops / most big cities’ etc. (not the most …):\nMost shops accept credit cards. (not The most shops)\nthe 3 (children / the children)\nWe use the when we mean specific things or people.\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nThe diff erence between ‘something in general’ and ‘something specific’ is not always very clear.\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nIn general (without the)\nChildren learn from playing.\n(= children in general)\nI couldn’t live without music.\nAll cars have wheels.\nSugar isn’t very good for you.\nEnglish people drink a lot of tea.\n(= English people in general)\nSpecific people or things (with the)\nWe took the children to the zoo.\n(= a specific group, perhaps the\nspeaker’s children)\nThe film wasn’t very good, but I liked\nthe music. (= the music in the film)\nAll the cars in this car park belong to\npeople who work here.\nCan you pass the sugar, please?\n(= the sugar on the table)\nThe English people I know drink a lot\nof tea. (= only the English people I\nknow, not English people in general)\nIn general (without the)\nI like working with people.\n(= people in general)\nI like working with people who say \nwhat they think.\n(not all people, but ‘people who say \nwhat they think’ is still a general idea)\nDo you like coff ee?\n(= coff ee in general)\nDo you like strong black coff ee?\n(not all coff ee, but ‘strong black coff ee’ is \nstill a general idea)\nSpecific people or things (with the)\nI like the people I work with. \n(= a specific group of people)\nThe coff ee we had aft er dinner \nwasn’t very good. (= specific coff ee)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n150\n</div>",
    exercises: [],
  },
  '76': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\na/an and the ➜ Unit 72\nthe ➜ Units 73–75\nNames with and without the ➜ Units 77–78\nStudy these sentences:\nThe giraff e is the tallest of all animals.\nThe bicycle is an excellent means of transport.\nWhen was the camera invented?\nThe dollar is the currency of the United States.\nIn these examples, the … does not mean one specific thing.\nThe giraff e = a specific type of animal, not a specific giraff e. \nWe use the … in this way to talk about a type of animal, \nmachine etc.\nIn the same way we use the for musical instruments:\nCan you play the guitar?\nThe piano is my favourite instrument.\nCompare a and the:\nI’d like to have a piano. \nbut I can’t play the piano.\nWe saw a giraff e at the zoo. but The giraff e is my favourite animal.\nNote that man (without the) = human beings in general, the human race:\nWhat do you know about the origins of man? (not the man)\nthe 4 (the giraﬀ e / the telephone / the old etc.)\nthe old, the rich etc.\nWe use the + adjective (without a noun) to talk about groups of people.  For example:\nthe old\nthe elderly\nthe rich\nthe poor\nthe homeless\nthe unemployed\nthe sick\nthe injured\nthe old = old people, the rich = rich people etc. :\nDo you think the rich should pay higher taxes?\nWe need to do more to help the homeless.\nNote that we say: the old (not the olds), the poor (not the poors) etc.\nThe rich, the homeless etc. are plural.  For one person, we say:\na rich man  (not a rich) \na homeless person  (not a homeless) \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nthe French, the Chinese etc.\nWe use the + a few nationality adjectives that end in -ch or -sh.  For example:\nthe French \n the Dutch \n the British \n the English \nthe Spanish\nThe meaning is plural – the people of that country.\nThe French are famous for their food.   (not French are …)\nWe do not say ‘a French’ or ‘an English’ (singular).  For example, we say:\n I met a French woman / an English guy.\nWe also use the + nationality words ending in -ese or -ss.  For example:\n the Chinese \n the Portuguese \n the Swiss\nThese words can also be singular (a Chinese, a Swiss etc.).\nWith other nationality words, the plural ends in -s (usually without the).  For example:\n \n an Italian → Italians \n a Mexican → Mexicans \n a Thai → Thais\nItalians / Mexicans / Thais are very friendly.\nIn all cases you can use adjective + people.  For example, you can say:\nFrench / Chinese / Mexican people are very friendly.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nA\n152\n</div>",
    exercises: [],
  },
  '77': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nNames with and without the 2 ➜ Unit 78\nWe do not use the with names of people (‘Helen’, ‘Helen Taylor’ etc.).  In the same way, we do\nnot use the with most names of places.  For example:\ncontinents\ncountries, states etc.\nislands\ncities, towns etc.\nmountains\nAfrica (not the Africa), South America\nFrance (not the France), Japan, Texas\nSicily, Tasmania\nCairo, Bangkok\nEverest, Kilimanjaro\nBut we normally use the in names with Republic, Kingdom, States etc. :\nthe Czech Republic \nthe United Kingdom (the UK)\nthe Dominican Republic \nthe United States of America (the USA)\nCompare:\nHave you been to Canada or the United States?\nNames with and without the  1 \nWhen we use Mr/Ms/Captain/Doctor etc. + a name, we do not use the.  So we say:\n \nMr Johnson / Doctor Johnson / Captain Johnson / President Johnson etc. (not the …)\n \nUncle Robert / Saint Catherine / Queen Catherine etc. (not the …)\nCompare:\nWe called the doctor.\nWe called Doctor Johnson.  (not the Doctor Johnson)\nWe use Mount (= mountain) and Lake before a name in the same way (without the):\nMount Everest (not the …) \n \nMount Etna \n \nLake Superior \n \nLake Victoria\nThey live near the lake.\nThey live near Lake Superior. (not the Lake Superior)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use the with the names of oceans, seas, rivers and canals:\nthe Atlantic (Ocean) \nthe Red Sea \nthe Amazon\nthe Indian Ocean \nthe Channel (between \nthe Nile\nthe Mediterranean (Sea) \nFrance and Britain) \nthe Suez Canal\nWe use the with the names of deserts:\nthe Sahara (Desert) \nthe Gobi Desert\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe use the with plural names of people and places:\npeople\ncountries\ngroups of islands\nmountain ranges\nthe Taylors (= the Taylor family), the Johnsons\nthe Netherlands, the Philippines, the United States\nthe Canaries (or  the Canary Islands), the Bahamas\nthe Andes, the Alps, the Urals\nThe highest mountain in the Andes is (Mount) Aconcagua.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe say:\nthe north (of Brazil) \nbut \nnorthern Brazil (without the)\nthe southeast (of Spain) \nbut \nsoutheastern Spain\nCompare:\nSweden is in northern Europe; Spain is in the south.\nWe also use north/south etc. (without the) in the names of some regions and countries:\nNorth America \n \nSouth Africa \n \nsoutheast Asia\nNote that on maps, the is not usually included in the name.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nA\n154\n</div>",
    exercises: [],
  },
  '78': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nNames with and without the 1 ➜ Unit 77\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nNames without the\nWe do not use the with names of most city streets/roads/squares/parks etc. :\nUnion Street (not the …) \nFifth Avenue \nHyde Park\nAbbey Road \nBroadway \nTimes Square\nNames of many public buildings and institutions (airports, stations, universities etc.), and also some  \ngeographical names, are two words:\nManchester Airport \nHarvard University\nThe first word is the name of a place (‘Manchester’) or a person (‘Harvard’).  These names are\nusually without the.  In the same way, we say:\nVictoria Station (not the …) \nCanterbury Cathedral \nEdinburgh Castle\nBuckingham Palace \nCambridge University \nSydney Harbour\nCompare:\nBuckingham Palace (not the …)    but    the Royal Palace\n(‘Royal’ is an adjective – it is not a name like ‘Buckingham’.)\nNames with and without the  2\nMost other buildings have names with the.  For example:\nhotels\ntheatres/cinemas\nmuseums\nother buildings\nthe Sheraton Hotel, the Holiday Inn\nthe Palace Theatre, the Odeon (cinema)\nthe Guggenheim Museum, the National Gallery\nthe Empire State (Building), the White House, the Eiffel Tower\nWe often leave out the noun:\nthe Sheraton (Hotel) \nthe Palace (Theatre) \nthe Guggenheim (Museum)\nSome names are only the + noun, for example:\nthe Acropolis \nthe Kremlin \nthe Pentagon\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nNames with of usually have the.  For example:\nthe Bank of England\nthe Museum of Modern Art\nthe Great Wall of China\nthe Tower of London\nNote that we say:\nthe University of Cambridge    but    Cambridge University (without the)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nMany shops, restaurants, hotels etc. are named after people.  These names end in -’s or -s.  We do not use \nthe with these names:\nMcDonald’s (not the …) \nBarclays (bank)\nJoe’s Diner (restaurant) \nMacy’s (department store)\nChurches are often named after saints (St = Saint):\nSt John’s Church (not the …) \nSt Patrick’s Cathedral\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nMost newspapers and many organisations have names with the:\nthe Washington Post \nthe Financial Times \nthe Sun (newspaper)\nthe European Union \nthe BBC \nthe Red Cross\nNames of companies, airlines etc. are usually without the:\nFiat (not the Fiat) \nSony \nSingapore Airlines\nKodak \nIBM \nYale University Press\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n156\n</div>",
    exercises: [],
  },
  '79': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nAmerican English ➜ Appendix 7\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSometimes we use a plural noun for one thing that has two parts.  For example:\ntrousers (two legs)\nalso jeans/tights/shorts/pants\npyjamas\n(top and bottom)\nglasses\nbinoculars\nscissors\nThese words are plural, so they take a plural verb:\nMy trousers are too long. (not My trousers is)\nYou can also use a pair of + these words:\nThose are nice jeans. \nor    That’s a nice pair of jeans. (not a nice jeans)\nI need some new glasses.    or    I need a new pair of glasses.\nSingular and plural\nSome nouns end in -ics, but are not usually plural.  For example:\nathletics \n \ngymnastics \n \neconomics \n \npolitics \n \nphysics \nelectronics \nmaths (= mathematics)\nGymnastics is my favourite sport. (not Gymnastics are)\nNews is not plural (see Unit 70B):\nI have some news for you.  It’s good news!  \nSome words that end in -s can be singular or plural.  For example:\nmeans \na means of transport \nmany means of transport\nseries\na TV series\ntwo TV series\nspecies \na species of fish \n200 species of fish\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nC\nSome singular nouns are often used with a plural verb.  For example:\naudience \n committee \n company \n family \n firm \n government \n staff \n team\nThese nouns are all groups of people.  We often think of them as a number of people (= they),\nnot as one thing (= it).  So we often use a plural verb:\nThe government (= they) have decided to increase taxes.\n The staff at the company (= they) are not happy with their working conditions.\nIn the same way, we often use a plural verb after the name of a company or a sports team:\nShell have increased the price of petrol.\nItaly are playing Brazil next Sunday (in a football match).\nYou can also use a singular verb (The government wants … / Shell has … etc.).\nWe use a plural verb with police:\nThe police are investigating the crime, but haven’t arrested anyone yet.\n \n(not The police is … hasn’t)\nNote that we say a police officer / a policeman / a policewoman (not a police).\nWe do not often use the plural of person (‘persons’).  We normally use people (a plural word):\nHe’s a nice person.    but    They are nice people. (not nice persons)\nMany people don’t have enough to eat. (not Many people doesn’t)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe think of a sum of money, a period of time, a distance etc. as one thing.  So we use a singular verb:\nFifty thousand pounds (= it) was stolen in the robbery. (not were stolen)\nThree years (= it) is a long time to be without a job. (not Three years are)\nTwo miles isn’t very far to walk.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n158\n</div>",
    exercises: [],
  },
  '80': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n-’s and of … ➜ Unit 81\na week’s holiday / three weeks’ holiday etc. ➜ Unit 81E\nYou can use two nouns together (noun + noun) to mean one thing/person/idea etc. :\na bus driver \n \nincome tax \nthe city centre \n \nan apple tree\nThe first noun is like an adjective.  It tells us what kind of thing/person/idea etc. :\na bus driver = the driver of a bus\nincome tax = tax that you pay on your income\nthe city centre = the centre of the city\nan apple tree = a tree that has apples\na Paris hotel = a hotel in Paris\nmy life story = the story of my life\nSo you can say:\na television camera \na television programme \na television studio \na television producer\n(things or people to do with television)\nlanguage problems \nmarriage problems \nhealth problems \nwork problems\n(different kinds of problems)\nSometimes the first word ends in -ing:\na frying pan (= a pan for frying)\na washing machine\na swimming pool\nNoun + noun (a bus driver / a headache)\nSometimes there are more than two nouns together:\nI waited at the hotel reception desk.\nWe watched the World Swimming Championships on TV.\nIf you want to play table tennis (= a game), you need a table tennis table (= a table).\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWhen two nouns are together like this, sometimes we write them as one word and sometimes as two  \nseparate words.  For example:\na headache \n \ntoothpaste \n \na weekend \n \na car park \n \na road sign\nThere are no clear rules for this.  If you are not sure, write two words.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nNote the difference between:\na coffee cup (maybe empty) and a cup of coffee (= a cup with coffee in it)\na shopping bag (maybe empty) and a bag of shopping (= a bag full of shopping)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWhen we use noun + noun, the first noun is like an adjective.  It is normally singular, but the\nmeaning is often plural. \nFor example: a car park is a place to park cars, an apple tree is a tree that has apples.\nIn the same way we say:\na three-hour journey  (= a journey that takes three hours)\na ten-pound note  (= a note with the value of ten pounds)\na four-week course  \na six-mile walk\ntwo 14-year-old girls \nCompare:\n It was a four-week course. (not a four weeks course)\nbut \nThe course lasted four weeks.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nA\n160\n</div>",
    exercises: [],
  },
  '81': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n-’s (your sister’s name) and  \nof … (the name of the book)\nWe use -’s (apostrophe + s) mostly for people or animals:\nTom’s computer isn’t working. (not the computer of Tom)\nHow old are Chris’s children?   (not the children of Chris)\nWhat’s (= What is) your sister’s name?\nWhat’s Tom’s sister’s name?\nBe careful.  Don’t step on the cat’s tail.\nYou can use -’s without a noun after it:\nThis isn’t my book.  It’s my sister’s. (= my sister’s book)\nWe do not use -’s after a long group of words.  So we say: \nmy friend’s mother  \nbut the mother of the man we met yesterday  (not the man we met yesterday’s mother)\nNote that we say a woman’s hat (= a hat for a woman), a boy’s name  (= a name for a boy),\na bird’s egg (= an egg laid by a bird) etc.\nWith a singular noun we use -’s:\nmy sister’s room  (= her room – one sister)          \nMr Carter’s house  (= his house)\nWith a plural noun (sisters, friends etc.) we put an apostrophe (’) after s:\nmy sisters’ room  (= their room – two or more sisters)\nthe Carters’ house  (= their house – Mr and Mrs Carter)\nIf a plural noun does not end in -s (for example men/women/children/people) we use -’s:\nthe men’s changing room          a children’s book  (= a book for children)\nYou can use -’s after more than one noun:\nJack and Karen’s children          Mr and Mrs Carter’s house\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nFor things, ideas etc., we normally use of:\nthe temperature of the water  (not the water’s temperature)\nthe name of the book \n the owner of the restaurant\nWe say the beginning/end/middle of … / the top/bottom of … / the front/back/side of … :\nthe beginning of the month (not the month’s beginning)\nthe top of the hill                           the back of the car\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can usually use -’s or of … for an organisation (= a group of people).  So you can say:\nthe government’s decision     or     the decision of the government\nthe company’s success \n or the success of the company\nWe also use -’s for places.  So you can say:\nthe city’s streets         the world’s population         Italy’s prime minister\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe use -’s with time words (yesterday / next week etc.):\nDo you still have yesterday’s newspaper?\n Next week’s meeting has been cancelled.\nIn the same way, you can say today’s / tomorrow’s / this evening’s / Monday’s etc.\nWe also use -’s (or -s’ with plural words) with periods of time:\nI’ve got a week’s holiday starting on Monday.\nJulia has got three weeks’ holiday.\nI live near the station – it’s only ten minutes’ walk.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nNoun + noun (a bus driver) ➜ Unit 80\na three-hour journey, a ten-pound note ➜ Unit 80E \n-’s (= is or has) in short forms ➜ Appendix 5.2\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n162\n</div>",
    exercises: [],
  },
  '82': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nget dressed / get married etc. ➜ Unit 44D\nby myself / by yourself etc. ➜ Unit 83D\nmyself/yourself/themselves etc.\nStudy this example:\nThe reflexive pronouns are:\nsingular (-self) \nmyself \nyourself (one person) \nhimself/herself/itself\nplural (-selves) \nourselves \nyourselves (more than one) \nthemselves\nI don’t want you to pay for me.  I’ll pay for myself. (not I’ll pay for me)\nAmy had a great holiday.  She really enjoyed herself.\nDo you talk to yourself sometimes?   (said to one person)\nIf you want more to eat, help yourselves. (said to more than one person)\nCompare:\nLisa introduced me to the other guests.\nI introduced myself to the other guests.\nSteve introduced himself to the other guests.\nWe use myself/yourself/himself etc. (reflexive pronouns)\nwhen the subject and object are the same:\n Steve  introduced  himself \nsubject\nobject\nWe do not use myself etc. aft er feel/relax/concentrate/meet:\nI feel nervous.  I can’t relax.\nYou need to concentrate. (not concentrate yourself)\nWhat time shall we meet tomorrow? \nNormally we do not use myself etc. aft er wash/shave/dress:\n He got up, washed, shaved and dressed. (not washed himself etc.)\nYou can also say get dressed (He got dressed).\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare -selves and each other:\nKate and Joe stood in front of the mirror and looked\n \nat themselves. \n(= Kate and Joe together looked at Kate and Joe)\nKate looked at Joe, and Joe looked at Kate.  They looked\n \nat each other.\nYou can use one another instead of each other:\nHow long have you and Ben known each other?     or     … known one another?\nSue and Alice don’t like each other.     or     … don’t like one another.\nDo they live near each other?     or     … near one another?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nthemselves\neach other\nWe also use myself/yourself etc. in another way.  For example:\n‘Who repaired your bike?’ \n‘I repaired it myself.’\nI repaired it myself = I repaired it, not another person.  Here, myself is used to emphasise ‘I’\n(= it makes it stronger).  Some more examples:\nI’m not going to do your work for you.  You can do it yourself. (= you, not me)\nLet’s paint the house ourselves.  It will be much cheaper.\nThe film itself wasn’t very good, but I loved the music.\nI don’t think Lisa will get the job she applied for.  Lisa doesn’t think so herself.    or\nLisa herself doesn’t think so.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nA\nHi, I’m Steve.\n164\n</div>",
    exercises: [],
  },
  '83': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nmyself/yourself/themselves etc. ➜ Unit 82\na friend of mine  my own house\non my own / by myself\na friend of mine / a friend of yours etc.\nWe say ‘(a friend) of mine/yours/his/hers/ours/theirs’.  \nA friend of mine = one of my friends:\nI’m going to a wedding on Saturday.  A friend of mine is getting married. (not a friend of me)\nWe went on holiday with some friends of ours. (not some friends of us)\nHarry had an argument with a neighbour of his.\nIt was a good idea of yours to go to the cinema.\nIn the same way we say ‘(a friend) of my sister’s / (a friend) of Tom’s’ etc. :\nThat woman over there is a friend of my sister’s. (= one of my sister’s friends)\nIt was a good idea of Tom’s to go to the cinema.\nmy own … / your own … etc.\nWe say my own / your own / her own … etc. :\nmy own house          your own car          her own room \n(not an own house, an own car etc.)\nmy own … / your own … etc. = something that is only mine/yours, not shared or borrowed:\nI don’t want to share a room with anybody.  I want my own room.\nVicky and Gary would like to have their own house.\nIt’s a shame that the apartment hasn’t got its own parking space.\nIt’s my own fault that I have no money.  I buy too many things I don’t need.\nWhy do you want to borrow my car?  Why don’t you use your own? (= your own car)\nYou can also say ‘a room of my own’, ‘a house of your own’, ‘problems of his own’ etc. :\nI’d like to have a room of my own.\nHe won’t be able to help you with your problems.  He has too many problems of his own.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nHe cuts his own hair\nWe also use own to say that we do something ourselves instead of somebody else doing it\nfor us.  For example:\nPaul usually cuts his own hair.\n(= he cuts it himself)\nI’d like to have a garden so that\nI could grow my own vegetables.\n(= grow them myself instead of\nbuying them from shops)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\non my own / by myself\nOn my own and by myself both mean ‘alone’.  So you can say:\nmy / your\non his / her / its own\nour / their\nor\nmyself / yourself (singular)\nby himself / herself / itself\nourselves / yourselves (plural) / themselves\nI like living on my own.    or    I like living by myself.\nSome people prefer to live on their own.    or    … live by themselves.\nJack was sitting on his own in a corner of the cafe.    or    Jack was sitting by himself … \nDid you go on holiday on your own?    or    Did you go on holiday by yourself? \n⎫⎪⎬⎪⎭\n⎫⎪⎬⎪⎭\n⎫⎪⎬⎪⎭\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nPaUL\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n166\n</div>",
    exercises: [],
  },
  '84': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nthere … and it …\nStudy this example:\nWe use there … when we talk about something for the first time, to say that it exists:\nThere’s a new restaurant in Hill Street.\nI’m sorry I’m late.  There was a lot of traff ic. (not It was a lot of traff ic)\nThings are very expensive now.  There has been a big rise in the cost of living.\nIt = a specific thing, place, fact, situation etc. :\nWe went to the new restaurant.  It’s very good. (It = the restaurant)\nI wasn’t expecting her to call me.  It was a complete surprise. (It = that she called)\nCompare there and it:\nI like this town.  There’s a lot to do here.  It’s an interesting place.\nThere also means ‘to/at/in that place’:\nThe house is unoccupied.  There’s nobody living there. (= in the house) \nYou can say:\nthere will be\nthere must be\nthere might be  etc.\nthere must have been\nthere should have been \nthere would have been  etc.\nthere is sure to be\nthere is bound to be\nthere is going to be\nthere is likely to be\nthere is supposed to be\nthere used to be\n‘Is there a flight to Rome tonight?’ \n‘There might be.  I’ll check online.’\nIf people drove more carefully, there wouldn’t be so many accidents.\nI could hear music coming from the house.  There must have been somebody at home.\nThere’s bound to be a cafe somewhere near here. (= There’s sure to be …)\nCompare there and it:\nThey live on a busy road.  There must be a lot of noise from the traff ic.\nThey live on a busy road.  It must be very noisy. (It = living on a busy road)\nThere used to be a cinema here, but it closed a few years ago.\nThat building is now a supermarket.  It used to be a cinema. (It = that building)\nThere’s sure to be a flight to Rome tonight. \nThere’s a flight to Rome tonight, but it’s sure to be full. (it = the flight)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say:\nIt’s dangerous to walk in the road. (not To walk in the road is dangerous)\nNormally we use It … at the beginning of sentences like this.  Some more examples:\nIt didn’t take us long to get here.\nIt’s a shame (that) you can’t come to the party.\nIt’s not worth waiting any longer.  Let’s go.\nWe also use it to talk about distance, time and weather:\nHow far is it from here to the airport?\nIt’s a long time since we last saw you.\nCompare it and there:\nIt was windy.  but  There was a cold wind.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nsupposed to … ➜ Unit 45B\nit’s worth / it’s no use / there’s no point ➜ Unit 63A\nsure to / bound to … etc. ➜ Unit 65E\nthere is + -ing/-ed ➜ Unit 97\nThere’s a new restaurant \nin Hill Street.\nYes, I know.  I’ve heard \nit’s very good.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n168\n</div>",
    exercises: [],
  },
  '85': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nnot … any ➜ Unit 86\nsome of / any of … ➜ Unit 88\nhardly any ➜ Unit 101C\nsome and any\nIn general we use some (also somebody/someone/something) in positive sentences and any \n(also anybody etc.) in negative sentences:\nWe use any in the following sentences because the meaning is negative:\nShe went out without any money. (she didn’t take any money with her)\nHe refused to eat anything. (he didn’t eat anything)\nIt’s a very easy exam.  Hardly anybody fails. (= almost nobody fails)\nsome\nWe bought some flowers.\nHe’s busy.  He has some work to do.\nThere’s somebody at the door.\nI want something to eat.\nany\nWe didn’t buy any flowers.\nHe’s lazy.  He never does any work.\nThere isn’t anybody at the door.\nI don’t want anything to eat.\nWe use both some and any in questions.  We use some/somebody/something to talk about a person  \nor thing that we know exists, or we think exists:\nAre you waiting for somebody? (I think you are waiting for somebody)\nWe use some in questions when we ask for or offer things:\nCan I have some sugar, please? (there is probably some sugar that I can have)\nWould you like something to eat? (there is something to eat)\nBut in most questions, we use any.  We do not know if the thing or person exists:\nDo you have any luggage? (maybe you do, maybe not)\nIs there anybody in the house? (maybe there is, maybe not)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use if + any:\nLet me know if you need anything.\nIf anyone has any questions, I’ll be pleased to answer them.\nThe following sentences have the idea of if:\nI’m sorry for any trouble I’ve caused. (= if I have caused any trouble)\nThe police want to speak to anyone who saw the accident. (= if there is anyone)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe also use any with the meaning ‘it doesn’t matter which’:\nYou can take any bus.  They all go to the centre. (= it doesn’t matter which bus you take)\nCome and see me any time you want.\nWe use anybody/anyone/anything/anywhere in the same way:\n We forgot to lock the door.  Anybody could have come in. \nCompare some- and any-:\na: I’m hungry.  I want something to eat.\nb: What would you like?\na: I don’t mind.  Anything. (= it doesn’t matter what)\nb: Let’s go out somewhere.\na: Where shall we go?\nb: Anywhere.  I just want to go out.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nSomebody/someone/anybody/anyone are singular words:\nSomeone is here to see you.\nBut we use they/them/their after these words:\nSomeone has forgotten their umbrella. (= his or her umbrella)\nIf anybody wants to leave early, they can. (= he or she can)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nA\n170\n</div>",
    exercises: [],
  },
  '86': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nno/none/any \n \nnothing/nobody etc.\nno and none\nWe use no + noun (no bus, no shops etc.).   \nno = not a or not any:\nWe had to walk home.  There was no bus. (= There wasn’t a bus.)\nSarah will have no trouble finding a job. (= Sarah won’t have any trouble …)\nThere were no shops open. (= There weren’t any shops open.)\nYou can use no + noun at the beginning of a sentence:\n No reason was given for the change of plan.\nWe use none without a noun:\n‘How much money do you have?’ \n‘None.’ (= no money)\n All the tickets have been sold.  There are none left. (= no tickets left)\nOr we use none of … :\nThis money is all yours.  None of it is mine.\nCompare no, none and any:\nI have no luggage.\n‘How much luggage do you have?’ \n‘None.’    or    ‘I don’t have any.’\nAfter none of + plural (none of the students, none of them etc.) the verb can be singular or plural:\nNone of the students were happy.    or    None of the students was happy.\nnothing      nobody/no-one       nowhere\nYou can use these words at the beginning of a sentence or alone (as answers to questions):\n‘What’s going to happen?’ \n‘Nobody knows. / No-one knows.’\n‘What happened?’ \n‘Nothing.’\n‘Where are you going?’ \n‘Nowhere.  I’m staying here.’\nYou can also use these words after a verb, especially after be and have:\nThe house is empty.  There’s nobody living there.\nWe had nothing to eat.\nnothing/nobody etc. = not + anything/anybody etc. :\nI said nothing.   =   I didn’t say anything.\nJane told nobody about her plans.   =   Jane didn’t tell anybody about her plans.\nThey have nowhere to live.   =   They don’t have anywhere to live.\nWith nothing/nobody etc., we do not use a negative verb (isn’t, didn’t etc.):\nI said nothing. (not I didn’t say nothing)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nAfter nobody/no-one you can use they/them/their (see also Unit 85E):\nNobody is perfect, are they? (= is he or she perfect?)\nNo-one did what I asked them to do. (= him or her)\nNobody in the class did their homework. (= his or her homework)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSometimes any/anything/anybody etc. means ‘it doesn’t matter which/what/who’ (see Unit 85D).  \nCompare no- and any-:\nThere was no bus, so we walked home.\nYou can take any bus.  They all go to the centre. (= it doesn’t matter which bus)\n‘What do you want to eat?’ \n‘Nothing.  I’m not hungry.’\nI’m so hungry.  I could eat anything. (= it doesn’t matter what)\nIt’s a difficult job.  Nobody wants to do it.\nIt’s a very easy job.  Anybody can do it. (= it doesn’t matter who)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nsome and any ➜ Unit 85\nnone of … ➜ Unit 88\nany bigger / no better etc. ➜ Unit 106B\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n172\n</div>",
    exercises: [],
  },
  '87': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nCountable and uncountable ➜ Units 69–70\nmuch, many, little, few, a lot, plenty\nWe use much and little with uncountable nouns: \nmuch luck \n \nmuch time \n \nlittle energy \n \nlittle money\nWe use many and few with plural nouns:\nmany friends \n \nmany people \n \nfew cars \n \nfew children\nWe use a lot of / lots of / plenty of with both uncountable and plural nouns:\na lot of luck \nlots of time \nplenty of money\na lot of friends \nlots of people \nplenty of ideas\nplenty = more than enough:\nThere’s no need to hurry.  We’ve got plenty of time.\nThere’s plenty to do in this town.\nMuch is unusual in positive sentences (especially in spoken English).  Compare:\nWe didn’t spend much money.    but    We spent a lot of money. \n Do you see David much?                   but    I see David a lot. \nBut we use too much / so much / as much in positive sentences:\nWe spent too much money.\nWe use many and a lot of in all kinds of sentences:\nMany people drive too fast. \nor A lot of people drive too fast.\nDo you know many people? \nor Do you know a lot of people?\nThere aren’t many tourists here.    or    There aren’t a lot of tourists here.\nNote that we say many years / many weeks / many days:\nWe’ve lived here for many years. (not usually a lot of years)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nlittle = not much,  few =  not many:\nGary is very busy with his job.  He has little time for other things.  \n(= not much time, less time than he would like)\nVicky doesn’t like living in London.  She has few friends there. \n(= not many friends, not as many as she would like)\nWe often use very little and very few:\nGary has very little time for other things.\nVicky has very few friends in London.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\na little = some, a small amount:\nLet’s go and have coffee.  We have a little time before the train leaves.\n \n(a little time = some time, enough time to have a coffee)\n‘Do you speak English?’ \n‘A little.’  (so we can talk a bit)\na few = some, a small number:\nI enjoy my life here.  I have a few friends and we meet quite often.\n \n(a few friends = not many, but enough to have a good time)\n‘When was the last time you saw Clare?’ \n‘A few days ago.’  (= 3 or 4 days ago)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nCompare little and a little, few and a few:\nHe spoke little English, so it was difficult to communicate with him.\nHe spoke a little English, so we were able to communicate with him.\nShe’s lucky.  She has few problems. (= not many problems)\nThings are not going so well for her.  She has a few problems. (= some problems)\nWe say only a little (not only little) and only a few (not only few):\nHurry!  We only have a little time. (= some, but not much time)\nThe village was small.  There were only a few houses. (= some but not many houses)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nA\n174\n</div>",
    exercises: [],
  },
  '88': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nall / all of  most / most of  no / none of etc.\nall \n \nsome \n \nany \n \nmost \n \nmuch \n \nmany \n \n(a) littl e \n(a) few \n \nno\nYou can use these words with a noun (some food / few books etc.):\nAll cars have wheels.\nSome cars can go faster than others.\nMany people drive too fast.\nI go away most weekends.\nI feel really tired.  I’ve got no energy.\nWe do not say ‘all of cars’, ‘some of people’ etc. (see Section B):\nSome people learn more easily than others. (not Some of people)\nall  \nhalf  \nsome  \nany  \nmost  \nmuch  \nmany  \n(a) little\n(a) few\nnone\nYou can use these words with of (some of / most of etc.):\nsome of\nmost of\nnone of   etc.\n+\nthe … \nmy … \nthis … \nthese … \nthat … \nthose … etc.\nSo you can say:\nsome of the people, some of those people  (but not some of people) \n \nmost of my time, most of the time  (but not most of time)\nSome of the people I work with are very strange.\nNone of this money is mine.\nHave you read any of these books?\nI was ill yesterday.  I spent most of the day in bed.\nYou don’t need of after all or half.  So you can say:\nAll my friends live near here.    or    All of my friends …\nHalf this money is mine.    or    Half of this money …\nCompare:\nAll flowers are beautiful. (= all flowers in general)\n \nAll (of) these flowers are beautiful. (= a specific group of flowers)\nMost problems have a solution. (= most problems in general)\nWe were able to solve most of the problems we had. (= a specific group of problems)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use all of / some of / none of etc. + it/us/you/them:\nall of\nsome of\nany of \nmost of \nnone of\n    etc.\n+\nit\nus \nyou \nthem \na: Do you like this music? \nb: Some of it.  Not all of it. \na: How many of these people do you know? \nb: None of them. / A few of them.\nDo any of you want to come to a party tonight? \n(said to more than 2 people)\nWe say: all of us / all of you / half of it / half of them etc.  You need of before it/us/you/them:\nAll of us were late. (not all us)\nI haven’t finished the book yet.  I’ve only read half of it. (not half it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe also use some/most etc. alone, without a noun:\nSome cars have four doors and some have two.\nA few of the shops were open, but most (of them) were closed.\nHalf this money is mine, and half (of it) is yours. (not the half)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nall ➜ Unit 75B, 90, 110D\nsome and any ➜ Unit 85\nno and none ➜ Unit 86  \nmuch/many/little/few ➜ Unit 87\nall of whom / most of which etc. ➜ Unit 96B\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n176\n</div>",
    exercises: [],
  },
  '89': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nneither do I / I don’t either ➜ Unit 51C\nany ➜ Units 85–86\nnone ➜ Units 86A, 88\nall ➜ Unit 88\nboth of whom / neither of which ➜ Unit 96B\nboth ➜ Unit 110D\nboth / both of  neither / neither of       \neither / either of\nWe use both/neither/either for two things.  \nYou can use these words with a noun (both books, neither book etc.).\nFor example, you are going out to eat.  There are two possible restaurants.  You say:\nBoth restaurants are good. (not the both restaurants)\nNeither restaurant is expensive.\nWe can go to either restaurant.  I don’t mind. (= one or the other, it doesn’t matter which)\nI haven’t been to either restaurant before. (= not one or the other)\nYou can also use both/neither/either without a noun: \n‘Which do you prefer, basketball or tennis?’ \n‘It’s hard to say.  I like both.’\n‘Is your friend British or American?’ \n‘Neither.  She’s Australian.’\n‘Do you want tea or coffee?’ \n‘Either.  I don’t mind.’\nboth of … / neither of … / either of …\nWe use both of / neither of / either of + the/these/my/Tom’s … etc.  So we say ‘both of the\nrestaurants’, ‘both of those restaurants’ etc. (but not both of restaurants):\nBoth of these restaurants are good.\nNeither of the restaurants we went to was expensive. \nI haven’t been to either of those restaurants.\nYou don’t need of after both.  So you can say:\nBoth of these restaurants are good.    or    Both these restaurants are good.\nWe also use both of / neither of / either of + us/you/them:\n(talking to two people)  Can either of you speak Russian?\n I asked two people how to get to the station, but neither of them knew.\nWe say ‘both of’ before us/you/them (you need to use of):\nBoth of us were tired. (not Both us were …)\nAfter neither of … a verb can be singular or plural:\nNeither of them is at home.    or    Neither of them are at home.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can say:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nboth … and …\nneither … nor …\neither … or …\nBoth Chris and Paul were late.\nI was both tired and hungry when I arrived home.\nNeither Chris nor Paul came to the party.\nThere was an accident outside our house, but we neither saw nor \nheard anything.\nI’m not sure where Maria’s from.  She’s either Spanish or Italian.\nEither you apologise, or I’ll never speak to you again.\nCompare either/neither/both (two things) and any/none/all (more than two):\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nThere are two good hotels here.  \nYou could stay at either of them.\nWe tried two hotels.\n   Neither of them had a room. \n   Both of them were full. \nThere are many good hotels here.\nYou could stay at any of them.\nWe tried a lot of hotels.\n   None of them had a room.\n   All of them were full.\n⎧\n⎨\n⎩\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n178\n</div>",
    exercises: [],
  },
  '90': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nall   every   whole \neverybody/everyone/everything and all \nWe say:\nEverybody was happy.     or     Everyone was happy. (not all were happy)\nHe thinks he knows everything. (not knows all)\nOur holiday was a disaster.  Everything went wrong. (not all went wrong)\nWe do not often use all alone in this way.  We do not say ‘all were happy’, ‘he knows all’ etc.\nWe use all in the following ways:  \nall + noun (all cars, all my money etc.) \nall of + us/you/them\nwe/you/they … all … (see also Unit 110D)\nall about …\nall … = the only thing(s)\nAll my friends were happy.\nAll of us were happy.\nWe were all happy.\nHe knows all about computers.\nAll I’ve eaten today is a banana. \n(= the only thing I’ve eaten today)\nwhole and all\nWhole = complete, entire.  We use whole mostly with singular nouns:\nDid you read the whole book? (= all the book, not just a part of it)\nEmily has lived her whole life in the same town.\nI was so hungry, I ate a whole packet of biscuits. (= a complete packet)\nWe do not normally use whole with uncountable nouns (water, food, money etc.).  \nWe say:\nDid you spend all the money I gave you?   (not the whole money)\nI read all the information carefully. (not the whole information)\nWe use the/my/a etc. before whole.  Compare whole and all:\nI read the whole book.    but    I read all the information.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nevery day / all day / the whole day\nWe use every to say how often something happens (every day / every ten minutes etc.):\nWhen we were on holiday, we went to the beach every day. (not all days)\nThe bus service is excellent.  There’s a bus every ten minutes.\nWe don’t see each other very often – about every six months.\nAll day or the whole day = the complete day from beginning to end:\nWe spent all day on the beach.    or    We spent the whole day …\n Dan was very quiet.  He didn’t say a word all evening.    or    … the whole evening.\nNote that we say all day (not all the day), all week (not all the week) etc.\nCompare all the time and every time:\nThey never go out.  They are at home all the time. (= always, continuously)\nEvery time I see you, you look different. (= each time, on every occasion)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nEvery/everybody/everyone/everything are singular words, so we use a singular verb:\nEvery seat in the theatre was taken.\nEverybody has arrived. (not have arrived)\nBut we use they/them/their after everybody/everyone:\nEverybody said they enjoyed themselves. (= everybody enjoyed himself or herself)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nCountable and uncountable ➜ Units 69–70\nall / all of ➜ Unit 88\neach and every ➜ Unit 91 \nevery one ➜ Unit 91D\nall ➜ Unit 110C\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n180\n</div>",
    exercises: [],
  },
  '91': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\neach and every\neach other ➜ Unit 82C\nall and every ➜ Unit 90\nEach and every are similar.  Oft en it is possible to use each or every:\nEach time I see you, you look diff erent.    or    Every time I see you …\nBut each and every are not exactly the same.\nWe use each when we think of things\nseparately, one by one.\nStudy each sentence carefully. \n(= study the sentences one by one)\neach = \nEach is more usual for a small number:\nThere were four books on the table.\nEach book was a diff erent colour.\n(in a card game) At the beginning of the\ngame, each player has three cards.\nWe use every when we think of things as a\ngroup.  The meaning is similar to all.\nEvery window in the house was open.\n(= all the windows in the house)\nevery =  \nEvery is more usual for a large number:\nKate loves reading.  She has read every\n \nbook in the library. (= all the books)\nI’d like to visit every country in\nthe world. (= all the countries)\nEach (but not every) can be used for two things:\nIn football, each team has eleven players. (not every team)\nWe use every (not each) to say how oft en something happens:\n‘How oft en do you use your car?’ \n‘Every day.’ (not Each day)\nThere’s a bus every ten minutes. (not each ten minutes)\nWe use each with or without a noun:\nNone of the rooms are the same.\nEach room is diff erent.    or\nEach is diff erent.\nOr you can use each one:\nEach one is diff erent.\nWe say each of (the/these/them … etc.):\nEach of the books was a diff erent \ncolour. (not each of books)\nEach of them was a diff erent colour.\nRead each of these sentences carefully.\nWe use every with a noun:\nShe’s read every book in the library.\nWe don’t use every alone, but you can say\nevery one:\na: Have you read all these books?\nB: Yes, every one.\nWe say every one of … (but not every of):\nI’ve read every one of those books.\n \n(not every of those books)\nI’ve read every one of them.\nCompare the structures we use with each and every.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe also use each in the middle of a sentence.  For example:\nThe students were each given a book. (= Each student was given a book.)\nWe say a dollar each, ten pounds each etc. :\nThese oranges are 40 pence each. (each = for one orange)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\neveryone and every one\nEveryone (one word) is only for people (= everybody).\nEveryone enjoyed the party. (= Everybody …)\nEvery one (two words) is for things or people:\nSarah is invited to lots of parties and she goes to every one. (= to every party)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n182\n</div>",
    exercises: [],
  },
  '92': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nRelative clauses 1: clauses with who/that/which\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nLast week we had a party and a lot of people came.  Everybody enjoyed it.\n \nEverybody  who came to the party   enjoyed it.\nA clause is a part of a sentence.  A relative clause tells us which person or thing (or what kind of\nperson or thing) the speaker means:\nthe woman who lives next door to me  \n(‘who lives next door to me’ tells us which woman)\npeople who complain all the time\n(‘who complain all the time’  tells us what kind of people)\nWe use who in a relative clause for people (not things):\nThe woman who lives next door to me is a doctor.\nI don’t like people who complain all the time.\nAn architect is someone who designs buildings.\nWhat was the name of the person who called?\nDo you know anyone who wants to buy a car?\nWe also use that for people, but not which:\nThe woman that lives next door to me is a doctor. (not the woman which)\nSometimes you must use who (not that) for people – see Unit 95.\nrelative clause\nWhen we are talking about things, we use that or which (not who) in a relative clause:\nI don’t like stories that have unhappy endings. \nor    … stories which have unhappy endings. \nGrace works for a company that makes furniture. \nor    … a company which makes furniture.\nThe machine that broke down is working again now. \nor    The machine which broke down …\nIn these examples that is more usual than which, but sometimes you must use which.  See Unit 95.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nIn relative clauses we use who/that/which, not he/she/they/it. \nCompare:\nI met a Canadian woman at the party.  She is an English teacher. (2 sentences) \nI met a Canadian woman who is an English teacher. (1 sentence)\nI can’t find the keys.  They were on the table.  \nWhere are the keys that were on the table? (not the keys they were)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWhat = the thing(s) that\nCompare what and that:\nWhat happened was my fault. (= the thing that happened)\nbut\nEverything that happened was my fault.  \n(not Everything what happened)\nThe machine that broke down is now working again. \n(not The machine what broke down)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nRelative clauses 2–5 ➜ Units 93–96\n184\n</div>",
    exercises: [],
  },
  '93': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nRelative clauses 2: \nclauses with and without who/that/which\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nLook at these example sentences from Unit 92:\nThe woman  who  lives next door to me is a doctor. (or The woman that lives …)\nThe woman  lives next  door to me \nwho (= the woman) is the subject\nWhere are the keys  that  were on the table? (or … the keys which were …)\nThe keys  were on the table \nthat (= the keys) is the subject\nYou must use who/that/which when it is the subject of the relative clause.  You cannot leave out\nwho/that/which in these examples.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nwho (= the woman) is the object\nI is the subject\nthat (= the keys) is the object\nyou is the subject\nSometimes who/that/which is the object of the verb.  For example:\n The woman  who  I wanted to see was away on holiday. \nI wanted to see  the woman\nDid you find the keys  that  you lost? \nyou lost  the keys\nWhen who/that/which is the object, you can leave it out.  So you can say:\nThe woman I wanted to see was away.    or    The woman who I wanted to see …\nDid you find the keys you lost?    or    … the keys that you lost?\nThe dress Lisa bought doesn’t fit her very well.    or    The dress that Lisa bought …\nIs there anything I can do?    or    … anything that I can do?\nNote that we say:\nthe keys you lost   (not the keys you lost them)\nthe dress Lisa bought   (not the dress Lisa bought it)\nNote the position of prepositions (to/in/for etc.) in relative clauses:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nTom is  talking to  a woman.  Do you know her? (2 sentences)\nDo you know the woman Tom is  talking to ? (or … the woman who/that Tom is talking to)\nI  slept in  a bed.  It wasn’t comfortable. (2 sentences)\nThe bed I  slept in  wasn’t comfortable. (or  The bed that/which I slept in …)\nAre these the books you were looking for?    or    \nAre these the books that/which you were …\nThe man I was sitting next to on the plane talked all the time.    or\nThe man who/that I was sitting next to …\nNote that we say:\nthe books you were looking for   (not the books you were looking for them)\nthe man I was sitting next to   (not the man I was sitting next to him)\nWe say:\nEverything (that) they said was true. (not Everything what they said)\nI gave her all the money (that) I had. (not all the money what I had)\nWhat = the thing(s) that:\nWhat they said was true. (= The things that they said)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nRelative clauses 1 ➜ Unit 92\nRelative clauses 3–5 ➜ Units 94–96\nwhom ➜ Unit 94B\n186\n</div>",
    exercises: [],
  },
  '94': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nRelative clauses 3: whose/whom/where\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nwhose\nStudy this example situation:\nWhen we were driving home, we saw some people standing by the \nroad.  Their car had broken down, so we stopped to help them.\nWe helped some people whose car had broken down. \n(= their car had broken down)\nWe use whose mostly for people:\nA widow is a woman whose husband is dead. \n \n(her husband is dead)\nI met someone whose brother I went to school with. \n(I went to school with his/her brother)\nCompare who and whose:\nI met a man who knows you. (he knows you)\nI met a man whose sister knows you. (his sister knows you)\nDo not confuse whose and who’s.  The pronunciation is the same, but who’s = who is or who has:\nI have a friend who’s learning Arabic. (who’s = who is)\nI have a friend who’s just started learning Arabic. (who’s = who has)\nI have a friend whose sister is learning Arabic. \nwhom\nWhom is possible instead of who when it is the object of the verb (see Unit 93B):\nGeorge is a person whom I admire very much. (I admire him)\nYou can also use a preposition + whom (to whom / from whom / with whom etc.):\nIt’s important to have friends with whom you can relax. (you can relax with them)\nWhom is a formal word and we do not oft en use it in spoken English.  We usually prefer to say:\na person I admire a lot    or    a person who/that I admire a lot\nfriends you can relax with    or    friends who/that you can relax with \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nwhere\nWe use where in a relative clause to talk about a place:\nI recently went back to the town where I grew up. (I grew up there)\nThe restaurant where we had lunch was near the airport.\nI would like to live in a place where there is plenty of sunshine.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nthe day, the time, the reason … \nWe say ‘the day we got married’, ‘the year I was born’, ‘the last time they met’ etc. :\nI can’t meet you on Friday.  That’s the day I’m going away.\n The last time I saw her, she looked great.\nYou can also use that:\nThe last time that I saw her, she looked great.\nWe say ‘the reason I’m calling you’, ‘the reason she didn’t get the job’ etc.\n The reason I’m calling you is to ask your advice.\nYou can also use that:\nThe reason that I’m calling you …    or    The reason why I’m calling you …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nRelative clauses 1–2 ➜ Units 92–93\nRelative clauses 4–5 ➜ Units 95–96\nwhom ➜ Unit 96\n188\n</div>",
    exercises: [],
  },
  '95': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nRelative clauses 4: extra information clauses (1)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nThere are two types of relative clause.  In these examples, the relative clauses are underlined.\nCompare:\nType 1\nThe woman who lives next door to me  \nis a doctor.\nGrace works for a company that makes \nfurniture.\nWe stayed at the hotel (that) you\nrecommended.\nIn these examples, the relative clauses tell you\nwhich person or thing (or what kind of person  \nor thing) the speaker means:\n‘The woman who lives next door to me’ \ntells us which woman.\n‘A company that makes furniture’ tells us\nwhat kind of company.\n‘The hotel (that) you recommended’ tells\nus which hotel.\nWe do not use commas (,) with these clauses:\nWe know a lot of people who live in \nLondon.\nType 2\nMy brother Ben, who lives in Hong  \nKong, is an architect.\nAnna told me about her new job, which\nshe’s enjoying a lot.\nWe stayed at the Park Hotel, which a\nfriend of ours recommended.\nIn these examples, the relative clauses do not\ntell you which person or thing the speaker\nmeans.  We already know which thing or\nperson is meant: ‘My brother Ben’, ‘Anna’s new  \njob’ and ‘the Park Hotel’.\nThe relative clauses in these sentences give us\nextra information about the person or thing.\nWe use commas (,) with these clauses:\nMy brother Ben, who lives in Hong  \nKong, is an architect.\nType 1\nYou can use that:\nDo you know anyone who/that speaks\nFrench and Italian?\nGrace works for a company which/that  \nmakes furniture.\nYou can leave out who/which/that when it is\nthe object (see Unit 93):\nWe stayed at the hotel (that/which) \nyou recommended.\nThis morning I met somebody (who/that) \nI hadn’t seen for ages.\nWe do not often use whom in this type of\nclause (see Unit 94B).\nType 2\nYou cannot use that:\nJohn, who speaks French and Italian,  \nworks as a tour guide.  (not that speaks)\nAnna told me about her new job, which\nshe’s enjoying a lot. \nYou cannot leave out who or which:\nWe stayed at the Park Hotel, which\na friend of ours recommended.\nThis morning I met Chris, who I hadn’t\nseen for ages.\nYou can use whom for people (when it is the  \nobject):\nThis morning I met Chris, whom I hadn’t  \nseen for ages.\nWe helped some people whose car had\nbroken down.\nWhat’s the name of the place where  \nyou went on holiday?\nLisa, whose car had broken down, was \nin a very bad mood.\nKate has just been to Sweden, where  \nher daughter lives.\nIn both types of relative clause we use who for people and which for things.  But:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nIn both types of relative clause you can use whose and where:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nRelative clauses (Type 1) ➜ Units 92–94\nRelative clauses (Type 2) ➜ Unit 96\n190\n</div>",
    exercises: [],
  },
  '96': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nRelative clauses 5: extra information clauses (2)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\npreposition + whom/which\nYou can use a preposition + whom (for people) and which (for things).  \nSo you can say:\nto whom \n \nwith whom \nabout whom \netc.\nof which \nwithout which \nfrom which \netc.\nMr Lee, to whom I spoke at the meeting, is interested in our proposal.\nFortunately we had a good map, without which we would have got lost.\nIn spoken English we often keep the preposition after the verb in the relative clause:\nKatherine told me she works for a company called ‘Latoma’, which I’d never  \nheard of before.\nWe do not use whom when the preposition is in this position:\nMr Lee, who I spoke to at the meeting, is interested in our proposal. \n(not Mr Lee, whom I spoke to …)\nFor prepositions in relative clauses, see also Unit 93C.\nall of / most of etc. + whom/which\nYou can say:\nHelen has three brothers, all of whom are married.\nThey asked me a lot of questions, most of which I couldn’t answer.\nIn the same way you can say:\nmany of whom \nsome of whom \nneither of whom \netc. \n(for people)\nnone of which \nboth of which \none of which \netc. \n(for things)\nMartin tried on three jackets, none of which fitted him.\nTwo men, neither of whom I had seen before, came into the office.\nThey have three cars, two of which they rarely use.\nSue has a lot of friends, many of whom she was at school with.\nYou can also say:\nthe cause of which\nthe name of which etc.\nThe house was damaged in a fire, the cause of which was never established.\nWe stayed at a beautiful hotel, the name of which I don’t remember now.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nwhich (not what)\nStudy this example: \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nrelative clause\n Joe got the job  .     This     surprised everybody. \n(2 sentences)\n Joe got the job  ,  which   surprised everybody. \n(1 sentence)\nIn this example, which = ‘the fact that Joe got the job’.  We use which (not what) in sentences\nlike these:\nSarah couldn’t meet us, which was a shame. (not what was a shame)\nThe weather was good, which we hadn’t expected. (not what we hadn’t expected)\nFor what and that, see Units 92D and 93D.\nall of / most of etc. ➜ Unit 88\nboth of etc. ➜ Unit 89\nRelative clauses 1–4 ➜ Units 92–95\n192\n</div>",
    exercises: [],
  },
  '97': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n-ing and -ed clauses (the woman talking to Tom,\nthe boy injured in the accident)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nA clause is a part of a sentence.  Some clauses begin with -ing.  For example:\nWho is the woman talking to Tom? \nThe boy injured in the accident was taken to hospital.\n-ing clause\nTOM\nthe woman \ntalking to Tom\n-ed clause\nWe use -ing clauses to say what somebody (or something) is (or was) doing at a particular time:\nWho is the woman talking to Tom? (the woman is talking to Tom)\nPolice investigating the crime are looking for three men. (police are investigating the crime)\nWho were those people waiting outside? (they were waiting)\nI was woken up by a bell ringing. (a bell was ringing)\nYou can also use an -ing clause to say what happens all the time, not just at a particular time:\nThe road connecting the two villages is very narrow. (the road connects the two villages)\nI have a large room overlooking the garden. (the room overlooks the garden)\nCan you think of the name of a flower beginning with T? (the name begins with T)\n-ed clauses have a passive meaning:\nThe boy injured in the accident was taken to hospital.\n(he was injured in the accident)\nGeorge showed me some pictures painted by his father.\n(they were painted by his father)\nThe gun used in the robbery has been found.\n(the gun was used in the robbery)\nInjured/painted/used are past participles.  Most past participles end in -ed, but many are irregular \n(stolen/made/built etc.):\nThe police never found the money stolen in the robbery.\nMost of the goods made in this factory are exported.\nSome clauses begin with -ed (injured, painted etc.).  For example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use there is / there was (etc.) + -ing and -ed clauses:\nThere were some children swimming in the river.\nIs there anybody waiting?\nThere was a big red car parked outside the house.\nWe use left  in this way, with the meaning ‘not used, still there’:\nWe’ve eaten nearly all the chocolates.  There are only a few left .\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nsee/hear somebody doing something ➜ Unit 67\n-ing clauses ➜ Unit 68\nthere (is) ➜ Unit 84\nIrregular past participles (made/stolen etc.) ➜ Appendix 1\nthe boy injured \nin the accident\n194\n</div>",
    exercises: [],
  },
  '98': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nAdjectives ending in -ing and -ed  (boring/bored etc.)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nMany adjectives end in -ing and -ed, for example: boring and bored.\nStudy this example situation:\nJane has been doing the same job for \na very long time.  Every day she does \nexactly the same thing again and again.  \nShe doesn’t enjoy her job any more and \nwould like to do something diff erent.\nJane’s job is boring.\nJane is bored with her job.\nSomebody is bored or gets bored if something (or somebody else) is boring. \nIf something is boring, you get bored with it.\nSo:\nJane is bored because her job is boring.\nJane’s job is boring, so Jane is bored. (not Jane is boring)\nIf a person is boring, this means that they make other people bored:\n Paul always talks about the same things.  He’s really boring.\nCompare adjectives ending in -ing and -ed:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nboring\ninteresting\nMy job is \ntiring\nsatisfying\ndepressing   (etc.)\nIn these examples, the -ing adjective tells you \nabout the job\nI’m bored with my job.\nI’m not interested in my job any more.\nI get very tired doing my job.\nI’m not satisfied with my job.\nMy job makes me depressed.   (etc.)\nIn these examples, the -ed adjective tells you\nhow somebody feels (about the job).\n⎫⎪⎪⎬⎪⎪⎭\ninteresting\nJulia thinks politics is interesting.\nDid you meet anyone interesting at\nthe party?\nsurprising\nIt was surprising that he passed the\nexam.\ndisappointing\nThe movie was disappointing.\nWe expected it to be better.\nshocking\nThe news was shocking.\ninterested\nJulia is interested in politics.\n(not interesting in politics)\nAre you interested in buying a car?\nI’m trying to sell mine.\nsurprised\nEverybody was surprised that he passed\nthe exam.\ndisappointed\nWe were disappointed with the movie.\nWe expected it to be better.\nshocked\nI was shocked when I heard the news.\nCompare these examples:\nbored\nboring\n196\n</div>",
    exercises: [],
  },
  '99': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nAdjectives: a nice new house, you look tired\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSometimes we use two or more adjectives together:\nMy brother lives in a nice new house.\nIn the kitchen there was a beautiful large round wooden table.\nAdjectives like new/large/round/wooden are fact adjectives.  They give us information about \nage, size, colour etc.\nAdjectives like nice/beautiful are opinion adjectives.  They tell us what the speaker thinks of\nsomething or somebody.\nOpinion adjectives usually go before fact adjectives.\na\nan\na\nopinion\nnice\ninteresting\ndelicious\nbeautiful\nfact\nlong\nyoung\nhot\nlarge round wooden\nsummer holiday\nman\nvegetable soup\ntable\nSometimes we use two or more fact adjectives together.  Usually (not always) we put fact adjectives\nin this order:\n1\nhow big?\n2\nhow old?\n3\nwhat\ncolour?\n4\nwhere\nfrom?\n5\nwhat is it\nmade of?\nNOUN\na tall young man (1 → 2) \na large wooden table (1 → 5)\nbig blue eyes (1 → 3) \nan old Russian song (2 → 4)\na small black plastic bag (1 → 3 → 5) \nan old white cotton shirt (2 → 3 → 5)\nAdjectives of size and length (big/small/tall/short/long etc.) usually go before adjectives of shape\nand width (round/fat/thin/slim/wide etc.):\na large round table \n \na tall thin girl \n \na long narrow street\nWhen there are two or more colour adjectives, we use and:\na black and white dress \n \na red, white and green flag\nThis does not usually happen with other adjectives before a noun:\na long black dress   (not a long and black dress)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use adjectives after be/get/become/seem:\nBe careful!\nI’m tired and I’m getting hungry.\nAs the film went on, it became more and more boring.\nYour friend seems very nice.\nWe also use adjectives to say how somebody/something looks, feels, sounds, tastes or smells:\nYou look tired. / I feel tired. / She sounds tired.\nThe dinner smells good.\nThis tea tastes a bit strange.\nBut to say how somebody does something you must use an adverb (see Units 100–101):\nDrive carefully! (not Drive careful)\nSuzanne plays the piano very well. (not plays … very good)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe say ‘the first two days’, ‘the next few weeks’, ‘the last ten minutes’ etc. :\nI didn’t enjoy the first two days of the course. (not the two first days)\nThey’ll be away for the next few weeks. (not the few next weeks)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nAdverbs ➜ Units 100–101\nComparative (cheaper etc.) ➜ Units 105–107\nSuperlative (cheapest etc.) ➜ Unit 108\n198\n</div>",
    exercises: [],
  },
  '100': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nAdjectives and adverbs 1 (quick/quickly)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nYou can say:\nOur holiday was too short – the time passed very quickly.\nTwo people were seriously injured in the accident.\nQuickly and seriously are adverbs.  Many adverbs are adjective + -ly:\nadjective \nquick \nserious \ncareful \nbad \nheavy \nterrible\nadverb \nquickly \nseriously \ncarefully \nbadly \nheavily \nterribly\nFor spelling, see Appendix 6.\nNot all words ending in -ly are adverbs.  Some adjectives end in -ly too, for example:\nfriendly \n \nlively \n \nelderly \n \nlonely \n \nlovely\nIt was a lovely day.\nAdjective or adverb?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nCompare:\nWe use adjectives after some verbs, especially be, and also look/feel/sound etc.\nCompare:\nShe speaks perfect English.\nadjective  +  noun\nShe speaks English perfectly.\n  verb  +  noun  +   adverb\nAdjectives (quick/careful etc.) tell us about a \nnoun (somebody or something).  We use \nadjectives before nouns:\nSam is a careful driver. \n(not a carefully driver)\nWe didn’t go out because of the heavy \nrain.\nAdverbs (quickly/carefully etc.) tell us about\na verb (how somebody does something or \nhow something happens):\nSam drove carefully along the narrow\nroad. (not drove careful)\nWe didn’t go out because it was raining\nheavily. (not raining heavy)\nPlease be quiet.\nMy exam results were really bad.\nWhy do you always look so serious?\nI feel happy.\nPlease speak quietly.\nI did really badly in the exam. \nWhy do you never take me seriously?\nThe children were playing happily.\nYou can also use adverbs before adjectives and other adverbs.  For example:\nreasonably cheap \n(adverb + adjective)\nterribly sorry \n(adverb + adjective)\nincredibly quickly \n(adverb + adverb)\nIt’s a reasonably cheap restaurant and the food is extremely good.\nI’m terribly sorry.  I didn’t mean to push you. \nMaria learns languages incredibly quickly.\nThe exam was surprisingly easy.\nYou can also use an adverb before a past participle (injured/organised/written etc.):\nTwo people were seriously injured in the accident. (not serious injured)\nThe conference was badly organised.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nC\nAdjectives after be/look/feel etc. ➜ Unit 99C\nAdjectives and adverbs 2 ➜ Unit 101\n200\n</div>",
    exercises: [],
  },
  '101': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAdjectives and adverbs 2\n(well, fast, late, hard/hardly)\ngood and well\nGood is an adjective.  The adverb is well:\nYour English is good. \nbut    You speak English well.\nSophie is a good pianist.    but    Sophie plays the piano well.\nWe use well (not good) with past participles (known/educated etc.).  For example:\nwell-known \n \nwell-educated \n \nwell-paid \n \nwell-behaved\nSophie’s father is a well-known writer.\nWell is also an adjective meaning ‘in good health’:\n‘How are you today?’ \n‘I’m very well, thanks.’\nAdjectives aft er verbs (‘You look tired’ etc.) ➜ Unit 99C\nAdjectives and adverbs 1 ➜ Unit 100\nfast, hard and late\nThese words are both adjectives and adverbs:\n \nadjective\nadverb\nDarren is a fast runner.  \nDarren can run fast.\nIt’s hard to find a job right now.  \nKate works hard. (not works hardly)\nSorry I’m late.  \nI got up late.\nlately = recently:\nHave you seen Kate lately?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nhardly\nhardly = very little, almost not:\nSarah wasn’t very friendly at the party.  She hardly spoke to me.\n(= she spoke to me very little)\nWe’ve only met once or twice.  We hardly know each other.\nCompare hard and hardly:\nHe tried hard to find a job, but he had no luck.  (= he tried a lot, with a lot of eff ort)\nI’m not surprised he didn’t find a job.  He hardly tried.  (= he tried very little)\nHardly goes before the verb:\nWe hardly know each other. (not We know each other hardly)\nI can hardly do something = it’s very diff icult for me, almost impossible:\nYour writing is terrible.  I can hardly read it.  (= it is almost impossible to read it)\nMy leg was hurting.  I could hardly walk. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nYou can use hardly + any/anybody/anyone/anything/anywhere:\na: How much money do we have?\nB: Hardly any.  (= very little, almost none)\nThese two cameras are very similar.  There’s hardly any\ndiff erence between them.\nThe exam results were bad.  Hardly anybody in our\nclass passed.  (= very few students passed)\nShe was very quiet.  She said hardly anything.    or\nShe hardly said anything.\nhardly ever = almost never:\nI’m nearly always at home in the evenings.  I hardly ever go out.\nHardly also means ‘certainly not’.  For example:\nIt’s hardly surprising that you’re tired.  You haven’t slept for three days.\n(= it’s certainly not surprising)\nThe situation is serious, but it’s hardly a crisis.  (= it’s certainly not a crisis)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nThere’s hardly anything \nin the fridge.\n202\n</div>",
    exercises: [],
  },
  '102': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nnot so … as ➜ Unit 107A\nsuch as  ➜ Unit 117A\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nso and such\nCompare so and such:\nWe use so + adjective/adverb:\nso stupid \nso quick\nso nice  \nso quickly\nI didn’t like the book.  The story was so\n \nstupid.\nEverything happened so quickly.\nWe use such + noun:\nsuch a story\nsuch people\nWe also use such + adjective + noun:\n \nsuch a stupid story\nsuch nice people\nI didn’t like the book.  It was such a\n \nstupid story. (not a so stupid story)\nI like Liz and Joe.  They are such nice\n \npeople. (not so nice people)\nWe say such a … (not a such):\nsuch a big dog\nI’ve had a busy day.  I’m so tired.\n(= really tired)\nIt’s difficult to understand him.  He talks\nso quietly.\nYou can use so … that:\nI was so tired that I fell asleep in the \narmchair.\nWe usually leave out that:\nI was so tired I fell asleep.\nWe had a great trip.  We had such a good\n \ntime. (= a really good time)\nYou always think good things are going  \nto happen.  You’re such an optimist.\nYou can use such … that:\nIt was such nice weather that we spent\nthe whole day on the beach.\nWe usually leave out that:\nIt was such nice weather we spent …\nSomebody told me the house was built\n100 years ago.  I didn’t realise it was\nso old.  (= as old as it is)\nI’m tired because I got up at six.\nI don’t usually get up so early.\nI expected the weather to be cooler.\nI’m surprised it is so warm.\nI didn’t realise it was such an old house.\nYou know it’s not true.  How can you\n \nsay such a thing? (= a thing like this)\nNote the expression no such … :\nYou won’t find the word ‘blid’ in the\ndictionary.  There’s no such word.\n(= this word does not exist)\nso long\nI haven’t seen her for so long I’ve\nforgotten what she looks like.\nso far\nI didn’t know it was so far.\nso much, so many\nI’m sorry I’m late – there was so much\n \ntraffic.\nsuch a long time\nI haven’t seen her for such a long time.\n \n(not so long time)\nsuch a long way\nI didn’t know it was such a long way.\nsuch a lot (of)\nI’m sorry I’m late – there was such a lot\nof traffic.\nSo and such make the meaning stronger:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nSo and such also mean ‘like this’:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n204\n</div>",
    exercises: [],
  },
  '103': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nto … and for … (purpose) ➜ Unit 64      Adjective + to … (diff icult to understand etc.) ➜ Unit 65\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nenough and too\nenough\nEnough goes aft er adjectives and adverbs:\nI can’t run very far.  I’m not fit enough. (not enough fit)\nLet’s go.  We’ve waited long enough.\nEnough normally goes before nouns:\nWe have enough money.  We don’t need any more. \nThere weren’t enough chairs.  Some of us had to sit on \nthe floor.\nWe also use enough alone (without a noun or adjective):\n We don’t need more money.  We have enough.\ntoo and enough\nCompare too … and not … enough:\nYou never stop working.  You work too hard.\n(= more than is necessary)\nYou’re lazy.  You don’t work hard enough.\n(= less than is necessary)\nCompare too much/many and enough:\nThere’s too much furniture in this room.  There’s not enough space.\nThere were too many people and not enough chairs.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nenough/too + for … and to …\nWe say enough/too … for somebody/something:\nDoes Joe have enough experience for the job?\nThis bag isn’t big enough for all my clothes.\nThat shirt is too small for you.  You need a larger size.\nWe say enough/too … to do something.  For example:\nDoes Joe have enough experience to do the job?\nLet’s get a taxi.  It’s too far to walk home from here.\nShe’s not old enough to have a driving licence. \nThe next example has both for … and to … :\nThe bridge is just wide enough for two cars to pass one another.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\ntoo hot to eat etc.\nWe say:\nThe food was very hot.  We couldn’t eat it.\nand\nThe food was so hot that we couldn’t eat it.\nbut\nThe food was too hot to eat. (not to eat it)\nIn the same way we say:\nThese boxes are too heavy to carry.  (not to carry them)\nThe wallet was too big to put in my pocket.  (not to put it)\nThis chair isn’t strong enough to stand on.  (not to stand on it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI’m not fit enough.\n to stand on it)\nThe wallet doesn’t \nfit in my pocket.\n206\n</div>",
    exercises: [],
  },
  '104': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nquite, pretty, rather and fairly\nQuite and pretty are similar in meaning (= less than ‘very’, but more than ‘a little’):\nI’m surprised you haven’t heard of her.  She’s quite famous.  or   She’s pretty famous.  \n(= less than ‘very famous’, but more than ‘a little famous’)\nAnna lives quite near me, so we see each other pretty often.\nPretty is an informal word and is used mainly in spoken English.\nQuite goes before a/an:\n We live in quite an old house. (not a quite old house)\nCompare:\nSarah has quite a good job.\nSarah has a pretty good job.\nYou can also use quite (but not pretty) in the following ways:\nquite a/an + noun (without an adjective):\n I didn’t expect to see them.  It was quite a surprise.  (= quite a big surprise)\nquite a lot (of …):\n There were quite a lot of guests at the wedding.\nquite + verb, especially like and enjoy:\nI quite like tennis, but it’s not my favourite sport.\nRather is similar to quite and pretty.  We often use rather for negative ideas (things we think are not \ngood):\nThe weather isn’t so good.  It’s rather cloudy.\n Paul is rather shy.  He doesn’t talk very much.\nQuite is also possible in these examples.\nWhen we use rather for positive ideas (good/nice etc.), it means ‘unusually’ or ‘surprisingly’:\nThese oranges are rather good.  Where did you get them?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nFairly is weaker than quite/rather/pretty.  For example, if something is fairly good, it is not very\ngood and it could be better:\nMy room is fairly big, but I’d prefer a bigger one.\nWe see each other fairly often, but not as often as we used to.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nQuite also means ‘completely’.  For example:\n‘Are you sure?’     ‘Yes, quite sure.’  (= completely sure)\nQuite means ‘completely’ with a number of adjectives, especially:\nsure \nright \ntrue \nclear \n different \n incredible \n amazing\ncertain \nwrong \nsafe \nobvious \n unnecessary \n extraordinary \n impossible\nShe was quite different from what I expected.  (= completely different)\nEverything they said was quite true.  (= completely true)\nWe also use quite (= completely) with some verbs.  For example:\nI quite agree with you.  (= I completely agree)\nnot quite = not completely:\nI don’t quite understand what you mean.\n‘Are you ready yet?’ \n‘Not quite.’  (= not completely)\nCompare the two meanings of quite:\nThe story is quite interesting.  (= less than ‘very interesting’)\nThe story is quite true.  (= completely true)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n208\n</div>",
    exercises: [],
  },
  '105': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nComparative 2–3 ➜ Units 106–107\nSuperlative (cheapest / most expensive etc.) ➜ Unit 108\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nComparative 1 (cheaper, more expensive etc.)\nLook at these examples:\nHow shall we travel?  Shall we drive or go by train?\nLet’s drive.  It’s cheaper.\nDon’t go by train.  It’s more expensive.\nCheaper and more expensive are comparative forms.\nAft er comparatives you can use than (see Unit 107):\nIt’s cheaper to drive than go by train.\nGoing by train is more expensive than driving.\nThe comparative form is -er or more …  .\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use -er for short words (one syllable):\ncheap → cheaper \n fast → faster\nlarge → larger  \n thin → thinner\nWe also use -er for two-syllable words that\nend in -y (-y → -ier):\nlucky → luckier  \nearly → earlier\neasy → easier  \npretty → prettier\nFor spelling, see Appendix 6.\nWe use more … for longer words (two\nsyllables or more):\nmore serious  \nmore expensive\nmore oft en  \nmore comfortable\nWe also use more … for adverbs that end\nin -ly:\nmore slowly \nmore seriously\nmore easily \nmore quietly\nYou’re older than me.\nThe exam was quite easy – easier than\nI expected.\nCan you walk a bit faster?\nI’d like to have a bigger car.\nLast night I went to bed earlier than\n \nusual.\nYou’re more patient than me.\nThe exam was quite diff icult – more\ndiff icult than I expected.\nCan you walk a bit more slowly?\nI’d like to have a more reliable car.\nI don’t play tennis much these days.\nI used to play more oft en.\nWe use both -er or more … with some two-syllable adjectives, especially:\nclever \n \nnarrow \n \nquiet \n \nshallow \n \nsimple\nIt’s too noisy here.  Can we go somewhere quieter?    or    … somewhere more quiet?\nA few adjectives and adverbs have irregular comparative forms:\ngood/well → better\nThe garden looks better since you tidied it up.\nI know him well – probably better than anybody else knows him.\nbad/badly → worse\n‘How’s your headache?  Better?’ \n‘No, it’s worse.’\nHe did very badly in the exam – worse than expected.\nfar → further (or farther)\nIt’s a long walk from here to the park – further than I thought.  (or farther than)\nNote that further (but not farther) also means ‘more’ or ‘additional’:\nLet me know if you hear any further news.  (= any more news)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCompare these examples:\n£36\n£52\n210\n</div>",
    exercises: [],
  },
  '106': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nany/no ➜ Unit 86\nComparative 1, 3 ➜ Units 105, 107\neldest ➜ Unit 108C \neven + comparative ➜ Unit 112C\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nComparative 2 (much better / any better etc.)\nmuch / a lot etc. + comparative\nBefore comparatives you can use:\nmuch \n \na lot \n \nfar (= a lot) \n \na bit \n \na little \n \nslightly (= a little)\nI felt ill earlier, but I feel much better now. (or a lot better)\nDon’t go by train.  It’s a lot more expensive. (or much more expensive)\nCould you speak a bit more slowly?   (or a little more slowly)\nThis bag is slightly heavier than the other one.\nThe problem is far more serious than we thought at first. \nany / no + comparative\nYou can use any and no + comparative (any longer / no bigger etc.):\nI’ve waited long enough. I’m not waiting any longer. (= not even a little longer)\nWe expected their apartment to be very big, but it’s no bigger than ours.  \nor    … it isn’t any bigger than ours. (= not even a little bigger)\nHow do you feel now?  Do you feel any better?\nThis hotel is better than the other one, and it’s no more expensive.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nbetter and better, more and more etc.\nWe repeat comparatives (better and better etc.) to say that something changes continuously:\nYour English is improving.  It’s getting better and better.\nThe city has grown fast in recent years.  It’s got bigger and bigger.\nAs I listened to his story, I became more and more convinced that he was lying.\nMore and more tourists are visiting this part of the country.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nthe … the …\nYou can say the sooner the better, the more the better etc. :\na: What time shall we leave?\nB: The sooner the better. (= as soon as possible)\na: What sort of bag do you want?  A big one?\nB: Yes, the bigger the better. (= as big as possible)\nWhen you’re travelling, the less luggage you have the better.\nWe also use the … the … to say that one thing depends on another thing:\nThe sooner we leave, the earlier we’ll arrive. (= if we leave sooner, we’ll arrive earlier)\nThe younger you are, the easier it is to learn.\nThe more expensive the hotel, the better the service.\nThe more I thought about the plan, the less I liked it.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nolder and elder\nThe comparative of old is older:\nDavid looks older than he really is. (not looks elder)\nWe use elder only when we talk about people in a family (my elder sister, their elder son etc.).  \nYou can also use older:\nMy elder sister is a TV producer. (or My older sister …)\nBut we do not say that ‘somebody is elder’:\nMy sister is older than me. (not elder than me)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n212\n</div>",
    exercises: [],
  },
  '107': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nComparative 1–2 ➜ Units 105–106\nas long as ➜ Unit 115B\nas and like ➜ Unit 117\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nComparative 3 (as … as / than)\nStudy this example situation:\nSome more examples of not as … (as):\nJack isn’t as old as he looks.  (= he looks older than he is)\nThe town centre wasn’t as crowded as usual.  (= it is usually more crowded)\nLisa didn’t do as well in the exam as she had hoped.  (= she had hoped to do better)\nThe weather is better today.  It’s not as cold.  (= yesterday was colder than today)\nI don’t know as many people as you do.  (= you know more people than me)\n‘How much was it?  Fift y dollars?’ \n‘No, not as much as that.’  (= less than fift y dollars)\nYou can also say not so … (as):\nIt’s not warm, but it’s not so cold as yesterday.  (= it’s not as cold as …)\nLess than is similar to not as … as:\nI spent less money than you.  (= I didn’t spend as much money as you)\nThe city centre was less crowded than usual.  (= it wasn’t as crowded as usual)\nI play tennis less than I used to.  (= I don’t play as much as I used to)\nSARAH\nJOE\nDAVID\nSarah, Joe and David are all very rich.\nSarah has $20 million, Joe has $15 million\nand David has $10 million.  So:\nJoe is rich.\nHe is richer than David.\nBut he isn’t as rich as Sarah.\n(= Sarah is richer than he is)\nWe also use as … as (but not so … as) in positive sentences and in questions:\nI’m sorry I’m late.  I got here as fast as I could.\nThere’s plenty of food.  You can have as much as you want.\nCan you send me the information as soon as possible, please?\nLet’s walk.  It’s just as quick as taking the bus. \nalso  twice as … as, three times as … as etc. :\nPetrol is twice as expensive as it was a few years ago.\nTheir house is about three times as big as ours.\n(or    … three times the size of ours)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say the same as (not the same like):\nLaura’s salary is the same as mine.    or    Laura gets the same salary as me.\nDavid is the same age as James.\nSarah hasn’t changed.  She still looks the same as she did ten years ago.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nthan me / than I am etc.\nYou can say:\nYou’re taller than me.  \nor You’re taller than I am.\n \n(not usually You’re taller than I)\nHe’s not as clever as her. \nor He’s not as clever as she is.\nThey have more money than us.    or    They have more money than we have.\nI can’t run as fast as him. \nor I can’t run as fast as he can.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n214\n</div>",
    exercises: [],
  },
  '108': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nSuperlative (the longest / the most enjoyable etc.)\nLook at these examples:\nThe superlative form is -est or most …  .  In general, we use -est for short words and most … for\nlonger words. \n long → longest  \nhot → hottest \neasy → easiest \nhard → hardest\nbut    most famous \nmost boring \nmost enjoyable  \nmost difficult\nA few superlative forms are irregular:\ngood → best \nbad → worst \nfar → furthest or farthest\nThe rules are the same as those for the comparative – see Unit 105.\nFor spelling, see Appendix 6.\nWhat is the longest river in the world?\nWhat was the most enjoyable holiday you’ve ever had?\nLongest and most enjoyable are superlative forms.\nWe normally use the (or my/your etc.) with a superlative:\nYesterday was the hottest day of the year.\nThe Louvre in Paris is one of the most famous museums in the world.\nShe is really nice – one of the nicest people I know.\nWhat’s the best movie you’ve ever seen, and what’s the worst?\nHow old is your youngest child?\nCompare the superlative and the comparative:\nThis hotel is the cheapest in town.  (superlative) \nIt’s cheaper than all the others in town.  (comparative)\nHe’s the most patient person I’ve ever met.\nHe’s much more patient than I am.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\noldest and eldest\nThe superlative of old is oldest:\nThat church is the oldest building in the town. (not the eldest)\nWe use eldest only when we talk about people in a family (you can also use oldest):\nTheir eldest son is 13 years old. (or Their oldest son)\nAre you the eldest in your family?   (or the oldest)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nAfter superlatives we normally use in with places:\nWhat’s the longest river in the world?   (not of the world)\nWe had a nice room.  It was one of the best in the hotel. (not of the hotel)\nWe also use in for organisations and groups of people (a class / a company etc.):\nWho is the youngest student in the class?   (not of the class)\nFor a period of time (day, year etc.), we normally use of:\nYesterday was the hottest day of the year.\nWhat was the happiest day of your life?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe often use the present perfect (I have done) after a superlative (see also Unit 8A):\nWhat’s the most important decision you’ve ever made?\nThat was the best holiday I’ve had for a long time.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nComparative (cheaper / more expensive etc.) ➜ Units 105–107\nelder ➜ Unit 106E\n216\n</div>",
    exercises: [],
  },
  '109': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWord order 1: verb + object; place and time\nVerb + object\nThe verb and the object normally go together.  We do not usually put other words between them:\nI\nOur guide \nI didn’t\nDo you\nverb\nlike\nspoke\nuse\neat\nobject\nmy job \nEnglish \nmy phone\nmeat\nvery much. (not I like very much)\nfluently.    (not spoke fluently English)\nyesterday.\nevery day?\nTwo more examples:\nI lost all my money and I also lost my passport.    \n(not I lost also my passport)\nAt the end of this street you’ll see a supermarket on your left.\n \n(not see on your left a supermarket)\nPlace\nThe verb and place (where?) normally go together:\ngo home \n \nlive in a city \nwalk to work etc.\nIf the verb has an object, the order is:\nWe\nDon’t\nDid you \nverb\ntook\nput\nlearn\nobject\nthe children\nanything\nEnglish\nplace\nto the zoo. (not took to the zoo the children)\non the table.\nat school?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nTime\nNormally time (when? / how often? / how long?) goes after place:\nBen walks \nI’m going \nThey’ve lived\nWe need to be\nSarah gave me a lift \nYou really shouldn’t go\nplace\nto work\nto Paris\nin the same house\nat the airport\nhome\nto bed\ntime\nevery morning. (not every morning to work)\non Monday.\nfor a long time.\nby 8 o’clock.\nafter the party.\nso late.\nSometimes we put time at the beginning of the sentence:\nOn Monday I’m going to Paris.\nAfter the party Sarah gave me a lift home.\nSome time words (for example, always/never/usually) go with the verb in the middle of \nthe sentence.  See Unit 110.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWord order in questions ➜ Units 49–50\nAdjective order ➜ Unit 99\nWord order 2 ➜ Unit 110\n218\n</div>",
    exercises: [],
  },
  '110': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nWord order 1 ➜ Unit 109\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWord order 2: adverbs with the verb\nSome adverbs (for example, always, also, probably) go with the verb in the middle of a sentence:\nEmily always drives to work.\nWe were feeling very tired and we were also hungry.\nThe meeting will probably be cancelled.\nIf the verb is one word (drives/cooked etc.), the adverb goes before the verb:\nEmily\nI\nadverb\nalways\nalmost\nverb\ndrives\nfell\nto work.\nas I was going down the stairs.\nI cleaned the house and also cooked the dinner. (not cooked also)\nLaura hardly ever watches television and rarely reads newspapers.\n‘Shall I give you my address?’ \n‘No, I already have it.’\nNote that these adverbs (always/usually/also etc.) go before have to … :\nJoe never phones me.  I always have to phone him. (not I have always to phone)\nBut adverbs go after am/is/are/was/were:\nWe were feeling very tired and we were also hungry. (not also were)\nYou’re always late.  You’re never on time.\nThe traffic isn’t usually as bad as it was this morning.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nIf the verb is two or more words (for example, can remember / will be cancelled), the adverb \nusually goes after the first verb (can/doesn’t/will etc.):\nI\nClare\nThe meeting\nverb 1\ncan\ndoesn’t\nAre you\nwill\nadverb\nnever\nusually\ndefinitely\nprobably\nverb 2\nremember\ndrive\ngoing\nbe\nher name.\nto work.\naway next week?\ncancelled.\nYou’ve always been very kind to me.\nJack can’t cook.  He can’t even boil an egg.\nDo you still work for the same company?\nThe house was only built a year ago and it’s already falling down.\nNote that probably goes before a negative (isn’t/won’t etc.).  So we say:\nI probably won’t see you.    or \nI’ll probably not see you. (but not I won’t probably)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe also use all and both with the verb in the middle of a sentence:\nWe all felt ill after the meal. (not felt all ill)\nMy parents are both teachers. \nSarah and Jane have both applied for the job.\nMy friends are all going out tonight.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nSometimes we use is/will/did etc. instead of repeating part of a sentence (see Unit 51):\nTom says he isn’t clever, but I think he is.  (= he is clever)\nWhen we do this, we put always/never etc. before the verb:\nHe always says he won’t be late, but he always is.  (= he is always late)\nI’ve never done it and I never will.  (= I will never do it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n220\n</div>",
    exercises: [],
  },
  '111': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nstill \nany more \nyet \nalready\nWe use still to say that a situation or action is continuing.  It hasn’t changed or stopped:\nIt’s ten o’clock and Joe is still in bed.\nWhen I went to bed, Chris was still working.\nDo you still want to go away or have you changed your mind?\nStill also means ‘in spite of this’.  For example:\nHe has everything he needs, but he’s still unhappy.\nStill usually goes in the middle of the sentence with the verb.  See Unit 110.\nWe use not … any more or not … any longer to say that a situation has changed. \nAny more and any longer go at the end of a sentence:\nLucy doesn’t work here any more.  She left last month.    or \nLucy doesn’t work here any longer.\n We used to be good friends, but we aren’t any more.    or    … we aren’t any longer.\nYou can write any more (2 words) or anymore (1 word).\nYou can also use no longer.  No longer goes in the middle of the sentence:\n Lucy no longer works here.\nWe do not normally use no more in this way:\nWe are no longer friends. (not we are no more friends)\nCompare still and not … any more:\nSally still works here, but Lucy doesn’t work here any more.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe use already to say that something happened sooner than expected. \n‘What time is Sue leaving?’ \n‘She has already left.’ (= sooner than you expected)\nShall I tell Joe what happened or does he already know?\nI’ve just had lunch and I’m already hungry.\nAlready usually goes in the middle of a sentence (see Unit 110) or at the end:\nShe’s already left.   or   She’s left already.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe use yet mainly in negative sentences (He isn’t here yet) and questions (Is he here yet?). \nYet (= until now) shows that the speaker expects something to happen.\nYet usually goes at the end of a sentence:\nIt’s 10 o’clock and Joe isn’t here yet.\nHave you decided what to do yet?\n‘Where are you going on holiday?’ \n‘We don’t know yet.’\nWe often use yet with the present perfect (‘Have you decided … yet?’).  See Unit 7C.\nCompare yet and still:\nMike lost his job six months ago and is still unemployed.\nMike lost his job six months ago and hasn’t found another job yet.\nIs it still raining?\n \nHas it stopped raining yet?\nStill is also possible in negative sentences (before the negative):\n She said she would be here an hour ago and she still hasn’t come.\nThis is similar to ‘she hasn’t come yet’.  But still … not shows a stronger feeling of surprise or\nimpatience.  Compare:\nI sent him an invitation last week.  He hasn’t replied yet. (but I expect he will reply soon)\nI sent him an invitation weeks ago and he still hasn’t replied. (he should have replied  \nbefore now)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nPresent perfect + already/yet ➜ Unit 7C\nWord order ➜ Unit 110\n222\n</div>",
    exercises: [],
  },
  '112': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nif and when ➜ Unit 25D\nthough / even though ➜ Unit 113E\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nStudy this example situation:\nSome more examples:\nThese pictures are really awful.  Even I take better pictures than these.\n(and I’m certainly not a good photographer)\nHe always wears a coat, even in hot weather.\nThe print was very small.  I couldn’t read it, even with glasses. \nNobody would help her, not even her best friend.    or\nNot even her best friend would help her.\neven\nTina loves watching TV.\nShe has a television in every room of the house,\neven the bathroom.\nWe use even to say that something is unusual\nor surprising.  It is not usual to have a television\nin the bathroom.\nYou can use even with the verb in the middle of a sentence (see Unit 110):\nLaura has travelled all over the world.  She’s even been to the Antarctic.\nThey are very rich.  They even have their own private jet.\nYou can use even with a negative (not even, can’t even, don’t even etc.):\nI can’t cook.  I can’t even boil an egg. (and boiling an egg is very easy)\nThey weren’t very friendly to us.  They didn’t even say hello.\nJessica is very fit.  She’s been running quite fast and she’s not even out of breath.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use even + comparative (cheaper / more expensive etc.):\nI got up very early, but Jack got up even earlier.\nI knew I didn’t have much money, but I have even less than I thought.\nWe were very surprised to get an email from her.  We were even more surprised when she \ncame to see us a few days later.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\neven though / even when / even if\nWe use even though / even when / even if + subject + verb:\nEven though Tina can’t drive, she has a car.\nsubject + verb\nHe never shouts, even when he’s angry.\nThis river is dangerous.  It’s dangerous to swim in it, even if you’re a strong swimmer.\nWe do not use even + subject + verb.  We say:\nEven though she can’t drive, she has a car. (not even she can’t drive)\nI can’t reach the shelf even if I stand on a chair. (not even I stand)\nCompare even if and even (without if):\nIt’s dangerous to swim here even if you’re a strong swimmer. (not even you are)\nThe river is dangerous, even for strong swimmers.\nCompare even if and if:\nWe’re going to the beach tomorrow.  It doesn’t matter what the weather is like.\nWe’re going even if the weather is bad.\nWe want to go to the beach tomorrow, but we won’t go if the weather is bad.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n224\n</div>",
    exercises: [],
  },
  '113': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\neven ➜ Unit 112\nStudy this example situation:\nalthough \nthough \neven though\nin spite of \ndespite\nLast year Paul and Sarah had a holiday by the sea.\nIt rained a lot, but they had a good time.\nYou can say:\nAlthough it rained a lot, they had a good time.\n(= It rained a lot, but they …)\nor\nIn spite of\nDespite\nthe rain, they had a good time.\n⎫\n⎬\n⎭\nAft er although we use a subject + verb:\nAlthough it rained a lot, they had a good time.\nI didn’t apply for the job although I had the necessary qualifications.\nCompare the meaning of although and because:\nWe went out although it was raining heavily.\nWe didn’t go out because it was raining heavily.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nAft er in spite of or despite, we use a noun, a pronoun (this/that/what etc.) or -ing:\nIn spite of the rain, we had a good time.\nShe wasn’t well, but in spite of this she continued working.\nIn spite of what I said yesterday, I still love you.\nI didn’t apply for the job in spite of having the necessary qualifications.\nDespite is the same as in spite of.  We say in spite of, but despite (without of):\nShe wasn’t well, but despite this she continued working. (not despite of this)\nYou can say ‘in spite of the fact (that) …’ and ‘despite the fact (that) …’ :\nI didn’t apply for the job\nin spite of the fact (that)\ndespite the fact (that)\nI had the necessary qualifications.\nCompare in spite of and because of:\nWe went out in spite of the rain. (or … despite the rain.)\nWe didn’t go out because of the rain.\n⎧\n⎨\n⎩\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nCompare although and in spite of / despite:\nAlthough the traff ic was bad,\nIn spite of the traff ic,\nwe arrived on time.\n(not in spite of the traff ic was bad)\nI couldn’t sleep\nalthough I was very tired.\ndespite being very tired.\n(not despite I was tired)\n⎧\n⎨\n⎩\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nthough = although:\nI didn’t apply for the job though I had the necessary qualifications.\nIn spoken English we oft en use though at the end of a sentence:\nThe house isn’t so nice.  I like the garden though. (= but I like the garden)\nI see them every day.  I’ve never spoken to them though. (= but I’ve never spoken to them)\nEven though (but not ‘even’ alone) is similar to although:\nEven though I was really tired, I couldn’t sleep. (not even I was really tired)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n226\n</div>",
    exercises: [],
  },
  '114': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nStudy this example situation:\nSome more examples of in case:\nI’d better write down my password in case I forget it. \n(= because it is possible I will forget it)\nShall I draw a map for you in case you have a problem finding our house? \n(= because it is possible you will have problems finding it)\nI’ll remind them about the meeting in case they’ve forgotten. \n(= because it is possible they have forgotten)\nWe use just in case for a smaller possibility:\nI don’t think it will rain, but I’ll take an umbrella just in case. (= just in case it rains)\nWe do not use will aft er in case (see also Unit 25):\nI’ll write down my password in case I forget it. (not in case I will forget)\nin case\nYour car should have a spare wheel in case you have\na puncture.\n(= because it is possible you will have a puncture)\nin case something happens = \nbecause it is possible it will happen\nIn case and if are not the same.  We use in case to say why somebody does (or doesn’t do) something. \nYou do something now in case something happens later.\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nin case\nWe’ll buy some more food in case\nTom comes.\n(= Maybe Tom will come.  We’ll buy\nsome more food now, whether he comes\nor not.  Then we’ll already have the food\n \nif he comes.)\nI’ll give you my phone number in case\nyou need to contact me.\nYou should insure your bike in case it\nis stolen.\nif\nWe’ll buy some more food if Tom\n \ncomes.\n(= Maybe Tom will come.  If he comes,\nwe’ll buy some more food.  If he doesn’t\ncome, we won’t buy any more food.)\nYou can call me on this number if you\nneed to contact me.\nYou should inform the police if your\nbike is stolen.\nYou can use in case + past to say why somebody did something:\nI gave him my phone number in case he needed to contact me.\n(= because it was possible that he would need to contact me)\nI drew a map for Sarah in case she had a problem finding our house.\nWe rang the doorbell again in case they hadn’t heard it the first time.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nin case of = if there is … (especially on notices, instructions etc.):\nIn case of fire, please leave the building as quickly as possible. (= if there is a fire)\nIn case of emergency, call this number. (= if there is an emergency)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nif ➜ Units 25, 38–40\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\n228\n</div>",
    exercises: [],
  },
  '115': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nunless\nStudy this example situation:\nunless \n \nas long as \n \nprovided\nThe club is for members only.\nYou can’t go in unless you are a member.\nThis means:\nYou can’t go in except if you are a member.\nYou can go in only if you are a member.\nunless = except if \nSome more examples of unless:\nI’ll see you tomorrow unless I have to work late. \n(= except if I have to work late)\nThere are no buses to the beach.  Unless you have a car, it’s difficult to get there.\n(= except if you have a car)\na: Shall I tell Lisa what happened? \nB: Not unless she asks you. (= tell her only if she asks you)\nBen hates to complain. He wouldn’t complain about something unless it was really bad.\n(= except if it was really bad)\nWe can take a taxi to the restaurant – unless you’d prefer to walk. (= except if you’d\nprefer to walk)\nInstead of unless it is often possible to say if … not:\nUnless we leave now, we’ll be late.    or    If we don’t leave now, we’ll …\nas long as / so long as and provided / providing\nYou can say as long as or so long as (= if, on condition that):\nYou can borrow my car \nyou promise not to drive too fast.\n(= You can borrow my car, but you must promise not to drive too fast.  This is a condition.)\nYou can also say provided (that) or providing (that):\nTravelling by car is convenient \nyou have somewhere to park.\n(= It’s convenient but only if you have somewhere to park.)\n \nthe room is clean, I don’t mind which hotel we stay at.\n(= The room must be clean, but otherwise I don’t mind.)\nas long as \nso long as\n⎧\n⎨\n⎩\n⎫\n⎬\n⎭\nprovided (that) \nproviding (that)\n⎧\n⎨\n⎩\n⎫\n⎬\n⎭\nProviding (that) \nProvided (that)\n⎧\n⎨\n⎩\n⎫\n⎬\n⎭\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nunless / as long as etc. for the future\nWhen we are talking about the future, we do not use will after unless / as long as / so long as /\nprovided / providing.  We use a present tense (see Unit 25):\nI’m not going out unless it stops raining. (not unless it will stop)\nProviding the weather is good, we’re going to have a picnic tomorrow.  \n(not providing the weather will be good)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nif ➜ Units 25, 38–40\n230\n</div>",
    exercises: [],
  },
  '116': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nas … as ➜ Unit 107\nlike and as ➜ Unit 117\nas if ➜ Unit 118\nas = at the same time as\nYou can use as when two things happen together at the same time:\nWe all waved goodbye to Liz as she drove away.\n \n(we waved and she drove away at the same time)\nAs I walked along the street, I looked in the \nshop windows.\nCan you turn off  the light as you go out, please?\nOr you can say that something happened as you were doing\nsomething else (in the middle of doing something else):\nKate slipped as she was getting off  the bus.\n We met Paul as we were leaving the hotel.\nFor the past continuous (was getting / were going etc.), see Unit 6.\nYou can also use just as (= exactly at that moment):\nJust as I sat down, the doorbell rang.\nI had to leave just as the conversation was getting interesting.\nWe also use as when two things happen together in a longer period\nof time:\nAs the day went on, the weather got worse.\nI began to enjoy the job more as I got used to it.\nCompare as and when:\n  the weather got worse\n  the day went on\nas (as I walked … / as I was … etc.)\nWe use as only if two things happen at the \nsame time.\nAs I drove home, I listened to music.\n(= at the same time)\nUse when (not as) if one thing happens aft er \nanother.\nWhen I got home, I had something to eat.\n \n(not as I got home)\nDavid wasn’t in the off ice as he was on \nholiday. (= because he was on holiday)\nAs they lived near us, we used to see \nthem quite oft en.\n(= because they lived near us)\nDavid lost his passport when he was \non holiday.\n(= during the time he was away)\nWhen they lived near us, we used to \nsee them quite oft en.\n(= at the time they lived near us)\nas = because\nAs also means ‘because’:\nAs I was hungry, I decided to find somewhere to eat. \n(= because I was hungry)\nAs it’s late and we’re tired, let’s get a taxi home. (= because it’s late …)\nWe watched TV all evening as we didn’t have anything better to do.\nAs I don’t watch TV any more, I gave my television to a friend of mine.\nYou can also use since in this way:\nSince it’s late and we’re tired, let’s get a taxi home.\nCompare as (= because) and when:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nKATE\nLIZ\n232\n</div>",
    exercises: [],
  },
  '117': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nas … as ➜ Unit 107\nas (= at the same time as / because) ➜ Unit 116\nas if ➜ Unit 118\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nlike and as\nLike = similar to, the same as:\nWhat a beautiful house!  It’s like a palace. (not as a palace)\nBe careful!  The floor has been polished.  It’s like walking on ice. (not as walking)\nIt’s raining again.  I hate weather like this. (not as this)\n‘What’s that noise?’ \n‘It sounds like a baby crying.’   (not as a baby crying)\nIn these examples, like is a preposition.  So it is followed by a noun (like a palace), a pronoun  \n(like this) or -ing (like walking).  \nSometimes like = for example.  You can also use such as:\nI enjoy water sports, like surfing, scuba diving and water-skiing.   or \nI enjoy water sports, such as surfing …\nAs = in the same way as, in the same condition as. \nWe use as with subject (S) + verb (V):\nI didn’t move anything.  I left everything as it was.\nYou should have done it as I showed you.\nWe also use like in this way (+ subject + verb):\n I left everything like it was.\nCompare as and like.  You can say:\n You should have done it as I showed you.    or    … like I showed you.\nbut  \n You should have done it like this. (not as this)\nWe say as usual / as always:\nYou’re late as usual.\nAs always, Nick was the first to complain.\nWe say the same as … :\nYour phone is the same as mine. (not the same like)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nSometimes as (+ subject + verb) has other meanings.  For example, after do:\nYou can do as you like. (= do what you like)\nThey did as they promised. (= They did what they promised.)\nWe also say as you know / as I said / as she expected / as I thought etc. :\nAs you know, it’s Emma’s birthday next week. (= you know this already)\nAndy failed his driving test, as he expected. (= he expected this before)\nLike is not usual in these expressions, except with say (like I said):\nAs I said yesterday, I’m sure we can solve the problem.    or    Like I said yesterday …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nAs can also be a preposition (as + noun), but the meaning is different from like.  \nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nAs a taxi driver, I spend most of  \nmy working life in a car.  \n(I am a taxi driver, it’s my job.)\nEveryone in the family wants me to drive \nthem to places.  I’m like a taxi driver. \n(I’m not a taxi driver, but I’m like one.)\nAs (preposition) = in the position of, in the form of etc. :\nMany years ago I worked as a photographer. (I was a photographer)\nMany words, for example ‘work’ and ‘rain’, can be used as verbs or nouns.\nLondon is fine as a place to visit, but I wouldn’t like to live there.\nThe news of the tragedy came as a great shock.\nS  + V\nas  it     was\nas  I      showed\n234\n</div>",
    exercises: [],
  },
  '118': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nif I was/were ➜ Unit 39C\nlook/sound etc. + adjective ➜ Unit 99C\nlike and as ➜ Unit 117\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nWe use like or as if to say how somebody/something looks, sounds or feels:\nThat house looks like it’s going to fall down.    or\nThat house looks as if it’s going to fall down.\nAmy sounded like she had a cold, didn’t she?    or\nAmy sounded as if she had a cold, didn’t she?\nI’ve just had a holiday, but I feel very tired.\nI don’t feel like I’ve had a holiday.   or\nI don’t feel as if I’ve had a holiday.\nYou can also use as though in these examples:\nI don’t feel as though I’ve had a holiday.  \nCompare:\nYou look tired. (look + adjective)\nYou look like you haven’t slept.\n \nYou look as if you haven’t slept.\n(look like / as if + subject + verb)\n⎧\n⎨\n⎩\nlike \n \nas if\nWe say:  it looks like …    or    it looks as if …\nit sounds like …    or    it sounds as if …\nSarah is very late.  It looks like she isn’t coming.\nor  It looks as if she isn’t coming.\nIt looked like it was going to rain, so we took\nan umbrella.    \nor    It looked as if it was going to rain …\nThe noise is very loud next door. \nIt sounds like they’re having a party. \nor    It sounds as if they’re …\nYou can also use as though:\nIt sounds as though they’re having a party.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can use like / as if / as though with other verbs to say how somebody does something:\nHe ran like he was running for his life.\nAft er the interruption, the speaker went on talking as if nothing had happened.\nWhen I told them my plan, they looked at me as though I was mad.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nAft er as if, we sometimes use the past when we are talking about the present.\nFor example:\nI don’t like him.  He talks as if he knew everything.\nThe meaning is not past.  We use the past (as if he knew) because the idea is not real: he does not \nknow everything.  We use the past in the same way with if and wish (see Unit 39). \nWe do not normally use like in this way.\nSome more examples:\nShe’s always asking me to do things for her – as if I didn’t have enough to do already.\n \n(I have enough to do already)\nJoe’s only 40.  Why do you talk about him as if he was an old man? (he isn’t an old man)\nWhen you use the past in this way, you can use were instead of was:\nWhy do you talk about him as if he were an old man?\nThey treat me as if I were their own son.    or    … as if I was their own son.\n \n(I’m not their son)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nThat house looks like it’s \ngoing to fall down.\nIt sounds like they’re \nhaving a party next door.\n236\n</div>",
    exercises: [],
  },
  '119': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nfor and since ➜ Unit 12A\nwhile + -ing ➜ Unit 68B\nduring\nduring = at a time between the start and end of something:\nI fell asleep during the movie. (= at a time between\nthe start and end of the movie)\nWe met some really nice people during our holiday.\nThe ground is wet.  It must have rained during the night.\nWith ‘time words’ (the morning, the night, the summer etc.),\nyou can usually say in or during:\nIt rained in the night.    or    … during the night.\nIt’s lovely here during the summer.    or    … in the summer.\nduring    for   while\nI fell asleep during the movie.\nfor and during\nWe use for (+ a period of time) to say how long something goes on:\nWe watched TV for two hours last night.\nJess is going away for a week in September.\nHow are you?  I haven’t seen you for ages.\nAre you going away for the weekend?\nWe do not use during to say how long something goes on.  We do not say ‘during two hours’, \n‘during five years’ etc. :\nIt rained for three days without stopping. (not during three days)\nWe use during to say when something happens (not how long).  Compare during and for:\n‘When did you fall asleep?’ \n‘During the movie.’\n‘How long were you asleep?’ \n‘For half an hour.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nduring and while\nCompare:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSome more examples of while:\nWe saw Clare while we were waiting for the bus.\nWhile you were out, there was a phone \ncall for you.\nAlex read a book while Amy watched TV.\nWhen we are talking about the future, we use the present\naft er while.  Do not use ‘will’ (see Unit 25):\nI’m going to Moscow next week.  I hope the weather \nwill be good while I’m there. (not while I will be)\nWhat are you going to do while you’re waiting? \n(not while you’ll be waiting)\nAlex read a book while Amy \nwatched TV.\nWe use during + noun:\nI fell asleep during the movie.\nWe met a lot of interesting people\nduring our holiday.\nRobert suddenly began to feel ill\nduring the exam.\nWe use while + subject + verb:\nI fell asleep while I was watching TV.\nWe met a lot of interesting people\nwhile we were on holiday.\nRobert suddenly began to feel ill\nwhile he was doing the exam.\nnoun\nsubject + verb\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nALEX\nAMY\n238\n</div>",
    exercises: [],
  },
  '120': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nwill be doing and will have done ➜ Unit 24\nby (other uses) ➜ Units 42B, 60B, 128\nby … = not later than:\nby and until \nby the time …\nI sent the documents today, so they should arrive \nby Monday.\n(= on or before Monday, not later than Monday)\nWe’d better hurry.  We have to be home by 5 o’clock. \n(= at or before 5 o’clock, not later than 5 o’clock)\nWhere’s Sarah?  She should be here by now. \n(= now or before now – so she should already be here)\nThis milk has to be used \nby 14 August.\nWe use until (or till) to say how long a situation continues:\na: Shall we go now?\nB: No, let’s wait until it stops raining.    or    … till it stops raining.\n I was very tired this morning.\nCompare until and by:\nI stayed in bed until half past ten.\nI didn’t get up until half past ten.\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nYou can say ‘by the time something happens’:\nIt’s too late to go to the bank now.  By the time we get there, it will be closed.\n(= it will close between now and the time we get there)\nYou’ll need plenty of time at the airport.  By the time you check in and go through security, \nit will be time for your flight.\n(= check-in and security will take a long time)\nHurry up!  By the time we get to the cinema, the film will already have started.\nYou can say ‘by the time something happened’ (for the past):\nKaren’s car broke down on the way to the party last night.  By the time she arrived, most of the \nother guests had left .\n(= it took her a long time to get there and most of the guests left  during this time)\nI had a lot of work to do yesterday evening.  I was very tired by the time I finished.\n(= it took me a long time to do the work, and I became more and more tired)\nWe went to the cinema last night.  It took us a long time to find somewhere to park the car.  \nBy the time we got to the cinema, the film had already started.\nYou can say by then or by that time:\nKaren finally got to the party at midnight, but by then most of the other guests had left . \nor   … but by that time, most of the other guests had left .\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSomething continues until a time in the future:\nJoe will be away until Monday.\n(so he’ll be back on Monday)\nI’ll be working until 11.30.\n(so I’ll stop working at 11.30)\nSomething happens by a time in the future:\nJoe will be back by Monday.\n(= not later than Monday)\nI’ll have finished my work by 11.30.\n(= I’ll finish it not later than 11.30)\n240\n</div>",
    exercises: [],
  },
  '121': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nat/on/in (time)\nCompare at, on and in:\nThey arrived at 5 o’clock.\nThey arrived on Friday.\nThey arrived in June. / They arrived in 2012.\nWe use:\nat for the time of day\nat five o’clock \n \nat 11.45 \n \nat midnight \n \nat lunchtime \n \nat sunset \n \netc.\non for days and dates\non Friday / on Fridays \non 16 May 2012 \non New Year’s Day \non my birthday\nin for longer periods (months/years/seasons etc.)\nin June \n in 2012 \n in the 1990s \nin the 20th century \nin the past \nin winter\non/in time, at/in the end ➜ Unit 122\nin/at/on (position) ➜ Units 123–125\nin/at/on (other uses) ➜ Unit 127 \nAmerican English ➜ Appendix 7\nWe say:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nat the moment / at the minute / at present / at this time (= now):\nCan we talk later?  I’m busy at the moment.\nat the same time\nKate and I arrived at the same time.\nat the weekends / at weekends   (or  on the weekend / on weekends in American English):\nWill you be here at the weekend? (or  … on the weekend)\nat Christmas   (but on Christmas Day)\nDo you give each other presents at Christmas?\nat night (= during nights in general), in the night  (= during a particular night):\nI don’t like working at night.    but    I was woken up by a noise in the night.\nin the morning(s) \nbut \non Friday morning(s)\nin the afternoon(s)\non Sunday afternoon(s)\nin the evening(s)\non Monday evening(s) etc.\nI’ll see you in the morning. \nI’ll see you on Friday morning.\nDo you work in the evenings? \nDo you work on Saturday evenings?\nWe do not use at/on/in before last/next/this/every:\nI’ll see you next Friday. (not on next Friday)\nThey got married last June.\nWe often leave out on before days. So you can say:\nI’ll see you on Friday.    or    I’ll see you Friday.\nI don’t work on Monday mornings.    or    I don’t work Monday mornings.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe say that something will happen in a few minutes / in six months etc. :\nThe train will be leaving in a few minutes. (= a few minutes from now)\nAndy has gone away.  He’ll be back in a week. (= a week from now)\nThey’ll be here in a moment. (= a moment from now, very soon)\nWe also use in … to say how long it takes to do something:\nI learnt to drive in four weeks. (= it took me four weeks to learn)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\n242\n</div>",
    exercises: [],
  },
  '122': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nat/on/in (time) ➜ Unit 121\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\non time and in time      at the end and in the end\non time and in time\non time = punctual, not late\nIf something happens on time, it happens at the time that was planned:\nThe 11.45 train left on time. (= it left at 11.45)\nPlease be on time.  Don’t be late. \nThe conference was well-organised.  Everything began and finished on time.\nat the end (of something) = at the time when something ends\nFor example:\nat the end of the month \nat the end of January \nat the end of the game\nat the end of the film \nat the end of the course \nat the end of the concert\nI’m going away at the end of January / at the end of the month.\nAt the end of the concert, everyone applauded.\nThe players shook hands at the end of the game.\nWe do not say ‘in the end of …’ .  For example, we do not say ‘in the end of January’.\nThe opposite of at the end is at the beginning:\nI’m going away at the beginning of January. (not in the beginning)\nin time (for something / to do something) = soon enough\nWill you be home in time for dinner? (= soon enough for dinner)\nI sent Amy a birthday present.  I hope it arrives in time.  \n(= on or before her birthday)\nI’m in a hurry.  I want to get home in time to watch the game on TV.\n(= soon enough to see the game)\nThe opposite of in time is too late:\nI got home too late to watch the game on TV.\nYou can say just in time (= almost too late):\nWe got to the station just in time for our train.\nA child ran into the road in front of the car, but I managed to stop just in time.\nin the end = finally\nWe use in the end when we say what the final result of a situation was:\nWe had a lot of problems with our car.  We sold it in the end. (= finally we sold it)\nHe got more and more angry.  In the end he just walked out of the room.\nAlan couldn’t decide where to go for his holidays.  He didn’t go anywhere in the end.\n \n(not at the end)\nThe opposite of in the end is at first:\nAt first we didn’t get on very well, but in the end we became good friends.\nat the end and in the end\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\n244\n</div>",
    exercises: [],
  },
  '123': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nin/at/on (position) 2–3 ➜ Units 124–125\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nin/at/on  (position) 1\nin\nThere’s no-one in the room / in the building / in the garden.\nWhat do you have in your hand / in your mouth?\nWhen we were in Italy, we spent a few days in Venice.\nI have a friend who lives in a small village in the mountains.\nThere were some people swimming in the pool / in the sea / in the river.\nin a room\nin a building\nin a box\netc.\nin a garden\nin a town\nin the city centre\netc.\nin a pool\nin the sea\nin a river\netc.\nat\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWho is that man standing at the bus stop / at the door / at the window?\nTurn left  at the traff ic lights / at the next junction / at the roundabout / at the church. \nWe have to get off  the bus at the next stop. \nWhen you leave the hotel, please leave your key at reception. (= at the reception desk)\nCompare in and at:\nThere were a lot of people in the shop.  It was crowded. \nGo along this road, then turn left  at the shop.\nI’ll meet you in the hotel lobby. (= in the building)\nI’ll meet you at the entrance to the hotel. (= outside the building)\nat the bus stop \nat the door \nat the roundabout \nat her desk\nI sat on the floor / on the ground / on the grass / on the beach / on a chair.\nThere’s a dirty mark on the ceiling / on your nose / on your shirt.\nDid you see the notice on the wall / on the door?\nYou’ll find details of TV programmes on page seven of the newspaper.\nThe hotel is on a small island in the middle of a lake.\nCompare in and on:\nThere is some water in the bottle.\nThere is a label on the bottle.\nCompare at and on:\nThere is somebody at the door.  Shall I go and see who it is?\nThere is a notice on the door.  It says ‘Do not disturb’.\non\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\non the ceiling \non her nose\non the floor\n \non a page \non an island\nX\nX\nX\nX\nX\non the \nwall\non the door\non the table\nin the \nbottle\non the bottle\n246\n</div>",
    exercises: [],
  },
  '124': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nin/at/on  (position) 2\nWe say that somebody/something is: \nin a line, in a row, in a queue\nin a picture, in a photo(graph)\nin a newspaper, in a magazine, in a book\nin an off ice, in a department\nin the sky, in the world\nin th e country (= not in a town)\nWhen I go to the cinema, I like to sit in the front row.\nAmy works in the sales department.\nWho is the woman in that picture?\nDo you live in a city or in the country?\nIt’s a lovely day.  There isn’t a cloud in the sky.  \nWe say that somebody/something is:\non the left , on the right   (or on the left -hand side, on the right-hand side)\nDo you drive on the left  or on the right in your country?\non the ground floor, on the first floor, on the second floor etc.\nOur apartment is on the second floor of the building.\non a map, on a menu, on a list, on a page, on a website \nHere’s the shopping list.  Don’t buy anything that’s not on the list.\nYou’ll find the information you need on our website.\nWe say that a place is on a river / on a road / on the coast: \nVienna is on the (river) Danube. \n The town where you live – is it on the coast or is it inland?\nWe say on the way (from one place to another):\nWe stopped at a shop on the way home.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say:\nat the top (of …), at the bottom (of …), at the end (of …)\nWrite your name at the top of the page.\nJane lives at the other end of the street.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nWe say:\nin the front, in the back of a car\nI was in the back (of the car) when we had the accident.\nat the front, at the back of a building / theatre / group of people etc.\nThe garden is at the back of the house.\nLet’s sit at the front (of the cinema).\nWe were at the back, so we couldn’t see very well.\non the front, on the back of an envelope / a piece of paper etc.\nI wrote the date on the back of the photo.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nWe say:\nin the corner of a room\nThe TV is in the corner of the room.\nat the corner or on the corner of a street\nThere is a small shop at the corner (of the street).\nor   … on the corner (of the street). \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nin the world ➜ Unit 108D\nin/at/on (position) ➜ Units 123, 125\nAmerican English ➜ Appendix 7\nin the corner\nat or on the corner\nat the back\nat the front\nat the bottom (of the page)\nat the top (of the page)\nThey’re standing in a row.\n248\n</div>",
    exercises: [],
  },
  '125': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nin/at/on   (position) 3\nin hospital / at work etc.\nWe say that somebody is in bed / in hospital / in prison:\nJames isn’t up yet.  He’s still in bed.\nAnna’s mother is in hospital.\nWe say that somebody is at home / at work / at school / at university / at college:\nI’ll be at work until 5.30.\nMy sister is at university.  My brother is still at school.\nWe say be at home or be home (with or without at), but do something at home (with at):\nI’ll be home all evening.    or    I’ll be at home all evening.\nShall we go to a restaurant or eat at home?\nat a party / at a concert etc.\nWe say that somebody is at an event (at a party, at a conference etc.):\nWere there many people at the party / at the meeting / at the wedding?\nI saw Steve at a conference / at a concert on Saturday.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nin and at for buildings\nYou can often use in or at with buildings.  For example, you can eat in a restaurant or at a\nrestaurant; you can buy food in a supermarket or at a supermarket. \nWe usually say at when we say where an event takes place (a concert, a party, a meeting etc.):\nWe went to a concert at the National Concert Hall.\nThe meeting took place at the company’s head office in Frankfurt.\nThere was a robbery at the supermarket.\nWe say at somebody’s house:\n I was at Helen’s house last night.    or    I was at Helen’s last night.\nIn the same way we say at the doctor’s, at the hairdresser’s etc.\nWe use in when we are thinking about the building itself.  Compare at and in:\nI was at Helen’s (house) last night.\nIt’s always cold in Helen’s house.  The heating doesn’t work well. (not at Helen’s house)\nWe had dinner at the hotel.\nAll the rooms in the hotel have air conditioning. (not at the hotel)\nWe say at the station / at the airport:\nThere’s no need to meet me at the station.  I can get a taxi.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nin and at for towns etc.\nWe normally use in with cities, towns and villages:\nThe Louvre is a famous art museum in Paris. (not at Paris)\nSam’s parents live in a village in the south of France. (not at a village)\nWe use at when we think of the place as a point or station on a journey:\n Does this train stop at Oxford? (= at Oxford station)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\non a bus / in a car etc.\nWe usually say on a bus / on a train / on a plane / on a ship  but  in a car / in a taxi:\nThe bus was very full. There were too many people on it.\n Laura arrived in a taxi.\nWe say on a bike (= bicycle) / on a motorbike / on a horse:\nJane passed me on her bike.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nat school / in hospital etc. ➜ Unit 74\nin/at/on (position) ➜ Units 123–124\nto/at/in/into ➜ Unit 126 \nby car / by bike etc. ➜ Unit 128B\n250\n</div>",
    exercises: [],
  },
  '126': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nto, at, in and into\nWe say go/come/travel (etc.) to a place or event.  For example:\ngo to China\ngo back to Italy\nreturn to London\ngo to work\ngo to the bank\ngo to a party\ncome to my house\ndrive to the airport\nbe taken to hospital\nWhen are your friends going back to Italy? (not going back in Italy)\nThree people were injured in the accident and taken to hospital.\nIn the same way we say Welcome to … , a trip to … , a visit to … ,  on my way to … etc. :\nWelcome to our country! (not Welcome in)\nWe had to cancel our trip to Paris.\nCompare to (for movement) and in/at (for position):\nThey are going to France. \nbut \nThey live in France.\nCan you come to the party? \nbut \nI’ll see you at the party.\nWe say ‘(I’ve) been to’ a place or an event:\nI’ve been to Italy four times, but I’ve never been to Rome.\nAmanda has never been to a football match in her life.\nget and arrive\nWe say get to a place:\nThey got to the hotel at midnight.\nWhat time did you get to the party?\nWe say arrive in … or arrive at … (not arrive to).\nWe say arrive in a town or country:\nThey arrived in Madrid / in Spain a week ago.\nFor other places (buildings etc.) or events, we say arrive at:\nWhat time did you arrive at the hotel / at the airport / at the party?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nhome\nWe say: go home, come home, get home, arrive home, on the way home etc. (no preposition).\nWe do not say ‘to home’:\nWhat time did you get home? (not get to home)\nI met Lisa on my way home. \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\ninto\ngo into, get into … etc. = enter (a room / a building / a car etc.):\nI opened the door, went into the room and sat down.\nA bird flew into the kitchen through the window.\nEvery month my salary is paid directly into my bank account.\nWith some verbs (especially go/get/put) we often use in (instead of into):\nShe got in the car and drove away.    or    She got into the car …\nI read the letter and put it back in the envelope.\nThe opposite of into is out of:\nShe got out of the car and went into a shop.\nFor buses, trains and planes, we usually say get on and get off:\nShe got on the bus and I never saw her again.\nYou need to get off (the train) at the next station.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nbeen to ➜ Units 7–8\nin/at/on (position) ➜ Units 123–125\n at home ➜ Unit 125A \ninto and in ➜ Unit 138A\nTO\nINTO\n252\n</div>",
    exercises: [],
  },
  '127': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nin/at/on (time) ➜ Unit 121\nin/at/on (position) ➜ Units 123–125\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nin/on/at  (other uses)\nin\nin the rain / in the sun / in the shade / in the dark / in bad weather etc.\nWe sat in the shade.  It was too hot to sit in the sun.\nDon’t go out in the rain.  Wait until it stops.\nin a language / in a currency etc. \nHow do you say ‘thank you’ in Russian?\nHow much is a hundred pounds in dollars?\n(be/fall) in love (with somebody)\nThey’re very happy together.  They’re in love.\nin a (good/bad) mood\nYou seem to be in a bad mood.  What’s the matter?\nin (my) opinion\nIn my opinion the movie wasn’t very good.\nin the shade\non\non TV / on television\non the radio\non the phone\non fire\non purpose (= intentionally)\non the whole (= in general)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nI didn’t see the news on TV.\nI heard the weather forecast on the radio.\nI’ve never met her, but I’ve spoken to her on the phone.\nLook!  That car is on fire.\nI’m sorry.  I didn’t mean to hurt you.  I didn’t do it on purpose.\nSometimes I have problems at work, but on the whole I enjoy my job.\non holiday / on a trip etc.\n(be/go) on holiday / on vacation\n(be/go) on a trip / on a tour / on a cruise etc.\n(be/go to a place) on business\n(be/go) on strike\n(be/go) on a diet\nWe also say ‘go somewhere for a holiday’:\nSteve has gone to France for a holiday.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nat the age of … etc.\nat the age of 16 / at 90 miles an hour / \nat 100 degrees etc. :\nTracy left  school at 16.    or  \nTracy left  school at the age of 16.\nThe train was travelling at 120 miles an hour.\nWater boils at 100 degrees Celsius.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nI’m going on holiday next week.\nOne day I’d like to go on a world tour.\nEmma’s away on business at the moment.\nThere are no trains today.  The drivers are on strike.\nI’ve put on weight.  I’ll have to go on a diet.\nWe are now flying at a speed of \n800 kilometres an hour and at an \naltitude of 9,000 metres.\n254\n</div>",
    exercises: [],
  },
  '128': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nby\nYou can say that something happens by mistake / by accident / by chance:\nWe hadn’t arranged to meet.  We met by chance.\nBut we say ‘do something on purpose’ (= you mean to do it):\nI didn’t do it on purpose.  It was an accident.\nNote that we say by chance, by accident etc. (not by the chance / by an accident).  \nIn these expressions we use by + noun without the or a.\nWe use by … to say how somebody travels.  For example, you can travel:\nby car \nby train \nby plane \nby boat \nby ship \nby bus \nby bike  etc. \nJess usually goes to work by bus / by bike / by car.\nWe do not use by if we say my car / the train / a taxi etc.  We say:\nby car \nbut in my car   (not by my car)\nby train    but    on the train   (not by the train)\nWe use in for cars and taxis:\n They didn’t come in their car.  They came in a taxi.\nWe use on for bikes and public transport (buses, trains etc.):\nWe travelled on the 6.45 train, which arrived at 8.30.\nNote that we usually say on foot (not usually by foot):\nDid you come here by car or on foot?\nWe also use by to say how we do other things.  For example, you can:\nsend something by post \n \npay by card / by cheque \ndo something by hand\n Can I pay by credit card? \nBut note that we say pay cash or pay in cash (not usually by cash).\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nWe say that ‘something is done by …’ (passive):\nHave you ever been bitten by a dog?\nThe programme was watched by millions of people.\nCompare by and with:\nThe door must have been opened with a key. (not by a key)\n(= somebody used a key to open it)\nThe door must have been opened by somebody with a key.\nWe say: a play by Shakespeare, a painting by Rembrandt, a novel by Tolstoy etc. \nHave you read any poems by Shakespeare?\n‘Who is this painting by?  Picasso?’ \n‘I have no idea.’\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nBy also means ‘next to / beside’:\nThe light switch is by the door.\nCome and sit by me. (= next to me)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nYou can also use by… to show the diff erence between two things:\nClare’s salary has increased by ten per cent.\n(= it’s now ten per cent more than before) \nCarl won the race by five metres.\n(= he was five metres in front of the other runners) \n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nPassive + by ➜ Unit 42B\nby + -ing ➜ Unit 60B\nby myself ➜ Unit 83C\nby (time) ➜ Unit 120\nCARL\nLIGHT SWITCH\n256\n</div>",
    exercises: [],
  },
  '129': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nNoun + preposition  (reason for, cause of etc.)\nnoun + for …\na demand / a need FOR …\nThe company went out of business.  There was no demand for its product any more.\nThere’s no excuse for behaviour like that.  There’s no need for it.\na picture / a photo / a photograph / a map / a plan / a drawing (etc.) OF …\nRachel showed me some pictures of her family.\nI had a map of the town, so I was able to find my way around.\nan increase / a decrease / a rise / a fall IN (prices etc.)\nThere has been an increase in the number of road accidents recently.\nLast year was a bad one for the company.  There was a big fall in sales.\na relationship / a connection / contact WITH …\nDo you have a good relationship with your parents?\nThe police want to question a man in connection with the robbery.\na relationship / a connection / contact / a difference BETWEEN two things or people\nThe police believe that there is no connection between the two crimes.\nThere are some differences between British and American English.\nan advantage / a disadvantage OF …\nThe advantage of living alone is that you can do what you like.\nbut \nthere is an advantage IN doing something or TO doing something: \nThere are many advantages in living alone.    or … many advantages to living alone.\na solution TO a problem / a key TO a door / an answer TO a question / a reply TO a letter /  \na reaction TO something\nI hope we find a solution to the problem. (not a solution of the problem)\nI was surprised at her reaction to my suggestion.\na reason FOR …\nThe train was late, but nobody knew the reason for the delay. (not reason of)\na cause OF …\nThe cause of the explosion is unknown.\ndamage TO …\nThe accident was my fault, so I had to pay for the damage to the other car.\nan invitation TO … (a party / a wedding etc.)\nDid you get an invitation to the wedding?\nan attitude TO … or  an attitude TOWARDS …\nHis attitude to his job is very negative.    or    His attitude towards his job …\nnoun + of …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nnoun + in …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nnoun + with … / between …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nnoun + to …\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n258\n</div>",
    exercises: [],
  },
  '130': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAdjective + preposition 1\nnice of you, nice to me\nnice / kind / good / generous / polite / honest / stupid / silly etc. OF somebody (to do something)\nThank you.  It was very nice of you to help me.\nIt was stupid of me to go out without a coat in such cold weather.\n(be) nice / kind / good / generous / polite / rude / friendly / cruel etc. TO somebody\nThey have always been very nice to me. (not with me)\nWhy were you so unfriendly to Lucy?\npleased / satisfied / happy / delighted / disappointed WITH something you get or experience\nThey were delighted with the present I gave them.\nWere you happy with your exam results?\nsurprised / shocked / amazed / astonished / upset  AT / BY something\nEverybody was surprised at the news.    or    … by the news.\nI hope you weren’t shocked by what I said.    or    … at what I said.\nsorry ABOUT a situation or something that happened\nI’m sorry about the mess.  I’ll clear it up later.\nSorry about last night. (= Sorry about something that happened last night)\nsorry FOR / ABOUT something you did or caused\nI’m sorry for shouting at you yesterday. (or sorry about shouting)\n Sorry for the delay. (or Sorry about the delay)\nYou can also say ‘I’m sorry I (did something)’:\nI’m sorry I shouted at you yesterday.\nangry / annoyed / furious / upset ABOUT something\n \nWITH somebody FOR doing something\nThere’s no point in getting angry about things that don’t matter.\nAre you annoyed with me for being late?\nLisa is upset about not being invited to the party.\nadjective + about / with\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\n⎧\n⎨\n⎩\nexcited / worried / nervous / happy etc. ABOUT something\nAre you nervous about the exam?\nimpressed WITH / BY somebody/something\nI’m very impressed with (or by) her English.  It’s very good.\nfeel / be sorry FOR somebody in a bad situation\nI feel sorry for Mark.  He’s had a lot of bad luck. (not I feel sorry about Mark)\nfed up / bored WITH something\nI don’t enjoy my job any more.  I’m fed up with it. / I’m bored with it.\ntired OF something\nCome on, let’s go!  I’m tired of waiting. \nadjective + at / by / with / of\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nsorry about / for\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nPreposition + -ing ➜ Unit 60\nAdjective + to … ➜ Unit 65\nsorry to / sorry for … ➜ Unit 66C \nAdjective + preposition 2 ➜ Unit 131\n260\n</div>",
    exercises: [],
  },
  '131': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nAdjective + preposition 2\nadjective + of \nafraid / scared / frightened / terrified OF …\n‘Are you afraid of spiders?’ \n‘Yes, I’m terrified of them.’\ngood / bad / brilliant / better / hopeless etc. AT …\nI’m not very good at repairing things. (not good in repairing things)\nfond / proud / ashamed / jealous / envious OF …\n Why is he so jealous of other people?\nsuspicious / critical / tolerant OF …\nThey didn’t trust me.  They were suspicious of my motives.\naware / conscious OF …\n‘Did you know he was married?’ \n‘No, I wasn’t aware of that.’\ncapable / incapable OF …\nI’m sure you are capable of doing the job well.\ntypical OF …\nHe’s late again.  It’s typical of him to keep everybody waiting.\nsimilar TO …\nYour handwriting is similar to mine.\ndependent ON … (but independent OF …)\nI don’t want to be dependent on anybody.\ninterested IN …\nAre you interested in art?\nfamous FOR …\nThe Italian city of Florence is famous for its art treasures.\ncertain / sure OF or ABOUT …\nI think she’s arriving this evening, but I’m not sure of that.   or    …  not sure about that.\ndifferent FROM    or    different TO …\nThe film was different from what I’d expected.    or    … different to what I’d expected.\ncrowded WITH (people etc.)\nThe streets were crowded with tourists. (but … full of tourists)\nkeen ON …\nWe stayed at home.  Chris wasn’t keen on going out.\nresponsible FOR …\nWho was responsible for all that noise last night?\nfull / short OF …\nAmy is a very active person.  She’s always full of energy.\nI’m a bit short of money.  Can you lend me some?\nmarried / engaged TO …\n Louise is married to an American. (not married with)\nbut \nLouise is married with three children. (= she is married and has three children)\nadjective + at / to / from / in / on / with / for\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nPreposition + -ing ➜ Unit 60\nafraid of/to … ➜ Unit 66A\nAdjective + preposition 1 ➜ Unit 130 \nAmerican English ➜ Appendix 7\n262\n</div>",
    exercises: [],
  },
  '132': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition 1   to and at\nverb + to\ntalk / speak TO somebody (talk/speak with is also possible)\nWho were you talking to?\nlisten TO …\nWhen I’m driving, I like to listen to the radio. (not listen the radio)\nask somebody (a question)\nIf there’s anything you want to know, you can ask me. (not ask to me)\nlook / stare / glance AT …, have a look / take a look AT …\nWhy are you looking at me like that?\napologise TO somebody (for …)\nThey apologised to me for their mistake. (not apologised me)\nthank somebody (for …)\nHe thanked me for helping him. (not He thanked to me)\nlaugh AT …\nI look stupid with this haircut.  Everybody will laugh at me.\nexplain something TO somebody\n Can you explain this word to me? (not explain me this word)\nexplain / describe (to somebody) what/how/why …\nI explained to them why I was worried. (not I explained them)\nLet me describe to you what I saw. (not Let me describe you)\nphone somebody, ask somebody etc. (without to)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nverb + at\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSome verbs can be followed by at or to, with a difference in meaning.  For example:\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nphone / call / email / text somebody\n I called the airline to cancel my flight. (not called to the airline)\nBut we say ‘write (a letter) to somebody’.\naim / point (something) AT …, shoot / fire (a gun) AT …\nDon’t point that knife at me.  It’s dangerous.\nWe saw someone with a gun shooting at birds, but he didn’t hit any.\nanswer somebody/something\n You didn’t answer my email. (not answer to my email)\nBut we say reply to (an email / a letter etc.).\nshout AT somebody (when you are angry or aggressive)\n He got very angry and started shouting at me.\nshout TO somebody (so that they can hear you)\nHe shouted to me from the other side of the street.\nthrow something AT somebody/something (to hit them)\n Somebody threw an egg at the politician.\nthrow something TO somebody (for somebody to catch)\nLisa shouted ‘Catch!’ and threw the keys to me from the window.\nVerb + preposition 2–5 ➜ Units 133–136\nask for ➜ Unit 133B \napologise for / thank somebody for ➜ Unit 135B\nOther verbs + to ➜ Unit 136D\n264\n</div>",
    exercises: [],
  },
  '133': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerbs + about/of (think/hear etc.) ➜ Unit 134\nOther verbs + for ➜ Unit 135B\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition 2   about/for/of/after\nverb + about\ntalk / read / know ABOUT … \nWe talked about a lot of things at the meeting.\ndo something/nothing ABOUT something = do something/nothing to improve a situation\nIf you’re worried about the problem, you should do something about it.\napply (TO a company etc.) FOR a job etc.\nI think you could do this job.  Why don’t you apply for it?\nsearch (a person / a place / a bag etc.) FOR …\nI’ve searched the house for my keys, but I still can’t find them.\nlook FOR … = search for, try to find\nI’ve lost my keys.  Can you help me to look for them?\nleave (a place) FOR another place\nI haven’t seen her since she left (home) for work. (not left to work)\nhave a discussion ABOUT something\n We had a discussion about what we should do.\nBut we say ‘discuss something’ (no preposition):\nWe discussed what we should do. (not discussed about)\nask (somebody) FOR …\n I sent an email to the company asking them for more information about the job.\nBut we say ‘ask somebody the way / the time’ etc. (no preposition):\nI asked somebody the way to the station.\ncare FOR somebody = take care of them, keep them safe\n Alan is 85 and lives alone.  He needs somebody to care for him.\nI don’t care FOR something = I don’t like it\nI don’t care for hot weather. (= I don’t like …)\ncare ABOUT … = think that somebody/something is important\n He’s very selfish.  He doesn’t care about other people.\ncare what/where/how … etc. (without about)\nYou can do what you like.  I don’t care what you do.\nverb + for\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\ntake care of, care for and care about\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nlook for and look after\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nwait FOR somebody, wait FOR something (to happen)\nDon’t wait for me.  I’ll join you later.\nI’m not going out yet.  I’m waiting for the rain to stop.\ntake care OF … = look after, keep safe, take responsibility for\nDon’t worry about me.  I can take care of myself.\nI’ll take care of the travel arrangements.  You don’t need to do anything.\nlook AFTER … = take care of, keep safe or in good condition\nAlan is 85 and lives alone.  He needs somebody to look after him. (not look for)\nYou can borrow this book, but please look after it.\n266\n</div>",
    exercises: [],
  },
  '134': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition 3   about and of\nhear ABOUT … = be told about something\nDid you hear about the fire at the hotel?\nSometimes the difference is very small and you can use of or about:\nWhen I’m alone, I often think of you.    or    … think about you.\nYou can say think of or think about doing something (for possible future actions):\nMy sister is thinking of going to Canada.    or     … thinking about going …\ndream ABOUT … (when you are asleep)\nI dreamt about you last night.\ncomplain (TO somebody) ABOUT … = say that you are not satisfied\nWe complained to the manager of the restaurant about the food.\nremind somebody ABOUT … = tell somebody not to forget\nIt’s good you reminded me about the meeting.  I’d completely forgotten about it.\ncomplain OF a pain, an illness etc. = say that you have a pain etc.\nWe called the doctor because George was complaining of a pain in his stomach.\ndream OF/ABOUT being something / doing something = imagine\nDo you dream of being rich and famous?    or    … dream about being rich …\nI wouldn’t dream OF doing something = I would never do it\n‘Don’t tell anyone what I said.’ \n‘No, I wouldn’t dream of it.’\nhear OF … = know that somebody/something exists\na: Who is Tom Hart? \nB: I have no idea.  I’ve never heard of him. (not heard from him)\nhear FROM … = be in contact with somebody\na: Have you heard from Jane recently? \nB: Yes, she called me a few days ago.\nremind somebody OF … = cause somebody to remember\nThis house reminds me of the one I lived in when I was a child.\nLook at this photograph of Richard.  Who does he remind you of?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nC\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nE\nthink ABOUT something =  consider it, concentrate your mind on it:\nI’ve thought about what you said and I’ve decided to take your advice.\na: Will you lend me the money? \nB: I’ll think about it. (not think of it)\nthink OF something = produce an idea:\nIt was my idea.  I thought of it first. (not thought about it)\n I felt embarrassed.  I couldn’t think of anything to say. (not think about anything)\nWe also use think of when we ask for or give an opinion:\na: What did you think of the movie? \nB: I didn’t think much of it. (= I didn’t like it much)\nremind somebody to … ➜ Unit 55B\n268\n</div>",
    exercises: [],
  },
  '135': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nVerb + preposition + -ing ➜ Unit 62\nOther verbs + for ➜ Unit 133\nOther verbs + on ➜ Unit 136E\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition 4   of/for/from/on\nverb + of\naccuse / suspect somebody OF …\nTina accused me of being selfish.\nSome students were suspected of cheating in the exam.\ncongratulate / compliment somebody ON …\nI congratulated her on doing so well in her exams.\nThe meal was really good.  I complimented Mark on his cooking skills.\napprove / disapprove OF …\nHis parents don’t approve of what he does, but they can’t stop him.\ndie OF or die FROM an illness etc.\n‘What did he die of?’ \n‘A heart attack.’\nthank / forgive somebody FOR …\nI’ll never forgive them for what they did.\nsuffer FROM an illness etc.\nThere’s been an increase in the number of people suffering from heart disease.\nprotect somebody/something FROM …\nSun cream protects the skin from the sun.\nlive ON money/food\nMichael’s salary is very low.  It isn’t enough to live on.\nconsist OF …\nWe had an enormous meal.  It consisted of seven courses.\napologise (TO somebody) FOR …\nWhen I realised I was wrong, I apologised (to them) for my mistake.\nverb + for\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nverb + from\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nverb + on\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\npay (somebody) FOR …\n We didn’t have enough money to pay for the meal. (not pay the meal)\nBut we say ‘pay a bill / a fine / a fee / tax / rent / a sum of money’ etc. (no preposition)\nWe didn’t have enough money to pay the rent.\nblame somebody/something FOR … , somebody is to blame FOR …\nEverybody blamed me for the accident.\n Everybody said that I was to blame for the accident.\nblame (a problem etc.) ON …\nIt wasn’t my fault.  Don’t blame it on me.\ndepend ON … ,  rely ON …\nI don’t know what time we’ll arrive.  It depends on the traffic.\nYou can rely on Anna.  She always keeps her promises.\nYou can use depend + when/where/how etc. with or without on:\n‘Are you going to buy it?’ \n‘It depends how much it is.’   (or ‘It depends on how much …’)\n270\n</div>",
    exercises: [],
  },
  '136': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nVerb + preposition 5    in/into/with/to/on\nverb + in\nbelieve IN … = believe that something exists, believe that it’s good to do something\nDo you believe in God? (= do you believe that God exists?)\n I believe in saying what I think. (= I believe it is right to say what I think)\nbut ‘believe something’ (= believe that it is true), ‘believe somebody’ (= believe what they say):\nThe story can’t be true.  I don’t believe it. (not believe in it)\nspecialise IN …\nHelen is a lawyer.  She specialises in company law.\nbreak INTO …\nOur house was broken into a few days ago, but nothing was stolen.\ncollide WITH …\nThere was an accident this morning.  A bus collided with a car.\nhappen TO …\nWhat happened to that gold watch you used to have? (= where is it now?)\nconcentrate ON …\nI tried to concentrate on my work, but I kept thinking about other things.\ndivide / cut / split something INTO two or more parts\nThe book is divided into three parts.\nprovide / supply somebody WITH …\nThe school provides all its students with books.\nprefer one thing TO another\n I prefer tea to coffee.\nspend (money) ON …\nHow much do you spend on food each week?\nsucceed IN …\nI hope you succeed in finding the job you want.\ncrash / drive / bump / run INTO …\nHe lost control of the car and crashed into a wall.\nfill something WITH … (but full of – see Unit 131A)\nTake this saucepan and fill it with water.\ninvite somebody TO a party / a wedding etc.\nThey only invited a few people to their wedding.\ninsist ON …\nI wanted to go alone, but some friends of mine insisted on coming with me.\ntranslate a book etc. FROM one language INTO another\nShe’s a famous writer.  Her books have been translated into many languages.\nverb + into\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nverb + with\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nverb + to\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nverb + on\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">E</h3>\nVerb + preposition + -ing ➜ Unit 62\nOther verbs + to ➜ Unit 132\nOther verbs + on ➜ Unit 135D\n272\n</div>",
    exercises: [],
  },
  '137': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPhrasal verbs 2–9 ➜ Units 138–145\nAmerican English ➜ Appendix 7\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 1     Introduction\nWe often use verbs with:\nin\nout\non\noff\nup\ndown\naway\nback\nby\nthrough\nabout\nalong\nover\nforward\nround or around\nSo you can say look out / get on / take off / run away etc.  These are phrasal verbs.\nWe often use on/off/out etc. with verbs of movement.  For example:\nget on\ndrive off\ncome back\nturn round\nThe bus was full.  We couldn’t get on.\nA woman got into the car and drove off.\nSarah is leaving tomorrow and coming back on Saturday.\nWhen I touched him on the shoulder, he turned round.\nOften the second word (on/off/out etc.) gives a special meaning to the verb.  For example:\nbreak down\nfind out\ntake off\ngive up\nget on\nget by\nSorry I’m late.  The car broke down. (= the engine stopped working)\nI never found out who sent me the flowers. (= I never discovered)\nIt was my first flight.  I was nervous as the plane took off. (= went into the air)\nI tried many times to contact her.  In the end I gave up. (=  stopped trying)\nHow was the exam?  How did you get on? (= How did you do?)\nMy French isn’t good, but it’s enough to get by. (= enough to manage)\nFor more phrasal verbs, see Units 138–145.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nSometimes a phrasal verb is followed by a preposition.  For example:\nphrasal verb\nlook up\nrun away\nkeep up\nlook forward\npreposition\nat\nfrom\nwith\nto\nWe looked up at the plane as it flew above us.\nWhy did you run away from me?\nYou’re walking too fast.  I can’t keep up with you.\nAre you looking forward to your trip?\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nSometimes a phrasal verb has an object.  For example:\n I turned on the light. (the light is the object)\nUsually there are two possible positions for the object.  You can say:\nI turned on the light.    or    I turned the light on.\nobject \nobject\nBut if the object is a pronoun (it/them/me/him etc.), only one position is possible:\nI turned it on. (not I turned on it)\nIn the same way, you can say:  \ntake off my shoes.\nI’m going to take my shoes off.\nbut \nThese shoes are uncomfortable.  I’m going to take them off. (not take off them)\nwake up the baby.\nDon’t wake the baby up.\nbut \nThe baby is asleep.  Don’t wake her up. (not wake up her)\nthrow away this box.\nDon’t throw this box away.\nbut \nI want to keep this box, so don’t throw it away. (not throw away it)\n⎧\n⎨\n⎩\n⎧\n⎨\n⎩\n⎧\n⎨\n⎩\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\n274\n</div>",
    exercises: [],
  },
  '138': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 2   in/out\nCompare in and out:\nin = into a room, a building, a car etc.\nHow did the thieves get in?\nHere’s a key, so you can let yourself in.\nLisa walked up to the edge of the pool\n \nand dived in. (= into the water)\nI’ve got a new apartment.  I’m moving in\non Friday.\nAs soon as I got to the airport, I \nchecked in.\nIn the same way you can say go in, come in, \nwalk in, break in etc.\nCompare in and into:\nI’m moving in on Friday.\nI’m moving into my new flat on Friday\nout = out of a room, a building, a car etc.\nStay in the car.  Don’t get out.\nI had no key, so I was locked out.\nShe swam up and down the pool,\nand then climbed out.\nAndy opened the window and\nlooked out.\nWe paid the hotel bill and \nchecked out.\nIn the same way you can say go out,\nget out, move out, let somebody out etc.\nCompare out and out of:\nShe climbed out.\nShe climbed out of the pool.\nOther verbs + in\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nOther verbs + out\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nfill in or fill out a form, a questionnaire etc. = write the necessary information on a form\nPlease fill in the application form and send it to us by 28 February.   or\nPlease fill out the application form …\ndrop in = visit somebody at home without arranging to do this\nI dropped in to see Chris on my way home.\neat out = eat at a restaurant, not at home\nThere wasn’t anything to eat at home, so we decided to eat out.\ndrop out of college / university / a course / a race = stop before you have completely finished\nGary went to university but dropped out aft er a year.\nget out of something that you arranged to do = avoid doing it\nI promised I’d go to the wedding. I don’t want to go, but I can’t get out of it now.\nleave something out = omit it, not include it\nIn the sentence ‘She said that she was ill’, you can leave out the word ‘that’.\ncross something out = write a line through something\nSome of the names on the list had been crossed out. \njoin in = take part in something that is already going on\nThey were playing cards, so I joined in.\ntake somebody in = deceive somebody\nThe man said he was a policeman and I believed him. I was completely taken in.\nplug in an electrical machine = connect it to the electricity supply\nThe fridge isn’t working because you haven’t plugged it in.\n Sarah  \nCROSS OUT\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + out ➜ Unit 139\nPLUG IN\n276\n</div>",
    exercises: [],
  },
  '139': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 3 \nout\nout = not burning, not shining\ngo out\nput out a fire / a cigarette / a light\nturn out a light\nblow out a candle\nSuddenly all the lights in the building went out.\nI put the fire out with a fire extinguisher.\nI turned the lights out before leaving.\nWe don’t need the candle.  You can blow it out.\nwork out\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nOther verbs + out\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nwork out = do physical exercises\nRachel works out at the gym three times a week.\nwork out = develop, progress\nGood luck for the future.  I hope everything works out well for you.\na: Why did James leave the company?\nB: Things didn’t work out. (= things didn’t work out well)\nwork out (for calculations):\n The total bill for three people is £97.35.  That works out at £32.45 each.\nwork (something) out = calculate\n345 × 76?  I need a calculator.  I can’t work it out in my head.\nwork out or figure out = understand, think about a problem and find an answer\nInvestigators are trying to work out what caused the accident.    or    \nInvestigators are trying to figure out what caused the accident.\ncarry out an order / an experiment / a survey / an investigation / a plan etc.\nSoldiers are expected to carry out orders.\nAn investigation into the accident will be carried out.\npoint something out (to somebody) = draw attention to it\nAs we drove through the city, the tour guide pointed out all the sights.\nI didn’t realise I’d made a mistake until somebody pointed it out to me.\nsort something out = find a solution to, put in order\nThere are a few problems we need to sort out.\nAll these papers are mixed up.  I’ll have to sort them out.\nfind out that/what/when (etc.) … , find out about … = get information about\nThe police never found out who committed the crime.\nI just found out that it’s Helen’s birthday today.\nI checked a few websites to find out about hotels in the town.\nturn out to be … / turn out good/nice etc. / turn out that …\n  Nobody believed Paul at first, but he turned out to be right. (= it became clear in the\nend that he was right)\nThe weather wasn’t so good in the morning, but it turned out nice later.\nI thought they knew each other, but it turned out that they’d never met.\ngive/hand things out = give to each person\nAt the end of the lecture, the speaker gave out information sheets to the audience.\nrun out (of something)\nWe ran out of petrol on the motorway. (= we used all our petrol)\ntry out a machine, a system, a new idea etc. = test it to see if it is OK\nThe company is trying out some new software at the moment.\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + out ➜ Unit 138\n278\n</div>",
    exercises: [],
  },
  '140': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + on/off ➜ Unit 141\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 4     on/off (1)\non and off for lights, machines etc.\nWe say:\nthe light is on / put the light on / leave the light on etc.\nturn the light on/off    or    switch the light on/off\nShall I leave the lights on or turn them off?\n‘Is the heating on?’ \n‘No, I switched it off.’\nalso\nput (music, a song) on, put the kettle on:\nLet’s put some music on.  What would you like to hear? \nWe need boiling water, so I’ll put the kettle on.\non and off for events etc.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\non and off for clothes etc.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\noff = away from a person or place\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nput something off, put off doing something = delay it\nThe election has been put off until January.\nWe can’t put off making a decision.  We have to decide now.\nbe off (to a place)\nTomorrow I’m off to Paris. / I’m off on holiday.\n(= I’m going to Paris / I’m going on holiday)\nwalk off / run off / drive off / ride off / go off  (similar to walk away / run away etc.)\nAnna got on her bike and rode off.\nMark left home at the age of eighteen and went off to Canada.\nput on clothes, glasses, make-up, a seat belt etc.\nMy hands were cold, so I put my gloves on.\nput on weight = get heavier\nI’ve put on two kilos in the last month.\ngo on = happen\nWhat’s all that noise?  What’s going on? (= what’s happening)\ntry on clothes (to see if they fit)\nI tried on a jacket in the shop, but it didn’t look right.\ntake off clothes, glasses etc.\nIt was warm, so I took off my coat.\nset off = start a journey\nWe set off early to avoid the traffic. (= We left early)\ntake off = leave the ground (for planes)\nAfter a long delay, the plane finally took off.\nsee somebody off = go with them to the airport/station to say goodbye\nHelen was going away.  We went to the station with her to see her off.\ncall something off = cancel it\nThe concert in the park had to be called off because of the weather.\n280\n</div>",
    exercises: [],
  },
  '141': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 5 on/oﬀ (2)\nverb + on = continue doing something\ngo on = continue\nThe party went on until 4 o’clock in the morning.\nkeep on doing (or keep doing) something = do it continuously or repeatedly\n He keeps on criticising me.  It’s not fair! (or He keeps criticising me.)\ndrive on / walk on / play on = continue driving/walking/playing etc.\nShall we stop at this petrol station or shall we drive on to the next one?\ndoze off / drop off / nod off = fall asleep\nI dozed off during the lecture.  It was very boring.\ngo off = make an alarm sound\nDid you hear the alarm go off?\nshow off = try to impress people with your ability, your knowledge etc.\nLook at that boy on the bike riding with no hands.  He’s just showing off.\ntell somebody off = speak angrily to somebody because they did something wrong\nClare’s mother told her off for wearing dirty shoes in the house.\ngo on / carry on doing something = continue doing it\nWe can’t go on spending money like this.  We’ll have nothing left soon.\nI don’t want to carry on working here.  I’m going to look for another job.\ngo on with / carry on with something = continue it\nDon’t let me disturb you.  Please carry on with what you’re doing.\nfinish something off = do the last part of it\na: Have you finished painting the kitchen?\nb: Nearly.  I’ll finish it off tomorrow.\nrip somebody off / be ripped off  = cheat somebody / be cheated\nDid you really pay £2,000 for that painting?  I think you were ripped off.\n(= you paid too much)\nput somebody off (doing) something so that they don’t want it or want to do it any more\nWe wanted to go to the exhibition, but we were put off by the long queue. \n(= we didn’t go because of the long queue)\nWhat put you off applying for the job?  Was the salary too low?\nget on = progress\nHow are you getting on in your new job? (= How is it going?)\nget on (with somebody) = have a good relationship\nJoanne and Karen don’t get on.  They’re always arguing.\nRichard gets on well with his neighbours.  They’re all very friendly.\nget on with something = continue something you have to do, usually after an interruption\nI must get on with my work.  I have a lot to do.\nget on\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nverb + off\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\ngo on / carry on / keep on ➜ Unit 53B\nPhrasal verbs 1 (Introduction) ➜ Unit 137 \nMore verbs + on/off ➜ Unit 140\nAmerican English → Appendix 7\n282\n</div>",
    exercises: [],
  },
  '142': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + up ➜ Units 143–144\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 6 up/down\nCompare up and down:\nput something up (on a wall etc.)\nI put a picture up on\nthe wall.\npick something up\nThere was a letter on the floor.\n \nI picked it up and looked at it.\nstand up\nAlan stood up and walked out.\nturn something up\nI can’t hear the TV.  Can you\n \nturn it up a bit?\ntake something down (from a wall etc.)\nI didn’t like the picture, so I took\n \nit down.\nput something down\nI stopped writing and put down\nmy pen.\nsit down / bend down / lie down\nI bent down to tie my shoelace.\nturn something down\nThe oven is too hot.  Turn it down\nto 150 degrees.\nknock down, cut down etc.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\ndown = getting less\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nOther verbs + down\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nburn down = be destroyed by fire\nThey were able to put out the fire before the house burnt down.\nslow down = go more slowly\nYou’re driving too fast.  Slow down.\ncalm (somebody) down = become calmer, make somebody calmer\nCalm down.  There’s no point in getting angry.\ncut down (on something) = eat, drink or do something less often\nI’m trying to cut down on coffee.  I drink too much of it.\nclose down / shut down = stop doing business\nThere used to be a shop at the end of the street.  It closed down a few years ago.\nlet somebody down = disappoint them because you didn’t do what they hoped\nYou can always rely on Paul.  He’ll never let you down.\nwrite something down = write something on paper because you may need the information later\nI can’t remember Ben’s address.  I wrote it down, but I can’t find it.\nknock down a building / blow something down / cut something down etc.\nSome old houses were knocked down to make way for the new shopping centre.\nWhy did you cut down the tree in your garden?\nbe knocked down (by a car etc.)\nA man was knocked down by a car and taken to hospital.\nbreak down = stop working (for machines, cars, relationships etc.)\nThe car broke down and I had to phone for help.\nTheir marriage broke down after only a few months.\nturn somebody/something down = refuse an application, an offer etc.\nI applied for several jobs, but I was turned down for all of them.\nRachel was offered the job, but she decided to turn it down.\n284\n</div>",
    exercises: [],
  },
  '143': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + up ➜ Units 142, 144\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 7 \nup (1)\ngo up, come up, walk up (to …) = approach\nA man came up to me in the street and asked me for money.\nset up an organisation, a company, a business, a system, a website etc. = start it\nThe government has set up a committee to investigate the problem.\ngrow up = become an adult\nAmy was born in Hong Kong but grew up in Australia.\nclean up, clear up, tidy up = make something clean, tidy etc.\nLook at this mess!  Who’s going to tidy up? (or … to tidy it up)\ntake up a hobby, a sport, an activity etc. = start doing it\nLaura took up photography a few years ago.  She takes really good pictures.\nbring up a child = raise, look after a child\nHer parents died when she was a child and she was brought up by her grandparents.\nwash up = wash the plates, dishes etc. after a meal\nI hate washing up. (or I hate doing the washing-up.)\ntake up space or time = use space or time\nMost of the space in the room was taken up by a large table.\nturn up, show up = arrive, appear\nWe arranged to meet David last night, but he didn’t turn up.\nuse something up = use all of it so that nothing is left\nI’m going to make soup.  We have a lot of vegetables and I want to use them up.\nfix up a meeting etc. = arrange it\nWe’ve fixed up a meeting for next Monday.\ncatch up (with somebody), catch somebody up = move faster than people in front of you\nso that you reach them\nI’m not ready to go yet.  You go on and I’ll catch up with you / I’ll catch you up.\nend up somewhere, end up doing something etc.\nThere was a fight in the street and three men ended up in hospital.  \n(= that’s what happened to these men in the end)\nI couldn’t find a hotel and ended up sleeping on a bench at the station. \n(= that’s what happened to me in the end)\nmake up something, be made up of something\nChildren under 16 make up half the population of the city.  \n(= half the population are children under 16)\nAir is made up mainly of nitrogen and oxygen. (= Air consists of …)\nkeep up (with somebody) = continue at the same speed or level\nYou’re walking too fast.  I can’t keep up (with you).\nYou’re doing well.  Keep it up!\ngive up = stop trying, give something up = stop doing it\nDon’t give up.  Keep trying!\nSue got bored with her job and decided to give it up. (= stop doing it)\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nC\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\nE\n286\n</div>",
    exercises: [],
  },
  '144': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 8     up (2)\nbring up a topic etc. = introduce it in a conversation\nI don’t want to hear any more about this.  Please don’t bring it up again.\nmake something up = invent something that is not true\nWhat Kevin told you about himself wasn’t true.  He made it all up.\nsave up for something / to do something = save money to buy something\nDan is saving up for a trip to New Zealand.\ntear something up = tear it into pieces\nI didn’t read the letter.  I just tore it up and threw it away.\nbreak up, split up (with somebody) = separate\nI’m surprised to hear that Kate and Paul have split up.  They seemed very happy together.\ndo up a coat, a shoelace, buttons etc. = fasten, tie etc.\nIt’s quite cold.  Do up your coat before you go out.\ndo up a building, a room etc. = repair and improve it\nThe kitchen looks great now that it has been done up.\nlook something up in a dictionary/encyclopaedia etc.\nIf you don’t know the meaning of a word, you can look it up (in a dictionary).\nput up with something = tolerate a difficult situation or person\nWe live on a busy road, so we have to put up with a lot of noise from the traffic.\nclear up = become bright (for weather)\nIt was raining when I got up, but it cleared up later.\nbeat somebody up = hit someone repeatedly so that they are badly hurt\nA friend of mine was attacked and beaten up.  He had to go to hospital. \ncome up = be introduced in a conversation\nSome interesting things came up in our discussion yesterday.\ncome up with an idea, a suggestion etc. = produce an idea\nSarah is very creative.  She’s always coming up with new ideas.\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nC\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">D</h3>\ncheer up = be happier, cheer somebody up = make somebody feel happier\nYou look so sad!  Cheer up!\nHelen is depressed.  What can we do to cheer her up?\nblow up = explode, blow something up = destroy it with a bomb etc.\nThe engine caught fire and blew up.\nThe bridge was blown up during the war.\nhold up a person, a plan etc. = delay\nDon’t wait for me.  I don’t want to hold you up.\nPlans to build a new factory have been held up because of financial problems.\nmix up people/things, get people/things mixed up = you think one is the other\nThe two brothers look very similar.  People often mix them up.  \nor … People often get them mixed up.\nPhrasal verbs 1 (Introduction) ➜ Unit 137\nMore verbs + up ➜ Units 142–143\nAmerican English ➜ Appendix 7\n288\n</div>",
    exercises: [],
  },
  '145': {
    theory: "<div class=\"grammar-theory\" style=\"white-space: pre-wrap; font-family: sans-serif; line-height: 1.6;\">\nPhrasal verbs 1 (Introduction) ➜ Unit 137\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">A</h3>\nPhrasal verbs 9    away/back\nCompare away and back:\naway = away from home\nWe’re going away on holiday today.\naway = away from a place, a person etc.\nSarah got into her car, started the engine  \nand drove away.\nI tried to take a picture of the bird, but \nit flew away.\nI dropped the ticket, and it blew away  \nin the wind.\nThe police searched the house and  \ntook away a computer.\nIn the same way you can say:\nwalk away, run away, look away etc.\nback = back home\nWe’ll be back in three weeks.\nback = back to a place, a person etc.\na:  I’m going out now. \nb:  What time will you be back?\nAfter eating at a restaurant, we  \nwalked back to our hotel.\nI’ve still got Jane’s keys.  I forgot to  \ngive them back to her.\nWhen you’ve finished with that book, \ncan you put it back on the shelf?\nIn the same way you can say:\ngo back, come back, get back,\ntake something back etc.\nOther verbs + away\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">B</h3>\nOther verbs + back\n<h3 class=\"text-xl font-bold mt-6 mb-2 text-primary\">C</h3>\nkeep away (from …) = don’t go near\nKeep away from the edge of the pool.  You might fall in.\ngive something away = give it to somebody else because you don’t want it any more\n‘Did you sell your bike?’ \n‘No, I gave it away to a friend.’\nput something away = put it in the place where it is usually kept\nWhen the children finished playing with their toys, they put them away.\nthrow something away = put it in the rubbish\nI kept the letter, but I threw away the envelope.\nthrow something away = put it in the rubbish\n I kept the letter, but I threw away the envelope.\nwave back / smile back / shout back / hit somebody back\nI waved to her, and she waved back.\ncall/phone/ring (somebody) back = return a phone call\nI can’t talk to you now.  I’ll call you back in ten minutes.\nget back to somebody = reply to them by phone etc.\nI sent him an email, but he never got back to me.\nget away = escape, leave with difficulty\nWe tried to catch the thief, but she got away.\nget away with something = do something wrong without being caught\nI parked in a no-parking zone, but I got away with it.  I didn’t have to pay a fine.\nlook back (on something) = think about what happened in the past\nMy first job was in a travel agency.  I didn’t like it much at the time but, looking back on it,\nI learnt a lot and it was a useful experience.\npay back money, pay somebody back\nIf you borrow money, you have to pay it back.\nThanks for lending me the money.  I’ll pay you back next week.\n290\n</div>",
    exercises: [],
  },
};

